import java.util.Map;

/** POJO types shared by the tests of this package. */
final class TestPojos {

    private TestPojos() {}

    /** A simple POJO using only Flink-supported field types. */
    public static class SimplePojo {
        public String name;
        public int age;

        public SimplePojo() {}

        public SimplePojo(String name, int age) {
            this.name = name;
            this.age = age;
        }
    }

    /** A POJO with all of the primitive field types. */
    public static class WidePojo {
        public String text;
        public boolean flag;
        public byte tiny;
        public short small;
        public int integer;
        public long big;
        public float single;
        public double decimal;

        public WidePojo() {}
    }

    /** A POJO with nested POJO, list and map fields. */
    public static class CompoundPojo {
        public SimplePojo child;
        public List<String> tags;
        public Map<String, Integer> counts;

        public CompoundPojo() {}
    }

    /** Base type used for exercising the registered subclass wire format. */
    public static class BasePojo {
        public String baseField;

        public BasePojo() {}
    }

    /** A registered subclass that is itself a valid POJO. */
    public static class RegisteredSubPojo extends BasePojo {
        public int subField;

        public RegisteredSubPojo() {}
    }

    /**
     * A registered subclass that is deliberately not an analyzable POJO: it has a private field
     * with a getter but no setter, so Flink falls back to Kryo for it.
     */
    public static class NonPojoSubPojo extends BasePojo {
        private final String payload = "kryo";

        public NonPojoSubPojo() {}

        public String getPayload() {
            return payload;
        }
    }
}
