import org.junit.jupiter.api.Test;

import java.io.EOFException;
import java.io.IOException;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for {@link PojoToRowDataDeserializer}. */
class PojoToRowDataDeserializerTest {

    @Test
    void testDeserializePojoIntoRowData() throws Exception {
        TypeSerializer<SimplePojo> serializer = pojoSerializer(SimplePojo.class);
        PojoToRowDataDeserializer deserializer = PojoToRowDataDeserializer.create(snapshot(serializer));

        RowData row = deserializer.deserialize(input(serialize(serializer, new SimplePojo("Alice", 42))));

        assertThat(row).isInstanceOf(GenericRowData.class);
        assertThat(row.getArity()).isEqualTo(2);
        assertThat(row.getString(0)).isEqualTo(StringData.fromString("Alice"));
        assertThat(row.getInt(1)).isEqualTo(42);
    }

    @Test
    void testDeserializeMultipleConsecutiveRows() throws Exception {
        TypeSerializer<SimplePojo> serializer = pojoSerializer(SimplePojo.class);
        PojoToRowDataDeserializer deserializer = PojoToRowDataDeserializer.create(snapshot(serializer));

        DataOutputSerializer out = new DataOutputSerializer(64);
        serializer.serialize(new SimplePojo("first", 1), out);
        serializer.serialize(new SimplePojo("second", 2), out);
        DataInputView in = input(out.getCopyOfBuffer());

        assertThat(deserializer.deserialize(in).getString(0))
                .isEqualTo(StringData.fromString("first"));
        assertThat(deserializer.deserialize(in).getString(0))
                .isEqualTo(StringData.fromString("second"));
    }

    @Test
    void testDeserializeNullPojoReturnsNull() throws Exception {
        TypeSerializer<SimplePojo> serializer = pojoSerializer(SimplePojo.class);
        PojoToRowDataDeserializer deserializer = PojoToRowDataDeserializer.create(snapshot(serializer));

        DataInputView in = input(serialize(serializer, null));

        assertThat(deserializer.deserialize(in)).isNull();
    }

    @Test
    void testDeserializePojoWithNullFields() throws Exception {
        TypeSerializer<SimplePojo> serializer = pojoSerializer(SimplePojo.class);
        PojoToRowDataDeserializer deserializer = PojoToRowDataDeserializer.create(snapshot(serializer));

        RowData row = deserializer.deserialize(input(serialize(serializer, new SimplePojo(null, 0))));

        assertThat(row.isNullAt(0)).isTrue();
        assertThat(row.getInt(1)).isZero();
    }

    @Test
    void testDeserializeAllPrimitiveFieldTypes() throws Exception {
        TypeSerializer<TestPojos.WidePojo> serializer = pojoSerializer(TestPojos.WidePojo.class);
        PojoToRowDataDeserializer deserializer = PojoToRowDataDeserializer.create(snapshot(serializer));

        TestPojos.WidePojo pojo = new TestPojos.WidePojo();
        pojo.text = "text";
        pojo.flag = true;
        pojo.tiny = 1;
        pojo.small = 2;
        pojo.integer = 3;
        pojo.big = 4L;
        pojo.single = 5.5f;
        pojo.decimal = 6.5d;

        RowData row = deserializer.deserialize(input(serialize(serializer, pojo)));

        assertThat(row.getString(0)).isEqualTo(StringData.fromString("text"));
        assertThat(row.getBoolean(1)).isTrue();
        assertThat(row.getByte(2)).isEqualTo((byte) 1);
        assertThat(row.getShort(3)).isEqualTo((short) 2);
        assertThat(row.getInt(4)).isEqualTo(3);
        assertThat(row.getLong(5)).isEqualTo(4L);
        assertThat(row.getFloat(6)).isEqualTo(5.5f);
        assertThat(row.getDouble(7)).isEqualTo(6.5d);
    }

    @Test
    void testDeserializeNestedPojoListAndMap() throws Exception {
        TypeSerializer<CompoundPojo> serializer = pojoSerializer(CompoundPojo.class);
        PojoToRowDataDeserializer deserializer = PojoToRowDataDeserializer.create(snapshot(serializer));

        CompoundPojo pojo = new CompoundPojo();
        pojo.child = new SimplePojo("Bob", 7);
        pojo.tags = List.of("a", "b");

        Map<String, Integer> counts = new LinkedHashMap<>();
        counts.put("x", 1);
        counts.put("y", 2);
        pojo.counts = counts;

        RowData row = deserializer.deserialize(input(serialize(serializer, pojo)));

        RowData child = (RowData) row.getField(0);
        assertThat(child.getString(0)).isEqualTo(StringData.fromString("Bob"));
        assertThat(child.getInt(1)).isEqualTo(7);

        GenericArrayData tags = (GenericArrayData) row.getField(1);
        assertThat(tags.size()).isEqualTo(2);
        assertThat(tags.getString(0)).isEqualTo(StringData.fromString("a"));
        assertThat(tags.getString(1)).isEqualTo(StringData.fromString("b"));

        GenericMapData countsData = (GenericMapData) row.getField(2);
        assertThat(countsData.size()).isEqualTo(2);
        assertThat(countsData.get(StringData.fromString("x"))).isEqualTo(1);
        assertThat(countsData.get(StringData.fromString("y"))).isEqualTo(2);
    }

    @Test
    void testDeserializeRegisteredSubclassUsesSubclassFieldLayout() throws Exception {
        SerializerConfigImpl config = new SerializerConfigImpl();
        config.registerPojoType(RegisteredSubPojo.class);
        TypeSerializer<BasePojo> serializer = pojoSerializer(BasePojo.class, config);

        RegisteredSubPojo subclass = new RegisteredSubPojo();
        subclass.baseField = "base";
        subclass.subField = 99;

        PojoToRowDataDeserializer deserializer = PojoToRowDataDeserializer.create(snapshot(serializer));
        RowData row = deserializer.deserialize(input(serialize(serializer, subclass)));

        // The registered subclass has its own field layout: (baseField, subField).
        assertThat(row.getArity()).isEqualTo(2);
        assertThat(row.getString(0)).isEqualTo(StringData.fromString("base"));
        assertThat(row.getInt(1)).isEqualTo(99);
    }

    @Test
    void testDeserializeUnknownSubclassTagFails() throws Exception {
        TypeSerializer<BasePojo> serializer = pojoSerializer(BasePojo.class);
        PojoToRowDataDeserializer deserializer = PojoToRowDataDeserializer.create(snapshot(serializer));

        // No registered subclasses, so tag 0 is out of range.
        DataInputView in = input(new byte[] {PojoSerializer.IS_TAGGED_SUBCLASS, 0});

        assertThatThrownBy(() -> deserializer.deserialize(in))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("registered POJO subclass at tag 0")
                .hasMessageContaining("1 registered");
    }

    @Test
    void testDeserializeRegisteredSubclassWithoutPojoSnapshotFails() throws Exception {
        SerializerConfigImpl config = new SerializerConfigImpl();
        config.registerPojoType(NonPojoSubPojo.class);
        TypeSerializer<BasePojo> serializer = pojoSerializer(BasePojo.class, config);

        PojoToRowDataDeserializer deserializer = PojoToRowDataDeserializer.create(snapshot(serializer));
        DataInputView in = input(new byte[] {PojoSerializer.IS_TAGGED_SUBCLASS, 0});

        assertThatThrownBy(() -> deserializer.deserialize(in))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("tag 0")
                .hasMessageContaining("not a POJO serializer");
    }

    @Test
    void testDeserializeNonRegisteredSubclassFailsBecauseKryoBytesCannotBeSkipped() throws Exception {
        TypeSerializer<SimplePojo> serializer = pojoSerializer(SimplePojo.class);
        PojoToRowDataDeserializer deserializer = PojoToRowDataDeserializer.create(snapshot(serializer));

        DataOutputSerializer out = new DataOutputSerializer(64);
        out.writeByte(PojoSerializer.IS_SUBCLASS);
        out.writeUTF("com.example.UnknownSubclass");

        assertThatThrownBy(() -> deserializer.deserialize(input(out.getCopyOfBuffer())))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("POJO subclass 'com.example.UnknownSubclass'")
                .hasMessageContaining("Kryo");
    }

    @Test
    void testDeserializeUnrecognizedFlagsFails() throws Exception {
        TypeSerializer<SimplePojo> serializer = pojoSerializer(SimplePojo.class);
        PojoToRowDataDeserializer deserializer = PojoToRowDataDeserializer.create(snapshot(serializer));

        DataInputView in = input(new byte[] {0x10});

        assertThatThrownBy(() -> deserializer.deserialize(in))
                .isInstanceOf(IOException.class)
                .hasMessageContaining("Unrecognised POJO flags byte: 0x10");
    }

    @Test
    void testFailedFieldConversionOnlyNullsThatField() throws Exception {
        LogicalType rawType = new RawType<>(Integer.class, IntSerializer.INSTANCE);
        PojoToRowDataDeserializer deserializer =
                new PojoToRowDataDeserializer(
                        new TypeSerializer<?>[] {IntSerializer.INSTANCE, IntSerializer.INSTANCE},
                        new LogicalType[] {rawType, new IntType()},
                        new String[] {"unconvertible", "count"},
                        Collections.emptyList());

        DataOutputSerializer out = new DataOutputSerializer(16);
        out.writeByte(PojoSerializer.NO_SUBCLASS);
        out.writeBoolean(false);
        out.writeInt(11);
        out.writeBoolean(false);
        out.writeInt(9);

        RowData row = deserializer.deserialize(input(out.getCopyOfBuffer()));

        assertThat(row.isNullAt(0)).isTrue();
        assertThat(row.getInt(1)).isEqualTo(9);
    }

    @Test
    void testTruncatedFieldFailsLoudly() throws Exception {
        PojoToRowDataDeserializer deserializer =
                new PojoToRowDataDeserializer(
                        new TypeSerializer<?>[] {IntSerializer.INSTANCE},
                        new LogicalType[] {new IntType()},
                        new String[] {"count"},
                        Collections.emptyList());

        DataOutputSerializer out = new DataOutputSerializer(8);
        out.writeByte(PojoSerializer.NO_SUBCLASS);
        out.writeBoolean(false);
        out.writeByte(1);

        DataInputView in = input(out.getCopyOfBuffer());

        assertThatThrownBy(() -> deserializer.deserialize(in)).isInstanceOf(EOFException.class);
    }

    @Test
    void testCreateFailsWhenFieldSnapshotIsMissing() throws Exception {
        TypeSerializer<SimplePojo> serializer = pojoSerializer(SimplePojo.class);
        DataOutputSerializer out = new DataOutputSerializer(256);
        TypeSerializerSnapshot.writeVersionedSnapshot(out, serializer.snapshotConfiguration());

        // Refuse to resolve the snapshot class of the 'age' field, which makes the field snapshot
        // unreadable while the rest of the POJO snapshot stays intact.
        ClassLoader loader =
                filteringClassLoader(
                        "org.apache.flink.api.common.typeutils.base.IntSerializer$IntSerializerSnapshot");
        @SuppressWarnings("unchecked")
        PojoSerializerSnapshot<SimplePojo> degradedSnapshot =
                (PojoSerializerSnapshot<SimplePojo>)
                        TypeSerializerSnapshot.readVersionedSnapshot(
                                input(out.getCopyOfBuffer()), loader);

        assertThatThrownBy(() -> PojoToRowDataDeserializer.create(degradedSnapshot))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("'age'")
                .hasMessageContaining("serializer snapshot was not readable");
    }

    @Test
    void testSerializerProperties() throws Exception {
        TypeSerializer<SimplePojo> serializer = pojoSerializer(SimplePojo.class);
        PojoToRowDataDeserializer deserializer = PojoToRowDataDeserializer.create(snapshot(serializer));

        assertThat(deserializer.isImmutableType()).isFalse();
        assertThat(deserializer.getLength()).isEqualTo(-1);
        assertThat(deserializer.duplicate()).isSameAs(deserializer);
        assertThat(deserializer.createInstance().getArity()).isEqualTo(2);

        RowData row = GenericRowData.of(StringData.fromString("x"), 1);
        assertThat(deserializer.copy(row)).isSameAs(row);
        assertThat(deserializer.copy(row, row)).isSameAs(row);
    }

    @Test
    void testWriteOperationsAreNotSupported() throws Exception {
        PojoToRowDataDeserializer deserializer =
                PojoToRowDataDeserializer.create(
                        snapshot(pojoSerializer(SimplePojo.class)));
        DataOutputSerializer out = new DataOutputSerializer(16);

        assertThatThrownBy(() -> deserializer.serialize(GenericRowData.of(), out))
                .isInstanceOf(UnsupportedOperationException.class)
                .hasMessageContaining("read-only");
        assertThatThrownBy(
                        () ->
                                deserializer.copy(
                                        input(serialize(pojoSerializer(SimplePojo.class), new SimplePojo("a", 1))),
                                        out))
                .isInstanceOf(UnsupportedOperationException.class)
                .hasMessageContaining("read-only");
    }

    @Test
    void testSnapshotConfigurationWrapsTheLiveDeserializer() throws Exception {
        TypeSerializer<SimplePojo> serializer = pojoSerializer(SimplePojo.class);
        PojoSerializerSnapshot<SimplePojo> pojoSnapshot = snapshot(serializer);
        PojoToRowDataDeserializer deserializer = PojoToRowDataDeserializer.create(pojoSnapshot);

        TypeSerializerSnapshot<RowData> snapshot = deserializer.snapshotConfiguration();

        assertThat(snapshot).isInstanceOf(PojoDeserializerCompatibilitySnapshot.class);
        assertThat(snapshot.restoreSerializer()).isSameAs(deserializer);
        assertThat(((PojoDeserializerCompatibilitySnapshot<?>) snapshot).resolveSchemaCompatibility(pojoSnapshot))
                .matches(compatibility -> compatibility.isCompatibleAsIs());
    }

    @Test
    void testEqualsAndHashCode() throws Exception {
        TypeSerializer<SimplePojo> serializer = pojoSerializer(SimplePojo.class);
        PojoSerializerSnapshot<SimplePojo> snapshot = snapshot(serializer);

        PojoToRowDataDeserializer first = PojoToRowDataDeserializer.create(snapshot);
        PojoToRowDataDeserializer second = PojoToRowDataDeserializer.create(snapshot);
        PojoToRowDataDeserializer different =
                new PojoToRowDataDeserializer(
                        new TypeSerializer<?>[] {IntSerializer.INSTANCE},
                        new LogicalType[] {new IntType()},
                        new String[] {"other"},
                        Collections.emptyList());

        assertThat(first).isEqualTo(second).hasSameHashCodeAs(second);
        assertThat(first).isEqualTo(first);
        assertThat(first).isNotEqualTo(different);
        assertThat(first).isNotEqualTo("not-a-deserializer");
    }

    // ------------------------------------------------------------------------
    //  Helpers
    // ------------------------------------------------------------------------

    static <T> TypeSerializer<T> pojoSerializer(Class<T> clazz) {
        return pojoSerializer(clazz, new SerializerConfigImpl());
    }

    static <T> TypeSerializer<T> pojoSerializer(Class<T> clazz, SerializerConfigImpl config) {
        TypeSerializer<T> serializer =
                TypeExtractor.createTypeInfo(clazz).createSerializer(config);
        assertThat(serializer).isInstanceOf(PojoSerializer.class);
        return serializer;
    }

    @SuppressWarnings("unchecked")
    static <T> PojoSerializerSnapshot<T> snapshot(TypeSerializer<T> serializer) {
        TypeSerializerSnapshot<T> snapshot = serializer.snapshotConfiguration();
        assertThat(snapshot).isInstanceOf(PojoSerializerSnapshot.class);
        return (PojoSerializerSnapshot<T>) snapshot;
    }

    static <T> byte[] serialize(TypeSerializer<T> serializer, T value) throws IOException {
        DataOutputSerializer out = new DataOutputSerializer(64);
        serializer.serialize(value, out);
        return out.getCopyOfBuffer();
    }

    static DataInputView input(byte[] bytes) {
        return new DataInputDeserializer(bytes);
    }

    /** A class loader that refuses to resolve the given class name. */
    static ClassLoader filteringClassLoader(String unresolvableClassName) {
        return new ClassLoader(PojoToRowDataDeserializerTest.class.getClassLoader()) {
            @Override
            protected Class<?> loadClass(String name, boolean resolve)
                    throws ClassNotFoundException {
                if (unresolvableClassName.equals(name)) {
                    throw new ClassNotFoundException(name);
                }
                return super.loadClass(name, resolve);
            }
        };
    }
}
