import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for {@link PojoDeserializerCompatibilitySnapshot}. */
class PojoDeserializerCompatibilitySnapshotTest {

    @Test
    void testCurrentVersion() {
        assertThat(new PojoDeserializerCompatibilitySnapshot<>().getCurrentVersion()).isEqualTo(1);
    }

    @Test
    void testRestoreSerializerWithoutWrappedSerializerFails() {
        PojoDeserializerCompatibilitySnapshot<Object> snapshot =
                new PojoDeserializerCompatibilitySnapshot<>();

        assertThatThrownBy(snapshot::restoreSerializer)
                .isInstanceOf(UnsupportedOperationException.class)
                .hasMessageContaining("cannot reconstruct the deserializer")
                .hasMessageContaining("PojoToRowDataDeserializer.create()");
    }

    @Test
    void testRestoreSerializerReturnsWrappedSerializer() {
        TypeSerializer<SimplePojo> serializer =
                PojoToRowDataDeserializerTest.pojoSerializer(SimplePojo.class);
        PojoDeserializerCompatibilitySnapshot<SimplePojo> snapshot =
                new PojoDeserializerCompatibilitySnapshot<>(serializer);

        assertThat(snapshot.restoreSerializer()).isSameAs(serializer);
    }

    @Test
    void testCompatibleAsIsWithPojoSerializerSnapshot() {
        TypeSerializer<SimplePojo> serializer =
                PojoToRowDataDeserializerTest.pojoSerializer(SimplePojo.class);
        PojoDeserializerCompatibilitySnapshot<SimplePojo> snapshot =
                new PojoDeserializerCompatibilitySnapshot<>(serializer);

        assertThat(snapshot.resolveSchemaCompatibility(serializer.snapshotConfiguration()))
                .matches(compatibility -> compatibility.isCompatibleAsIs());
    }

    @Test
    void testCompatibleAsIsWithSameSnapshotType() {
        TypeSerializer<SimplePojo> serializer =
                PojoToRowDataDeserializerTest.pojoSerializer(SimplePojo.class);
        PojoDeserializerCompatibilitySnapshot<SimplePojo> snapshot =
                new PojoDeserializerCompatibilitySnapshot<>(serializer);
        PojoDeserializerCompatibilitySnapshot<SimplePojo> otherSnapshot =
                new PojoDeserializerCompatibilitySnapshot<>(serializer);

        assertThat(snapshot.resolveSchemaCompatibility(otherSnapshot))
                .matches(compatibility -> compatibility.isCompatibleAsIs());
    }

    @Test
    @SuppressWarnings({"unchecked", "rawtypes"})
    void testIncompatibleWithUnrelatedSnapshotType() {
        PojoDeserializerCompatibilitySnapshot snapshot =
                new PojoDeserializerCompatibilitySnapshot<>(IntSerializer.INSTANCE);

        assertThat(snapshot.resolveSchemaCompatibility(IntSerializer.INSTANCE.snapshotConfiguration()))
                .matches(compatibility -> compatibility.isIncompatible());
    }

    @Test
    void testWriteSnapshotWritesNothing() throws Exception {
        PojoDeserializerCompatibilitySnapshot<Object> snapshot =
                new PojoDeserializerCompatibilitySnapshot<>();
        DataOutputSerializer out = new DataOutputSerializer(8);

        snapshot.writeSnapshot(out);

        assertThat(out.length()).isZero();
    }

    @Test
    void testReadSnapshotIsNoOp() throws Exception {
        PojoDeserializerCompatibilitySnapshot<Object> snapshot =
                new PojoDeserializerCompatibilitySnapshot<>();

        snapshot.readSnapshot(42, new DataInputDeserializer(new byte[0]), getClass().getClassLoader());

        assertThat(snapshot.getCurrentVersion()).isEqualTo(1);
    }
