                PojoToRowDataDeserializerTest.filteringClassLoader(SimplePojo.class.getName());

        CustomRestoreSerializerFactory.set(MissingClassSerializerFactory::create);
        try {
            PojoSerializerSnapshot<SimplePojo> snapshot =
                    readSnapshot(snapshotBytes, classLoader);

            assertThat(snapshot.isPojoClassAvailable()).isFalse();
            assertThat(snapshot.getPojoClassName()).isEqualTo(SimplePojo.class.getName());

            TypeSerializer<?> created = MissingClassSerializerFactory.create(snapshot);
            assertThat(created).isInstanceOf(PojoToRowDataDeserializer.class);

            RowData row = created.deserialize(input(recordBytes));
            assertThat(row.getInt(0)).isEqualTo(42);
            assertThat(row.getString(1)).isEqualTo(StringData.fromString("Alice"));
        } finally {
            CustomRestoreSerializerFactory.remove();
        }

        assertThat(CustomRestoreSerializerFactory.get()).isNull();
    }

    @Test
    void testEnumClassCanBeMissingWhenFactoryIsRegistered() throws Exception {
        EnumSerializer<Color> enumSerializer = new EnumSerializer<>(Color.class);
        DataOutputSerializer records = new DataOutputSerializer(32);
        enumSerializer.serialize(Color.BLUE, records);

        byte[] snapshotBytes = writeSnapshot(enumSerializer);
        ClassLoader classLoader =
                PojoToRowDataDeserializerTest.filteringClassLoader(Color.class.getName());

        CustomRestoreSerializerFactory.set(MissingClassSerializerFactory::create);
        try {
            TypeSerializerSnapshot<Color> snapshot = readSnapshot(snapshotBytes, classLoader);
            TypeSerializer<?> created = MissingClassSerializerFactory.create(snapshot);

            assertThat(created).isInstanceOf(EnumNameDeserializer.class);
            assertThat(created.deserialize(input(records.getCopyOfBuffer()))).isEqualTo("BLUE");
        } finally {
            CustomRestoreSerializerFactory.remove();
        }
    }

    @Test
    void testReadingMissingClassFailsWithoutRegisteredFactory() throws Exception {
        byte[] snapshotBytes = writeSnapshot(pojoSerializer(SimplePojo.class));
        ClassLoader classLoader =
                PojoToRowDataDeserializerTest.filteringClassLoader(SimplePojo.class.getName());

        DataInputView in = input(snapshotBytes);

        assertThatThrownBy(() -> TypeSerializerSnapshot.readVersionedSnapshot(in, classLoader))
                .isInstanceOf(NoClassDefFoundError.class)
                .hasMessageContaining(SimplePojo.class.getName());
    }

    // ------------------------------------------------------------------------
    //  Helpers
    // ------------------------------------------------------------------------

    private static <T> byte[] writeSnapshot(TypeSerializer<T> serializer) throws IOException {
        DataOutputSerializer out = new DataOutputSerializer(256);
        TypeSerializerSnapshot.writeVersionedSnapshot(out, serializer.snapshotConfiguration());
        return out.getCopyOfBuffer();
    }

    private static <T> TypeSerializerSnapshot<T> readSnapshot(
            byte[] snapshotBytes, ClassLoader classLoader) throws IOException {
        return TypeSerializerSnapshot.readVersionedSnapshot(input(snapshotBytes), classLoader);
    }

    @SuppressWarnings("unchecked")
    private static EnumSerializer.EnumSerializerSnapshot<Color> readBackSnapshot(
            EnumSerializer<Color> serializer) throws IOException {
        return (EnumSerializer.EnumSerializerSnapshot<Color>)
                readSnapshot(writeSnapshot(serializer), MissingClassSerializerFactoryTest.class.getClassLoader());
    }
}
