package org.apache.flink.formats.avro.typeutils;

import org.apache.flink.api.common.typeutils.TypeSerializer;
import org.apache.flink.api.common.typeutils.TypeSerializerSnapshot;
import org.apache.flink.core.memory.DataInputDeserializer;
import org.apache.flink.core.memory.DataOutputSerializer;

import org.apache.avro.generic.GenericData;
import org.apache.avro.generic.GenericRecord;
import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for {@link AvroSerializer}. */
class AvroSerializerTest {

    @Test
    void testGenericRecordRoundTripAndSerializerProperties() throws Exception {
        AvroSerializer<GenericRecord> serializer =
                new AvroSerializer<>(GenericRecord.class, AvroTestFixtures.GENERIC_SCHEMA);

        assertThat(serializer.getType()).isEqualTo(GenericRecord.class);
        assertThat(serializer.isImmutableType()).isFalse();
        assertThat(serializer.getLength()).isEqualTo(-1);
        assertThat(serializer.toString())
                .isEqualTo(AvroSerializer.class.getName() + " (org.apache.avro.generic.GenericRecord)");

        GenericData.Record input = AvroTestFixtures.genericRecord("alice", 42, 1.5d);
        GenericRecord output = roundTrip(serializer, input);

        assertThat(output).isInstanceOf(GenericData.Record.class);
        assertThat(output.get("name").toString()).isEqualTo("alice");
        assertThat(output.get("age")).isEqualTo(42);
        assertThat(output.get("score")).isEqualTo(1.5d);
        assertThat(output.getSchema()).isEqualTo(AvroTestFixtures.GENERIC_SCHEMA);
    }

    @Test
    void testGenericRecordRequiresExplicitSchema() {
        assertThatThrownBy(() -> new AvroSerializer<>(GenericRecord.class))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("explicit schema");

        assertThatThrownBy(() -> new AvroSerializer<>(AvroTestFixtures.ReflectivePojo.class,
                        AvroTestFixtures.GENERIC_SCHEMA))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("without explicit schema");

        assertThatThrownBy(() -> new AvroSerializer<>(null))
                .isInstanceOf(NullPointerException.class);
        assertThatThrownBy(() -> new AvroSerializer<>(GenericRecord.class, null))
                .isInstanceOf(NullPointerException.class);
    }

    @Test
    void testReflectivePojoRoundTrip() throws Exception {
        AvroSerializer<AvroTestFixtures.ReflectivePojo> serializer =
                new AvroSerializer<>(AvroTestFixtures.ReflectivePojo.class);

        AvroTestFixtures.ReflectivePojo output =
                roundTrip(serializer, new AvroTestFixtures.ReflectivePojo("bob", 7));

        assertThat(output.name).isEqualTo("bob");
        assertThat(output.age).isEqualTo(7);
    }

    @Test
    void testSpecificRecordRoundTripAndSnapshot() throws Exception {
        AvroSerializer<AvroTestFixtures.SpecificPojo> serializer =
                new AvroSerializer<>(AvroTestFixtures.SpecificPojo.class);

        AvroTestFixtures.SpecificPojo input = new AvroTestFixtures.SpecificPojo("carol", 19);
        AvroTestFixtures.SpecificPojo output = roundTrip(serializer, input);

        assertThat(output.name.toString()).isEqualTo("carol");
        assertThat(output.age).isEqualTo(19);

        TypeSerializerSnapshot<AvroTestFixtures.SpecificPojo> snapshot =
                serializer.snapshotConfiguration();
        assertThat(snapshot).isInstanceOf(AvroSerializerSnapshot.class);
        assertThat(((AvroSerializerSnapshot<AvroTestFixtures.SpecificPojo>) snapshot).getSchema())
                .isEqualTo(AvroTestFixtures.SpecificPojo.SCHEMA);
        assertThat(serializer.snapshotConfiguration()).isSameAs(snapshot);
    }

    @Test
    void testCreateInstanceAndCopyForGenericRecord() throws Exception {
        AvroSerializer<GenericRecord> serializer =
                new AvroSerializer<>(GenericRecord.class, AvroTestFixtures.GENERIC_SCHEMA);

        GenericRecord empty = serializer.createInstance();
        assertThat(empty.getSchema()).isEqualTo(AvroTestFixtures.GENERIC_SCHEMA);
        assertThat(empty.get("name")).isNull();
        assertThat(empty.get("age")).isNull();

        GenericData.Record original = AvroTestFixtures.genericRecord("dave", 3, null);
        GenericRecord copy = serializer.copy(original);
        assertThat(copy).isNotSameAs(original);
        assertThat(copy).isEqualTo(original);

        original.put("name", "changed");
        assertThat(copy.get("name").toString()).isEqualTo("dave");

        GenericRecord reuse = new GenericData.Record(AvroTestFixtures.GENERIC_SCHEMA);
        GenericRecord copyWithReuse = serializer.copy(original, reuse);
        assertThat(copyWithReuse).isNotSameAs(original);
        assertThat(copyWithReuse).isEqualTo(original);
    }

    @Test
    void testDuplicateAndEqualityAreBasedOnConfiguredType() throws Exception {
        AvroSerializer<GenericRecord> serializer =
                new AvroSerializer<>(GenericRecord.class, AvroTestFixtures.GENERIC_SCHEMA);
        TypeSerializer<GenericRecord> duplicate = serializer.duplicate();

        assertThat(duplicate).isNotSameAs(serializer);
        assertThat(duplicate).isEqualTo(serializer);
        assertThat(duplicate.hashCode()).isEqualTo(serializer.hashCode());
        assertThat(duplicate.isImmutableType()).isEqualTo(serializer.isImmutableType());
        assertThat(duplicate.getLength()).isEqualTo(serializer.getLength());

        assertThat(roundTrip(duplicate, AvroTestFixtures.genericRecord("erin", 5, 2.0d)))
                .isEqualTo(AvroTestFixtures.genericRecord("erin", 5, 2.0d));
        assertThat(serializer).isNotEqualTo(
                new AvroSerializer<>(AvroTestFixtures.ReflectivePojo.class));
    }

    @Test
    void testCopyFromDataInputToDataOutput() throws Exception {
        AvroSerializer<GenericRecord> serializer =
                new AvroSerializer<>(GenericRecord.class, AvroTestFixtures.GENERIC_SCHEMA);
        GenericData.Record input = AvroTestFixtures.genericRecord("frank", 88, 3.25d);

        DataOutputSerializer first = new DataOutputSerializer(16);
        serializer.serialize(input, first);

        DataInputDeserializer source = new DataInputDeserializer(first.getCopyOfBuffer());
        DataOutputSerializer second = new DataOutputSerializer(16);
        serializer.copy(source, second);

        GenericRecord copied = serializer.deserialize(new DataInputDeserializer(second.getCopyOfBuffer()));
        assertThat(copied).isEqualTo(input);
    }

    @Test
    void testJavaSerializationRoundTrip() throws Exception {
        AvroSerializer<GenericRecord> serializer =
                new AvroSerializer<>(GenericRecord.class, AvroTestFixtures.GENERIC_SCHEMA);

        Object restored = javaRoundTrip(serializer);

        assertThat(restored).isInstanceOf(AvroSerializer.class);
        AvroSerializer<?> restoredSerializer = (AvroSerializer<?>) restored;
        assertThat(restoredSerializer).isEqualTo(serializer);
        assertThat(restoredSerializer.getType()).isEqualTo(GenericRecord.class);
        assertThat(roundTrip(castSerializer(restoredSerializer),
                        AvroTestFixtures.genericRecord("grace", 11, null)))
                .isEqualTo(AvroTestFixtures.genericRecord("grace", 11, null));
    }

    @SuppressWarnings("unchecked")
    private static AvroSerializer<GenericRecord> castSerializer(
            AvroSerializer<?> serializer) {
        return (AvroSerializer<GenericRecord>) serializer;
    }

    private static <T> T roundTrip(TypeSerializer<T> serializer, T value) throws Exception {
        DataOutputSerializer out = new DataOutputSerializer(16);
        serializer.serialize(value, out);

        DataInputDeserializer in = new DataInputDeserializer(out.getCopyOfBuffer());
        return serializer.deserialize(in);
    }

    private static Object javaRoundTrip(Object value) throws Exception {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
            out.writeObject(value);
        }

        try (ObjectInputStream in =
                new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
            return in.readObject();
        }
    }
}
