package org.apache.flink.formats.avro.typeutils;

import org.apache.flink.api.common.typeinfo.TypeInformation;
import org.apache.flink.api.common.typeinfo.Types;
import org.apache.flink.api.java.typeutils.RowTypeInfo;
import org.apache.flink.table.api.DataTypes;
import org.apache.flink.table.types.DataType;
import org.apache.flink.table.types.logical.LogicalType;
import org.apache.flink.table.types.logical.LogicalTypeRoot;
import org.apache.flink.types.Row;

import org.apache.avro.LogicalTypes;
import org.apache.avro.Schema;
import org.apache.avro.SchemaParseException;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for {@link AvroSchemaConverter}. */
class AvroSchemaConverterTest {

    private static final String ROW_SCHEMA =
            "{"
                    + "\"type\":\"record\","
                    + "\"name\":\"ConverterRecord\","
                    + "\"namespace\":\"org.apache.flink.formats.avro.typeutils\","
                    + "\"fields\":["
                    + "{\"name\":\"id\",\"type\":\"int\"},"
                    + "{\"name\":\"name\",\"type\":\"string\"},"
                    + "{\"name\":\"status\",\"type\":{\"type\":\"enum\",\"name\":\"Status\",\"symbols\":[\"A\",\"B\"]}},"
                    + "{\"name\":\"tags\",\"type\":{\"type\":\"array\",\"items\":\"string\"}},"
                    + "{\"name\":\"props\",\"type\":{\"type\":\"map\",\"values\":\"int\"}},"
                    + "{\"name\":\"optional\",\"type\":[\"null\",\"long\"]},"
                    + "{\"name\":\"raw\",\"type\":\"bytes\"}"
                    + "]"
                    + "}";

    @Test
    void testConvertAvroSchemaStringToTypeInformation() {
        TypeInformation<Row> typeInfo = AvroSchemaConverter.convertToTypeInfo(ROW_SCHEMA);

        assertThat(typeInfo).isInstanceOf(RowTypeInfo.class);
        assertThat(typeInfo.getTypeClass()).isEqualTo(Row.class);

        RowTypeInfo rowTypeInfo = (RowTypeInfo) typeInfo;
        assertThat(rowTypeInfo.getFieldNames())
                .containsExactly("id", "name", "status", "tags", "props", "optional", "raw");
        assertThat(rowTypeInfo.getTypeAt("id")).isEqualTo(Types.INT);
        assertThat(rowTypeInfo.getTypeAt("name")).isEqualTo(Types.STRING);
        assertThat(rowTypeInfo.getTypeAt("status")).isEqualTo(Types.STRING);
        assertThat(rowTypeInfo.getTypeAt("tags")).isEqualTo(Types.OBJECT_ARRAY(Types.STRING));
        assertThat(rowTypeInfo.getTypeAt("props")).isEqualTo(Types.MAP(Types.STRING, Types.INT));
        assertThat(rowTypeInfo.getTypeAt("optional")).isEqualTo(Types.LONG);
        assertThat(rowTypeInfo.getTypeAt("raw")).isEqualTo(Types.PRIMITIVE_ARRAY(Types.BYTE));
    }

    @Test
    void testConvertAvroSpecificClassToTypeInformation() {
        TypeInformation<Row> typeInfo =
                AvroSchemaConverter.convertToTypeInfo(AvroTestFixtures.SpecificPojo.class);

        assertThat(typeInfo).isInstanceOf(RowTypeInfo.class);
        RowTypeInfo rowTypeInfo = (RowTypeInfo) typeInfo;
        assertThat(rowTypeInfo.getFieldNames()).containsExactly("name", "age");
        assertThat(rowTypeInfo.getTypeAt("name")).isEqualTo(Types.STRING);
        assertThat(rowTypeInfo.getTypeAt("age")).isEqualTo(Types.INT);
    }

    @Test
    void testConvertAvroLogicalTypesToTypeInformationWithLegacyMapping() {
        String schema =
                "{\"type\":\"record\",\"name\":\"LogicalRecord\",\"fields\":["
                        + "{\"name\":\"date\",\"type\":{\"type\":\"int\",\"logicalType\":\"date\"}},"
                        + "{\"name\":\"time\",\"type\":{\"type\":\"int\",\"logicalType\":\"time-millis\"}},"
                        + "{\"name\":\"timestamp\",\"type\":{\"type\":\"long\",\"logicalType\":\"timestamp-millis\"}}"
                        + "]}";

        RowTypeInfo legacy = (RowTypeInfo) AvroSchemaConverter.convertToTypeInfo(schema, true);
        assertThat(legacy.getTypeAt("date")).isEqualTo(Types.SQL_DATE);
        assertThat(legacy.getTypeAt("time")).isEqualTo(Types.SQL_TIME);
        assertThat(legacy.getTypeAt("timestamp")).isEqualTo(Types.SQL_TIMESTAMP);

        RowTypeInfo modern = (RowTypeInfo) AvroSchemaConverter.convertToTypeInfo(schema, false);
        assertThat(modern.getTypeAt("date")).isEqualTo(Types.SQL_DATE);
        assertThat(modern.getTypeAt("time")).isEqualTo(Types.SQL_TIME);
        assertThat(modern.getTypeAt("timestamp")).isEqualTo(Types.INSTANT);
    }

    @Test
    void testConvertAvroSchemaStringToDataType() {
        DataType expected =
                DataTypes.ROW(
                                DataTypes.FIELD("id", DataTypes.INT().notNull()),
                                DataTypes.FIELD("name", DataTypes.STRING().notNull()),
                                DataTypes.FIELD("status", DataTypes.STRING().notNull()),
                                DataTypes.FIELD(
                                        "tags",
                                        DataTypes.ARRAY(DataTypes.STRING().notNull()).notNull()),
                                DataTypes.FIELD(
                                        "props",
                                        DataTypes.MAP(
                                                        DataTypes.STRING().notNull(),
                                                        DataTypes.INT().notNull())
                                                .notNull()),
                                DataTypes.FIELD("optional", DataTypes.BIGINT()),
                                DataTypes.FIELD("raw", DataTypes.BYTES().notNull()))
                        .notNull();

        assertThat(AvroSchemaConverter.convertToDataType(ROW_SCHEMA)).isEqualTo(expected);
    }

    @Test
    void testConvertAvroLogicalTypesToDataType() {
        String schema =
                "{\"type\":\"record\",\"name\":\"LogicalDataTypeRecord\",\"fields\":["
                        + "{\"name\":\"date\",\"type\":{\"type\":\"int\",\"logicalType\":\"date\"}},"
                        + "{\"name\":\"time\",\"type\":{\"type\":\"int\",\"logicalType\":\"time-millis\"}},"
                        + "{\"name\":\"timestamp\",\"type\":{\"type\":\"long\",\"logicalType\":\"timestamp-millis\"}},"
                        + "{\"name\":\"localTimestamp\",\"type\":{\"type\":\"long\",\"logicalType\":\"local-timestamp-micros\"}},"
                        + "{\"name\":\"decimal\",\"type\":{\"type\":\"bytes\",\"logicalType\":\"decimal\",\"precision\":10,\"scale\":2}}"
                        + "]}";

        DataType modern = AvroSchemaConverter.convertToDataType(schema, false);
        assertThat(modern).isEqualTo(
                DataTypes.ROW(
                                DataTypes.FIELD("date", DataTypes.DATE().notNull()),
                                DataTypes.FIELD("time", DataTypes.TIME(3).notNull()),
                                DataTypes.FIELD(
                                        "timestamp",
                                        DataTypes.TIMESTAMP_WITH_LOCAL_TIME_ZONE(3).notNull()),
                                DataTypes.FIELD("localTimestamp", DataTypes.TIMESTAMP(6).notNull()),
                                DataTypes.FIELD("decimal", DataTypes.DECIMAL(10, 2).notNull()))
                        .notNull());

        DataType legacy = AvroSchemaConverter.convertToDataType(schema, true);
        assertThat(legacy).isEqualTo(
                DataTypes.ROW(
                                DataTypes.FIELD("date", DataTypes.DATE().notNull()),
                                DataTypes.FIELD("time", DataTypes.TIME(3).notNull()),
                                DataTypes.FIELD("timestamp", DataTypes.TIMESTAMP(3).notNull()),
                                DataTypes.FIELD("localTimestamp", DataTypes.BIGINT().notNull()),
                                DataTypes.FIELD("decimal", DataTypes.DECIMAL(10, 2).notNull()))
                        .notNull());
    }

    @Test
    void testMultiTypeUnionUsesRawType() {
        DataType dataType =
                AvroSchemaConverter.convertToDataType(
                        "{\"type\":\"record\",\"name\":\"UnionRecord\",\"fields\":["
                                + "{\"name\":\"value\",\"type\":[\"string\",\"int\",\"boolean\"]}"
                                + "]}");

        DataType field = dataType.getChildren().get(0);
        assertThat(field.getLogicalType().getTypeRoot()).isEqualTo(LogicalTypeRoot.RAW);
    }

    @Test
    void testConvertLogicalTypeToAvroSchema() {
        DataType rowType =
                DataTypes.ROW(
                                DataTypes.FIELD("id", DataTypes.INT().notNull()),
                                DataTypes.FIELD("name", DataTypes.STRING()),
                                DataTypes.FIELD(
                                        "nested",
                                        DataTypes.ROW(
                                                        DataTypes.FIELD(
                                                                "value",
                                                                DataTypes.BIGINT().notNull()))
                                                .notNull()))
                        .notNull();

        Schema schema = AvroSchemaConverter.convertToSchema(rowType, "com.acme.Root");

        assertThat(schema.getType()).isEqualTo(Schema.Type.RECORD);
        assertThat(schema.getFullName()).isEqualTo("com.acme.Root");
        assertThat(schema.getField("id").schema().getType()).isEqualTo(Schema.Type.INT);
        assertThat(schema.getField("name").schema().getType()).isEqualTo(Schema.Type.UNION);
        assertThat(schema.getField("name").schema().getTypes())
                .containsExactly(Schema.create(Schema.Type.NULL), Schema.create(Schema.Type.STRING));

        Schema nested = schema.getField("nested").schema();
        assertThat(nested.getType()).isEqualTo(Schema.Type.RECORD);
        assertThat(nested.getFullName()).isEqualTo("com.acme.Root_nested");
        assertThat(nested.getField("value").schema().getType()).isEqualTo(Schema.Type.LONG);
    }

    @Test
    void testConvertLogicalTimeTypesToAvroSchema() {
        Schema timestamp =
                AvroSchemaConverter.convertToSchema(DataTypes.TIMESTAMP(3).notNull(), true);
        assertThat(timestamp.getLogicalType()).isEqualTo(LogicalTypes.timestampMillis());

        Schema localTimestamp =
                AvroSchemaConverter.convertToSchema(DataTypes.TIMESTAMP(6).notNull(), false);
        assertThat(localTimestamp.getLogicalType()).isEqualTo(LogicalTypes.localTimestampMicros());

        Schema zonedTimestamp =
                AvroSchemaConverter.convertToSchema(
                        DataTypes.TIMESTAMP_WITH_LOCAL_TIME_ZONE(6).notNull(), false);
        assertThat(zonedTimestamp.getLogicalType()).isEqualTo(LogicalTypes.timestampMicros());

        Schema date = AvroSchemaConverter.convertToSchema(DataTypes.DATE().notNull());
        assertThat(date.getLogicalType()).isEqualTo(LogicalTypes.date());

        Schema time = AvroSchemaConverter.convertToSchema(DataTypes.TIME(3).notNull());
        assertThat(time.getLogicalType()).isEqualTo(LogicalTypes.timeMillis());

        Schema decimal =
                AvroSchemaConverter.convertToSchema(DataTypes.DECIMAL(12, 4).notNull());
        assertThat(decimal.getLogicalType()).isInstanceOf(LogicalTypes.Decimal.class);
        assertThat(((LogicalTypes.Decimal) decimal.getLogicalType()).getPrecision()).isEqualTo(12);
        assertThat(((LogicalTypes.Decimal) decimal.getLogicalType()).getScale()).isEqualTo(4);
    }

    @Test
    void testUnsupportedLogicalTypeMappingsAreRejected() {
        assertThatThrownBy(
                        () ->
                                AvroSchemaConverter.convertToSchema(
                                        DataTypes.TIMESTAMP(6).notNull(), true))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("only supports precision less than 3");

        assertThatThrownBy(
                        () ->
                                AvroSchemaConverter.convertToSchema(
                                        DataTypes.TIMESTAMP_WITH_LOCAL_TIME_ZONE(3).notNull(),
                                        true))
                .isInstanceOf(UnsupportedOperationException.class);

        assertThatThrownBy(
                        () -> AvroSchemaConverter.convertToSchema(DataTypes.TIME(6).notNull()))
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessageContaining("only supports precision less than 3");

        assertThatThrownBy(
                        () ->
                                AvroSchemaConverter.convertToSchema(
                                        DataTypes.MAP(DataTypes.INT(), DataTypes.STRING())
                                                .notNull()))
                .isInstanceOf(UnsupportedOperationException.class)
                .hasMessageContaining("non-string as key");
    }

    @Test
    void testExtractValueTypeForMapsAndMultisets() {
        DataType mapType = DataTypes.MAP(DataTypes.STRING(), DataTypes.INT().notNull());
        assertThat(AvroSchemaConverter.extractValueTypeToAvroMap(mapType.getLogicalType()))
                .isSameAs(mapType.getValueType().getLogicalType());

        LogicalType multisetValueType =
                AvroSchemaConverter.extractValueTypeToAvroMap(
                        DataTypes.MULTISET(DataTypes.STRING()).getLogicalType());
        assertThat(multisetValueType.getTypeRoot()).isEqualTo(LogicalTypeRoot.INTEGER);
    }

    @Test
    void testInvalidInputsAreRejected() {
        assertThatThrownBy(() -> AvroSchemaConverter.convertToTypeInfo((String) null))
                .isInstanceOf(NullPointerException.class);
        assertThatThrownBy(() -> AvroSchemaConverter.convertToTypeInfo((Class<?>) null))
                .isInstanceOf(NullPointerException.class);
        assertThatThrownBy(() -> AvroSchemaConverter.convertToDataType((String) null))
                .isInstanceOf(NullPointerException.class);

        assertThatThrownBy(() -> AvroSchemaConverter.convertToTypeInfo("{not-avro"))
                .isInstanceOf(IllegalArgumentException.class)
                .hasCauseInstanceOf(SchemaParseException.class);
        assertThatThrownBy(() -> AvroSchemaConverter.convertToDataType("{not-avro"))
                .isInstanceOf(IllegalArgumentException.class)
                .hasCauseInstanceOf(SchemaParseException.class);
    }
}
