package org.apache.flink.runtime.iterative.task;

import org.apache.flink.api.common.aggregators.AggregatorWithName;
import org.apache.flink.api.common.aggregators.LongSumAggregator;
import org.apache.flink.types.LongValue;
import org.apache.flink.types.Value;

import org.junit.jupiter.api.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/** Tests for {@link RuntimeAggregatorRegistry}. */
class RuntimeAggregatorRegistryTest {

    @Test
    void registryExposesRegisteredAggregatorsAndInitiallyHasNoGlobalAggregates() {
        LongSumAggregator count = new LongSumAggregator();
        LongSumAggregator sum = new LongSumAggregator();

        RuntimeAggregatorRegistry registry =
                new RuntimeAggregatorRegistry(
                        Arrays.asList(
                                new AggregatorWithName<>("count", count),
                                new AggregatorWithName<>("sum", sum)));

        assertThat(registry.<LongSumAggregator>getAggregator("count")).isSameAs(count);
        assertThat(registry.<LongSumAggregator>getAggregator("sum")).isSameAs(sum);
        assertThat(registry.getAggregator("missing")).isNull();
        assertThat(registry.getPreviousGlobalAggregate("count")).isNull();

        Map<String, org.apache.flink.api.common.aggregators.Aggregator<?>> all =
                registry.getAllAggregators();
        assertThat(all).hasSize(2).containsEntry("count", count).containsEntry("sum", sum);
    }

    @Test
    void laterAggregatorWithSameNameReplacesEarlierOne() {
        LongSumAggregator first = new LongSumAggregator();
        LongSumAggregator second = new LongSumAggregator();

        RuntimeAggregatorRegistry registry =
                new RuntimeAggregatorRegistry(
                        Arrays.asList(
                                new AggregatorWithName<>("same", first),
                                new AggregatorWithName<>("same", second)));

        assertThat(registry.getAllAggregators()).hasSize(1);
        assertThat(registry.<LongSumAggregator>getAggregator("same")).isSameAs(second);
    }

    @Test
    void updateStoresGlobalAggregatesAndResetsEveryRegisteredAggregator() {
        LongSumAggregator count = new LongSumAggregator();
        LongSumAggregator sum = new LongSumAggregator();
        count.aggregate(7L);
        sum.aggregate(11L);

        RuntimeAggregatorRegistry registry =
                new RuntimeAggregatorRegistry(
                        Arrays.asList(
                                new AggregatorWithName<>("count", count),
                                new AggregatorWithName<>("sum", sum)));

        LongValue globalCount = new LongValue(21L);
        LongValue globalSum = new LongValue(42L);
        registry.updateGlobalAggregatesAndReset(
                new String[] {"count", "sum"}, new Value[] {globalCount, globalSum});

        assertThat(registry.getPreviousGlobalAggregate("count")).isSameAs(globalCount);
        assertThat(registry.getPreviousGlobalAggregate("sum")).isSameAs(globalSum);
        assertThat(registry.getPreviousGlobalAggregate("unknown")).isNull();
        assertThat(count.getAggregate().getValue()).isZero();
        assertThat(sum.getAggregate().getValue()).isZero();
    }

    @Test
    void emptyUpdateResetsAggregatorsWithoutCreatingGlobalAggregates() {
        LongSumAggregator aggregator = new LongSumAggregator();
        aggregator.aggregate(5L);
        RuntimeAggregatorRegistry registry =
                new RuntimeAggregatorRegistry(
                        Collections.singletonList(
                                new AggregatorWithName<>("counter", aggregator)));

        registry.updateGlobalAggregatesAndReset(new String[0], new Value[0]);

        assertThat(aggregator.getAggregate().getValue()).isZero();
        assertThat(registry.getPreviousGlobalAggregate("counter")).isNull();
    }

    @Test
    void invalidUpdateArgumentsAreRejectedBeforeAnyStateChanges() {
        LongSumAggregator aggregator = new LongSumAggregator();
        aggregator.aggregate(9L);
        RuntimeAggregatorRegistry registry =
                new RuntimeAggregatorRegistry(
                        Collections.singletonList(
                                new AggregatorWithName<>("counter", aggregator)));

        assertThatThrownBy(
                        () ->
                                registry.updateGlobalAggregatesAndReset(
                                        null, new Value[] {new LongValue(1L)}))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(
                        () ->
                                registry.updateGlobalAggregatesAndReset(
                                        new String[] {"counter"}, null))
                .isInstanceOf(IllegalArgumentException.class);
        assertThatThrownBy(
                        () ->
                                registry.updateGlobalAggregatesAndReset(
                                        new String[] {"counter", "other"},
                                        new Value[] {new LongValue(1L)}))
                .isInstanceOf(IllegalArgumentException.class);

        assertThat(aggregator.getAggregate().getValue()).isEqualTo(9L);
        assertThat(registry.getPreviousGlobalAggregate("counter")).isNull();
    }
}
