        SyncEventHandler handler =
                new SyncEventHandler(
                        1,
                        Collections.<String, Aggregator<?>>singletonMap("count", aggregator),
                        getClass().getClassLoader());
        WorkerDoneEvent event = workerDoneEvent(1L);

        Field namesField = IterationEventWithAggregators.class.getDeclaredField("aggNames");
        namesField.setAccessible(true);
