/** Tests for the iteration state and lifecycle logic in {@link AbstractIterativeTask}. */
class AbstractIterativeTaskTest {

    @Test
    void brokerKeyIsStableAndContainsJobIterationAndSubtaskIdentity() {
        JobID jobId = JobID.fromHexString("0123456789abcdef0123456789abcdef");
        Environment environment = environment(jobId, 3);
        TestIterativeTask task = new TestIterativeTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(7);
        task.setConfig(config);

        String expected = jobId + "#7#3";
        assertThat(task.brokerKey()).isEqualTo(expected);

        config.setIterationId(99);
        assertThat(task.brokerKey()).isEqualTo(expected);
    }

    @Test
    void iterationAggregatorRegistryIsFetchedFromBrokerAndCached() {
        JobID jobId = JobID.fromHexString("11111111111111111111111111111111");
        Environment environment = environment(jobId, 1);
        TestIterativeTask task = new TestIterativeTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(2);
        task.setConfig(config);

        LongSumAggregator aggregator = new LongSumAggregator();
        RuntimeAggregatorRegistry registry =
                new RuntimeAggregatorRegistry(
                        Collections.<AggregatorWithName<?>>singletonList(
                                new AggregatorWithName<>("sum", aggregator)));
        String key = task.brokerKey();
        IterationAggregatorBroker.instance().handIn(key, registry);
        try {
            assertThat(task.getIterationAggregators()).isSameAs(registry);
            assertThat(task.getIterationAggregators()).isSameAs(registry);
            assertThat(task.getIterationAggregators().<LongSumAggregator>getAggregator("sum"))
                    .isSameAs(aggregator);
        } finally {
            IterationAggregatorBroker.instance().remove(key);
        }
    }

    @Test
    void iterationRuntimeContextExposesSuperstepAggregatorsPreviousValuesAndFirstStepAccumulators() {
        JobID jobId = JobID.fromHexString("22222222222222222222222222222222");
        Environment environment = environment(jobId, 0);
        TestIterativeTask task = new TestIterativeTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(3);
        task.setConfig(config);

        LongSumAggregator aggregator = new LongSumAggregator();
        RuntimeAggregatorRegistry registry =
                new RuntimeAggregatorRegistry(
                        Collections.<AggregatorWithName<?>>singletonList(
                                new AggregatorWithName<>("sum", aggregator)));
        registry.updateGlobalAggregatesAndReset(
                new String[] {"sum"}, new Value[] {new LongValue(17L)});
        String key = task.brokerKey();
        IterationAggregatorBroker.instance().handIn(key, registry);

        Map<String, Accumulator<?, ?>> accumulators = new HashMap<>();
        task.setAccumulatorMap(accumulators);
        OperatorMetricGroup metricGroup = mock(OperatorMetricGroup.class);

        try {
            DistributedRuntimeUDFContext runtimeContext = task.createRuntimeContext(metricGroup);
            assertThat(runtimeContext).isInstanceOf(IterationRuntimeContext.class);
            assertThat(runtimeContext.getMetricGroup()).isSameAs(metricGroup);

            IterationRuntimeContext iterationContext = (IterationRuntimeContext) runtimeContext;
            assertThat(iterationContext.getSuperstepNumber()).isEqualTo(1);
            assertThat(iterationContext.<LongSumAggregator>getIterationAggregator("sum"))
                    .isSameAs(aggregator);
            assertThat((LongValue) iterationContext.getPreviousIterationAggregate("sum"))
                    .isEqualTo(new LongValue(17L));

            iterationContext.addAccumulator("first-step", new IntCounter());
            assertThat(accumulators).containsKey("first-step");

            task.incrementIterationCounter();
            assertThat(iterationContext.getSuperstepNumber()).isEqualTo(2);
            iterationContext.addAccumulator("later-step", new LongCounter());
            assertThat(accumulators).doesNotContainKey("later-step");
        } finally {
            IterationAggregatorBroker.instance().remove(key);
        }
    }

    @Test
    void superstepCounterStartsAtOneAndAdvances() {
        TestIterativeTask task = new TestIterativeTask(environment(JobID.generate(), 0));

        assertThat(task.inFirstIteration()).isTrue();
        assertThat(task.currentIteration()).isEqualTo(1);

        task.incrementIterationCounter();
        assertThat(task.inFirstIteration()).isFalse();
        assertThat(task.currentIteration()).isEqualTo(2);

        task.incrementIterationCounter();
        assertThat(task.currentIteration()).isEqualTo(3);
    }

    @Test
    void terminationCanBeRequestedIndependentlyAndByCancellation() throws Exception {
        Environment environment = environment(JobID.generate(), 0);
        BroadcastVariableManager broadcastVariableManager = mock(BroadcastVariableManager.class);
        when(environment.getBroadcastVariableManager()).thenReturn(broadcastVariableManager);
        TestIterativeTask task = new TestIterativeTask(environment);

        assertThat(task.terminationRequested()).isFalse();

        task.requestTermination();
        assertThat(task.terminationRequested()).isTrue();
        assertThat(task.isRunning()).isTrue();

        TestIterativeTask secondTask = new TestIterativeTask(environment);
        secondTask.cancel();

        assertThat(secondTask.terminationRequested()).isTrue();
        assertThat(secondTask.isRunning()).isFalse();
        verify(broadcastVariableManager).releaseAllReferencesFromTask(secondTask);
    }

    @Test
    void verifyingSuperstepWithoutAnyIterativeInputFails() {
        TestIterativeTask task = new TestIterativeTask(environment(JobID.generate(), 0));
        task.setIterativeInputs(new int[0]);
        task.setIterativeBroadcastInputs(new int[0]);

        assertThatThrownBy(task::verifySuperstepState)
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("without a single iterative input");
    }

    @Test
    void finishedIterativeInputIsLeftUntouched() throws Exception {
        TestIterativeTask task = new TestIterativeTask(environment(JobID.generate(), 0));
        MutableReader<?> reader = mock(MutableReader.class);
        when(reader.isFinished()).thenReturn(true);
        task.setIterativeInputs(new int[] {0});
        task.setInputReaders(new MutableReader<?>[] {reader});

        task.verifySuperstepState();

        verify(reader, never()).startNextSuperstep();
    }

    @Test
    void iterativeInputAlreadyAtEndOfSuperstepStartsNextSuperstep() throws Exception {
        TestIterativeTask task = new TestIterativeTask(environment(JobID.generate(), 0));
        MutableReader<?> reader = mock(MutableReader.class);
        when(reader.isFinished()).thenReturn(false);
        when(reader.hasReachedEndOfSuperstep()).thenReturn(true);
        task.setIterativeInputs(new int[] {0});
        task.setInputReaders(new MutableReader<?>[] {reader});

        task.verifySuperstepState();

        verify(reader).startNextSuperstep();
    }

    @Test
    void iterativeInputIsDrainedBeforeNextSuperstepStarts() throws Exception {
        TestIterativeTask task = new TestIterativeTask(environment(JobID.generate(), 0));
        MutableReader<?> reader = mock(MutableReader.class);
        when(reader.isFinished()).thenReturn(false);
        when(reader.hasReachedEndOfSuperstep()).thenReturn(false);

        AtomicInteger consumed = new AtomicInteger();
        MutableObjectIterator<Object> iterator =
                new MutableObjectIterator<Object>() {
                    @Override
                    public Object next(Object reuse) {
                        consumed.incrementAndGet();
                        return null;
                    }

                    @Override
                    public Object next() {
                        consumed.incrementAndGet();
                        return null;
                    }
                };
        TypeSerializerFactory<Object> serializerFactory =
                new RuntimeSerializerFactory<>(IntSerializer.INSTANCE, (Class) Integer.class);

        task.setIterativeInputs(new int[] {0});
        task.setInputReaders(new MutableReader<?>[] {reader});
        task.setInputIterators(new MutableObjectIterator<?>[] {iterator});
        task.setInputSerializers(new TypeSerializerFactory<?>[] {serializerFactory});

        task.verifySuperstepState();

        assertThat(consumed).hasValue(1);
        verify(reader).startNextSuperstep();
    }

    @Test
    void noNextSuperstepIsStartedWhenDrainingFinishesTheReader() throws Exception {
        TestIterativeTask task = new TestIterativeTask(environment(JobID.generate(), 0));
        MutableReader<?> reader = mock(MutableReader.class);
        when(reader.isFinished()).thenReturn(false, true);
        when(reader.hasReachedEndOfSuperstep()).thenReturn(false);
        MutableObjectIterator<Object> iterator =
                new MutableObjectIterator<Object>() {
                    @Override
                    public Object next(Object reuse) {
                        return null;
                    }

                    @Override
                    public Object next() {
                        return null;
                    }
                };
        TypeSerializerFactory<Object> serializerFactory =
                new RuntimeSerializerFactory<>(IntSerializer.INSTANCE, (Class) Integer.class);

        task.setIterativeInputs(new int[] {0});
        task.setInputReaders(new MutableReader<?>[] {reader});
        task.setInputIterators(new MutableObjectIterator<?>[] {iterator});
        task.setInputSerializers(new TypeSerializerFactory<?>[] {serializerFactory});

        task.verifySuperstepState();

        verify(reader, never()).startNextSuperstep();
    }

    @Test
    void unfinishedBroadcastInputIsRejected() {
        TestIterativeTask task = new TestIterativeTask(environment(JobID.generate(), 0));
        MutableReader<?> reader = mock(MutableReader.class);
        when(reader.isFinished()).thenReturn(false);
        when(reader.hasReachedEndOfSuperstep()).thenReturn(false);

        task.setIterativeInputs(new int[0]);
        task.setIterativeBroadcastInputs(new int[] {0});
        task.setBroadcastInputReaders(new MutableReader<?>[] {reader});

        assertThatThrownBy(task::verifySuperstepState)
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("broadcast input");
    }

    @Test
    void broadcastInputAtEndOfSuperstepStartsNextSuperstep() throws Exception {
        TestIterativeTask task = new TestIterativeTask(environment(JobID.generate(), 0));
        MutableReader<?> reader = mock(MutableReader.class);
        when(reader.isFinished()).thenReturn(false);
        when(reader.hasReachedEndOfSuperstep()).thenReturn(true);

        task.setIterativeInputs(new int[0]);
        task.setIterativeBroadcastInputs(new int[] {0});
        task.setBroadcastInputReaders(new MutableReader<?>[] {reader});

        task.verifySuperstepState();

        verify(reader).startNextSuperstep();
    }

    @Test
    void solutionSetCollectorSupportsBothManagedAndObjectSolutionSets() {
        JobID jobId = JobID.fromHexString("33333333333333333333333333333333");
        Environment environment = environment(jobId, 0);
        TestIterativeTask task = new TestIterativeTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(5);
        task.setConfig(config);
        String key = task.brokerKey();

        try {
            CompactingHashTable<Integer> hashTable = mock(CompactingHashTable.class);
            SolutionSetBroker.instance().handIn(key, hashTable);
            Collector<Integer> managed = task.createSolutionSetCollector(null);
            assertThat(managed).isInstanceOf(SolutionSetUpdateOutputCollector.class);

            SolutionSetBroker.instance().remove(key);
            JoinHashMap<Integer> joinHashMap = mock(JoinHashMap.class);
            when(joinHashMap.getBuildSerializer())
                    .thenReturn((TypeSerializer<Integer>) mock(TypeSerializer.class));
            SolutionSetBroker.instance().handIn(key, joinHashMap);
            Collector<Integer> objectBacked = task.createSolutionSetCollector(null);
            assertThat(objectBacked).isInstanceOf(SolutionSetObjectsUpdateOutputCollector.class);
        } finally {
            SolutionSetBroker.instance().remove(key);
        }
    }

    @Test
    void solutionSetCollectorRejectsUnknownHandles() {
        Environment environment = environment(JobID.generate(), 0);
        TestIterativeTask task = new TestIterativeTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(6);
        task.setConfig(config);
        String key = task.brokerKey();
        Object unexpected = new Object();
        SolutionSetBroker.instance().handIn(key, unexpected);
        try {
            assertThatThrownBy(() -> task.createSolutionSetCollector(null))
                    .isInstanceOf(RuntimeException.class)
                    .hasMessageContaining("Unrecognized solution set handle");
        } finally {
            SolutionSetBroker.instance().remove(key);
        }
    }

    private static Environment environment(JobID jobId, int subtaskIndex) {
        Environment environment = mock(Environment.class);
        when(environment.getJobID()).thenReturn(jobId);
        when(environment.getJobInfo()).thenReturn(mock(JobInfo.class));
        when(environment.getExecutionConfig()).thenReturn(new ExecutionConfig());
        when(environment.getDistributedCacheEntries()).thenReturn(Collections.emptyMap());
        when(environment.getExternalResourceInfoProvider())
                .thenReturn(mock(ExternalResourceInfoProvider.class));

        TaskInfo taskInfo = mock(TaskInfo.class);
        when(taskInfo.getTaskName()).thenReturn("test-task");
        when(taskInfo.getIndexOfThisSubtask()).thenReturn(subtaskIndex);
        when(environment.getTaskInfo()).thenReturn(taskInfo);

        UserCodeClassLoader classLoader = mock(UserCodeClassLoader.class);
        when(classLoader.asClassLoader()).thenReturn(AbstractIterativeTaskTest.class.getClassLoader());
        when(environment.getUserCodeClassLoader()).thenReturn(classLoader);
        return environment;
    }

    private static final class TestIterativeTask extends AbstractIterativeTask<Function, Integer> {

        TestIterativeTask(Environment environment) {
            super(environment);
        }

        void setConfig(TaskConfig config) {
            this.config = config;
        }

        void setAccumulatorMap(Map<String, Accumulator<?, ?>> accumulatorMap) {
            this.accumulatorMap = accumulatorMap;
        }

        void setIterativeInputs(int[] inputs) {
            this.iterativeInputs = inputs;
        }

        void setIterativeBroadcastInputs(int[] inputs) {
            this.iterativeBroadcastInputs = inputs;
        }

        void setInputReaders(MutableReader<?>[] readers) {
            this.inputReaders = readers;
        }

        void setBroadcastInputReaders(MutableReader<?>[] readers) {
            this.broadcastInputReaders = readers;
        }

        void setInputIterators(MutableObjectIterator<?>[] iterators) {
            this.inputIterators = iterators;
        }

        void setInputSerializers(TypeSerializerFactory<?>[] serializers) {
            this.inputSerializers = serializers;
        }

        boolean inFirstIteration() {
            return super.inFirstIteration();
        }

        int currentIteration() {
            return super.currentIteration();
        }

        void incrementIterationCounter() {
            super.incrementIterationCounter();
        }

        boolean isRunning() {
            return this.running;
        }

        void verifySuperstepState() throws IOException {
            verifyEndOfSuperstepState();
        }

        Collector<Integer> createSolutionSetCollector(Collector<Integer> delegate) {
            return createSolutionSetUpdateOutputCollector(delegate);
        }
    }
}
