/** Tests for the iteration state and lifecycle logic in {@link AbstractIterativeTask}. */
class AbstractIterativeTaskTest {

    @Test
    void brokerKeyIsStableAndContainsJobIterationAndSubtaskIdentity() {
        JobID jobId = JobID.fromHexString("0123456789abcdef0123456789abcdef");
        Environment environment = environment(jobId, 3);
        TestIterativeTask task = new TestIterativeTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(7);
        task.setConfig(config);

        String expected = jobId + "#7#3";
        assertThat(task.brokerKey()).isEqualTo(expected);

        config.setIterationId(99);
        assertThat(task.brokerKey()).isEqualTo(expected);
    }

    @Test
    void iterationAggregatorRegistryIsFetchedFromBrokerAndCached() {
        JobID jobId = JobID.fromHexString("11111111111111111111111111111111");
        Environment environment = environment(jobId, 1);
        TestIterativeTask task = new TestIterativeTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(2);
        task.setConfig(config);

        LongSumAggregator aggregator = new LongSumAggregator();
        RuntimeAggregatorRegistry registry =
                new RuntimeAggregatorRegistry(
                        Collections.<AggregatorWithName<?>>singletonList(
                                new AggregatorWithName<>("sum", aggregator)));
        String key = task.brokerKey();
        IterationAggregatorBroker.instance().handIn(key, registry);
        try {
            assertThat(task.getIterationAggregators()).isSameAs(registry);
            assertThat(task.getIterationAggregators()).isSameAs(registry);
            assertThat(task.getIterationAggregators().<LongSumAggregator>getAggregator("sum"))
                    .isSameAs(aggregator);
        } finally {
            IterationAggregatorBroker.instance().remove(key);
        }
    }

    @Test
    void iterationRuntimeContextExposesSuperstepAggregatorsPreviousValuesAndFirstStepAccumulators() {
        JobID jobId = JobID.fromHexString("22222222222222222222222222222222");
        Environment environment = environment(jobId, 0);
        TestIterativeTask task = new TestIterativeTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(3);
        task.setConfig(config);

        LongSumAggregator aggregator = new LongSumAggregator();
        RuntimeAggregatorRegistry registry =
                new RuntimeAggregatorRegistry(
                        Collections.<AggregatorWithName<?>>singletonList(
                                new AggregatorWithName<>("sum", aggregator)));
        registry.updateGlobalAggregatesAndReset(
                new String[] {"sum"}, new Value[] {new LongValue(17L)});
        String key = task.brokerKey();
        IterationAggregatorBroker.instance().handIn(key, registry);

        Map<String, Accumulator<?, ?>> accumulators = new HashMap<>();
        task.setAccumulatorMap(accumulators);
        OperatorMetricGroup metricGroup = IterativeTaskTestEnvironment.metricGroup();

        try {
            DistributedRuntimeUDFContext runtimeContext = task.createRuntimeContext(metricGroup);
            assertThat(runtimeContext).isInstanceOf(IterationRuntimeContext.class);
            assertThat(runtimeContext.getMetricGroup()).isSameAs(metricGroup);

            IterationRuntimeContext iterationContext = (IterationRuntimeContext) runtimeContext;
            assertThat(iterationContext.getSuperstepNumber()).isEqualTo(1);
            assertThat(iterationContext.<LongSumAggregator>getIterationAggregator("sum"))
                    .isSameAs(aggregator);
            assertThat((LongValue) iterationContext.getPreviousIterationAggregate("sum"))
                    .isEqualTo(new LongValue(17L));

            iterationContext.addAccumulator("first-step", new IntCounter());
            assertThat(accumulators).containsKey("first-step");

            task.incrementIterationCounter();
            assertThat(iterationContext.getSuperstepNumber()).isEqualTo(2);
            iterationContext.addAccumulator("later-step", new LongCounter());
            assertThat(accumulators).doesNotContainKey("later-step");
        } finally {
            IterationAggregatorBroker.instance().remove(key);
        }
    }

    @Test
    void superstepCounterStartsAtOneAndAdvances() {
        TestIterativeTask task = new TestIterativeTask(environment(JobID.generate(), 0));

        assertThat(task.inFirstIteration()).isTrue();
        assertThat(task.currentIteration()).isEqualTo(1);

        task.incrementIterationCounter();
        assertThat(task.inFirstIteration()).isFalse();
        assertThat(task.currentIteration()).isEqualTo(2);

        task.incrementIterationCounter();
        assertThat(task.currentIteration()).isEqualTo(3);
    }

    @Test
    void terminationCanBeRequestedIndependentlyAndByCancellation() throws Exception {
        BroadcastVariableManager broadcastVariableManager = new BroadcastVariableManager();
        Environment environment =
                IterativeTaskTestEnvironment.environment(
                        JobID.generate(),
                        0,
                        Collections.singletonMap(
                                "getBroadcastVariableManager", broadcastVariableManager));
        TestIterativeTask task = new TestIterativeTask(environment);

        assertThat(task.terminationRequested()).isFalse();

        task.requestTermination();
        assertThat(task.terminationRequested()).isTrue();
        assertThat(task.isRunning()).isTrue();

        TestIterativeTask secondTask = new TestIterativeTask(environment);
        secondTask.cancel();

        assertThat(secondTask.terminationRequested()).isTrue();
        assertThat(secondTask.isRunning()).isFalse();
        assertThat(broadcastVariableManager.getNumberOfVariablesWithReferences()).isZero();
    }

    @Test
