    @Test
    void iterativeInputIsDrainedBeforeNextSuperstepStarts() throws Exception {
        TestIterativeTask task = new TestIterativeTask(environment(JobID.generate(), 0));
        TestReader reader = new TestReader(false, false);

        AtomicInteger consumed = new AtomicInteger();
        MutableObjectIterator<Object> iterator =
                new MutableObjectIterator<Object>() {
                    @Override
                    public Object next(Object reuse) {
                        consumed.incrementAndGet();
                        return null;
                    }

                    @Override
                    public Object next() {
                        consumed.incrementAndGet();
                        return null;
                    }
                };
        TypeSerializerFactory<Object> serializerFactory =
                new RuntimeSerializerFactory<>(IntSerializer.INSTANCE, (Class) Integer.class);

        task.setIterativeInputs(new int[] {0});
        task.setInputReaders(new MutableReader<?>[] {reader});
        task.setInputIterators(new MutableObjectIterator<?>[] {iterator});
        task.setInputSerializers(new TypeSerializerFactory<?>[] {serializerFactory});

        task.verifySuperstepState();

        assertThat(consumed).hasValue(1);
        assertThat(reader.startedSupersteps).isEqualTo(1);
    }

    @Test
    void noNextSuperstepIsStartedWhenDrainingFinishesTheReader() throws Exception {
        TestIterativeTask task = new TestIterativeTask(environment(JobID.generate(), 0));
        TestReader reader = new TestReader(new boolean[] {false, true}, false);
        MutableObjectIterator<Object> iterator =
                new MutableObjectIterator<Object>() {
                    @Override
                    public Object next(Object reuse) {
                        return null;
                    }

                    @Override
                    public Object next() {
                        return null;
                    }
