    @Test
    void solutionSetCollectorSupportsBothManagedAndObjectSolutionSets() throws Exception {
        JobID jobId = JobID.fromHexString("33333333333333333333333333333333");
        Environment environment = environment(jobId, 0);
        TestIterativeTask task = new TestIterativeTask(environment);
        TaskConfig config = new TaskConfig(new Configuration());
        config.setIterationId(5);
        task.setConfig(config);
        String key = task.brokerKey();

        CompactingHashTable<Integer> hashTable =
                new CompactingHashTable<>(
                        IntSerializer.INSTANCE, new IntComparator(true), memorySegments());
        try {
            SolutionSetBroker.instance().handIn(key, hashTable);
            Collector<Integer> managed = task.createSolutionSetCollector(null);
            assertThat(managed).isInstanceOf(SolutionSetUpdateOutputCollector.class);
            hashTable.close();
        } finally {
            SolutionSetBroker.instance().remove(key);
        }

        JoinHashMap<Integer> joinHashMap =
                new JoinHashMap<>(IntSerializer.INSTANCE, new IntComparator(true));
        SolutionSetBroker.instance().handIn(key, joinHashMap);
        try {
            Collector<Integer> objectBacked = task.createSolutionSetCollector(null);
            assertThat(objectBacked).isInstanceOf(SolutionSetObjectsUpdateOutputCollector.class);
        } finally {
            SolutionSetBroker.instance().remove(key);
        }
    }

