 42	/**
 43	 * Utilities to determine the network interface and address that should be used to bind the
 44	 * TaskManager communication to.
 45	 *
 46	 * <p>Implementation note: This class uses {@code System.nanoTime()} to measure elapsed time,
 47	 * because that is not susceptible to clock changes.
 48	 */
 49	public class ConnectionUtils {
 50	
 51	    private static final Logger LOG = LoggerFactory.getLogger(ConnectionUtils.class);
 52	
 53	    private static final long MIN_SLEEP_TIME = 50;
 54	    private static final long MAX_SLEEP_TIME = 20000;
 55	
 56	    /**
 57	     * The states of address detection mechanism. There is only a state transition if the current
 58	     * state failed to determine the address.
 59	     */
 60	    private enum AddressDetectionState {
 61	        /** Connect from interface returned by InetAddress.getLocalHost(). * */
 62	        LOCAL_HOST(200),
 63	        /** Detect own IP address based on the target IP address. Look for common prefix */
 64	        ADDRESS(50),
 65	        /** Try to connect on all Interfaces and all their addresses with a low timeout. */
 66	        FAST_CONNECT(50),
 67	        /** Try to connect on all Interfaces and all their addresses with a long timeout. */
 68	        SLOW_CONNECT(1000),
 69	        /** Choose any non-loopback address. */
 70	        HEURISTIC(0);
 71	
 72	        private final int timeout;
 73	
 74	        AddressDetectionState(int timeout) {
 75	            this.timeout = timeout;
 76	        }
 77	
 78	        public int getTimeout() {
 79	            return timeout;
 80	        }
 81	    }
 82	
 83	    /**
 84	     * Finds the local network address from which this machine can connect to the target address.
 85	     * This method tries to establish a proper network connection to the given target, so it only
 86	     * succeeds if the target socket address actually accepts connections. The method tries various
 87	     * strategies multiple times and uses an exponential backoff timer between tries.
 88	     *
 89	     * <p>If no connection attempt was successful after the given maximum time, the method will
 90	     * choose some address based on heuristics (excluding link-local and loopback addresses.)
 91	     *
 92	     * <p>This method will initially not log on info level (to not flood the log while the backoff
 93	     * time is still very low). It will start logging after a certain time has passes.
 94	     *
 95	     * @param targetAddress The address that the method tries to connect to.
 96	     * @param maxWaitMillis The maximum time that this method tries to connect, before falling back
 97	     *     to the heuristics.
 98	     * @param startLoggingAfter The time after which the method will log on INFO level.
 99	     */
100	    public static InetAddress findConnectingAddress(
101	            InetSocketAddress targetAddress, long maxWaitMillis, long startLoggingAfter)
102	            throws IOException {
103	        if (targetAddress == null) {
104	            throw new NullPointerException("targetAddress must not be null");
105	        }
106	        if (maxWaitMillis <= 0) {
107	            throw new IllegalArgumentException("Max wait time must be positive");
108	        }
109	
110	        final long startTimeNanos = System.nanoTime();
111	
112	        long currentSleepTime = MIN_SLEEP_TIME;
113	        long elapsedTimeMillis = 0;
114	
115	        final List<AddressDetectionState> strategies =
116	                Collections.unmodifiableList(
117	                        Arrays.asList(
118	                                AddressDetectionState.LOCAL_HOST,
119	                                AddressDetectionState.ADDRESS,
120	                                AddressDetectionState.FAST_CONNECT,
121	                                AddressDetectionState.SLOW_CONNECT));
122	
123	        // loop while there is time left
124	        while (elapsedTimeMillis < maxWaitMillis) {
125	            boolean logging = elapsedTimeMillis >= startLoggingAfter;
126	            if (logging) {
127	                LOG.info("Trying to connect to " + targetAddress);
128	            }
129	
130	            // Try each strategy in order
131	            for (AddressDetectionState strategy : strategies) {
132	                InetAddress address = findAddressUsingStrategy(strategy, targetAddress, logging);
133	                if (address != null) {
134	                    return address;
135	                }
136	            }
137	
138	            // we have made a pass with all strategies over all interfaces
139	            // sleep for a while before we make the next pass
140	            elapsedTimeMillis = (System.nanoTime() - startTimeNanos) / 1_000_000;
141	
142	            long toWait = Math.min(maxWaitMillis - elapsedTimeMillis, currentSleepTime);
143	            if (toWait > 0) {
144	                if (logging) {
145	                    LOG.info("Could not connect. Waiting for {} msecs before next attempt", toWait);
146	                } else {
147	                    LOG.debug(
148	                            "Could not connect. Waiting for {} msecs before next attempt", toWait);
149	                }
150	
151	                try {
152	                    Thread.sleep(toWait);
153	                } catch (InterruptedException e) {
154	                    throw new IOException("Connection attempts have been interrupted.");
155	                }
156	            }
157	
158	            // increase the exponential backoff timer
159	            currentSleepTime = Math.min(2 * currentSleepTime, MAX_SLEEP_TIME);
160	        }
161	
162	        // our attempts timed out. use the heuristic fallback
163	        LOG.warn(
164	                "Could not connect to {}. Selecting a local address using heuristics.",
165	                targetAddress);
166	        InetAddress heuristic =
167	                findAddressUsingStrategy(AddressDetectionState.HEURISTIC, targetAddress, true);
168	        if (heuristic != null) {
169	            return heuristic;
170	        } else {
171	            LOG.warn(
172	                    "Could not find any IPv4 address that is not loopback or link-local. Using localhost address.");
173	            return InetAddress.getLocalHost();
174	        }
175	    }
