177	    /**
178	     * This utility method tries to connect to the JobManager using the InetAddress returned by
179	     * InetAddress.getLocalHost(). The purpose of the utility is to have a final try connecting to
180	     * the target address using the LocalHost before using the address returned. We do a second try
181	     * because the JM might have been unavailable during the first check.
182	     *
183	     * @param preliminaryResult The address detected by the heuristic
184	     * @return either the preliminaryResult or the address returned by InetAddress.getLocalHost()
185	     *     (if we are able to connect to targetAddress from there)
186	     */
187	    private static InetAddress tryLocalHostBeforeReturning(
188	            InetAddress preliminaryResult, SocketAddress targetAddress, boolean logging)
189	            throws IOException {
190	
191	        InetAddress localhostName = InetAddress.getLocalHost();
192	
193	        if (preliminaryResult.equals(localhostName)) {
194	            // preliminary result is equal to the local host name
195	            return preliminaryResult;
196	        } else if (tryToConnect(
197	                localhostName,
198	                targetAddress,
199	                AddressDetectionState.SLOW_CONNECT.getTimeout(),
200	                logging)) {
201	            // success, we were able to use local host to connect
202	            LOG.debug(
203	                    "Preferring {} (InetAddress.getLocalHost()) for local bind point over previous candidate {}",
204	                    localhostName,
205	                    preliminaryResult);
206	            return localhostName;
207	        } else {
208	            // we have to make the preliminary result the final result
209	            return preliminaryResult;
210	        }
211	    }
212	
213	    /**
214	     * Try to find a local address which allows as to connect to the targetAddress using the given
215	     * strategy.
216	     *
217	     * @param strategy Depending on the strategy, the method will enumerate all interfaces, trying
218	     *     to connect to the target address
219	     * @param targetAddress The address we try to connect to
220	     * @param logging Boolean indicating the logging verbosity

221	     * @return null if we could not find an address using this strategy, otherwise, the local
222	     *     address.
223	     * @throws IOException
224	     */
225	    private static InetAddress findAddressUsingStrategy(
226	            AddressDetectionState strategy, InetSocketAddress targetAddress, boolean logging)
227	            throws IOException {
228	        // try LOCAL_HOST strategy independent of the network interfaces
229	        if (strategy == AddressDetectionState.LOCAL_HOST) {
230	            InetAddress localhostName;
231	            try {
232	                localhostName = InetAddress.getLocalHost();
233	            } catch (UnknownHostException uhe) {
234	                LOG.warn("Could not resolve local hostname to an IP address: {}", uhe.getMessage());
235	                return null;
236	            }
237	
238	            if (tryToConnect(localhostName, targetAddress, strategy.getTimeout(), logging)) {
239	                LOG.debug(
240	                        "Using InetAddress.getLocalHost() immediately for the connecting address");
241	                // Here, we are not calling tryLocalHostBeforeReturning() because it is the
242	                // LOCAL_HOST strategy
243	                return localhostName;
244	            } else {
245	                return null;
246	            }
247	        }
248	
249	        final InetAddress address = targetAddress.getAddress();
250	        if (address == null) {
251	            return null;
252	        }
253	        final byte[] targetAddressBytes = address.getAddress();
254	
255	        // for each network interface
256	        Enumeration<NetworkInterface> e = NetworkInterface.getNetworkInterfaces();
257	        while (e.hasMoreElements()) {
258	
259	            NetworkInterface netInterface = e.nextElement();
260	
261	            // for each address of the network interface
262	            Enumeration<InetAddress> ee = netInterface.getInetAddresses();
263	            while (ee.hasMoreElements()) {
264	                InetAddress interfaceAddress = ee.nextElement();
265	
266	                switch (strategy) {
267	                    case ADDRESS:
268	                        if (hasCommonPrefix(targetAddressBytes, interfaceAddress.getAddress())) {
269	                            LOG.debug(
270	                                    "Target address {} and local address {} share prefix - trying to connect.",
271	                                    targetAddress,
272	                                    interfaceAddress);
273	
274	                            if (tryToConnect(
275	                                    interfaceAddress,
276	                                    targetAddress,
277	                                    strategy.getTimeout(),
278	                                    logging)) {
279	                                return tryLocalHostBeforeReturning(
280	                                        interfaceAddress, targetAddress, logging);
281	                            }
282	                        }
283	                        break;
284	
285	                    case FAST_CONNECT:
286	                    case SLOW_CONNECT:
287	                        LOG.debug(
288	                                "Trying to connect to {} from local address {} with timeout {}",
289	                                targetAddress,
290	                                interfaceAddress,
291	                                strategy.getTimeout());
292	
293	                        if (tryToConnect(
294	                                interfaceAddress, targetAddress, strategy.getTimeout(), logging)) {
295	                            return tryLocalHostBeforeReturning(
296	                                    interfaceAddress, targetAddress, logging);
297	                        }
298	                        break;
299	
300	                    case HEURISTIC:
301	                        if (LOG.isDebugEnabled()) {
302	                            LOG.debug(
303	                                    "Choosing InetAddress.getLocalHost() address as a heuristic.");
304	                        }
305	
306	                        return InetAddress.getLocalHost();
307	
308	                    default:
309	                        throw new RuntimeException("Unsupported strategy: " + strategy);
310	                }
311	            } // end for each address of the interface
312	        } // end for each interface
313	
314	        return null;
315	    }
