317	    /**
318	     * Checks if two addresses have a common prefix (first 2 bytes). Example: 192.168.???.??? Works
319	     * also with ipv6, but accepts probably too many addresses
320	     */
321	    private static boolean hasCommonPrefix(byte[] address, byte[] address2) {
322	        return address[0] == address2[0] && address[1] == address2[1];
323	    }
