325	    /**
326	     * @param fromAddress The address to connect from.
327	     * @param toSocket The socket address to connect to.
328	     * @param timeout The timeout fr the connection.
329	     * @param logFailed Flag to indicate whether to log failed attempts on info level (failed
330	     *     attempts are always logged on DEBUG level).
331	     * @return True, if the connection was successful, false otherwise.
332	     * @throws IOException Thrown if the socket cleanup fails.
333	     */
334	    private static boolean tryToConnect(
335	            InetAddress fromAddress, SocketAddress toSocket, int timeout, boolean logFailed)
336	            throws IOException {
337	        String detailedMessage =
338	                String.format(
339	                        "connect to [%s] from local address [%s] with timeout [%s]",
340	                        toSocket, fromAddress, timeout);
341	        if (LOG.isDebugEnabled()) {
342	            LOG.debug("Trying to " + detailedMessage);
343	        }
344	        try (Socket socket = new Socket()) {
345	            // port 0 = let the OS choose the port
346	            SocketAddress bindP = new InetSocketAddress(fromAddress, 0);
347	            // machine
348	            socket.bind(bindP);
349	            socket.connect(toSocket, timeout);
350	            return true;
351	        } catch (Exception ex) {
352	            String message = "Failed to " + detailedMessage + " due to: " + ex.getMessage();
353	            if (LOG.isDebugEnabled()) {
354	                LOG.debug(message, ex);
355	            } else if (logFailed) {
356	                LOG.info(message);
357	            }
358	            return false;
359	        }
360	    }
