362	    /**
363	     * A {@link LeaderRetrievalListener} that allows retrieving an {@link InetAddress} for the
364	     * current leader.
365	     */
366	    public static class LeaderConnectingAddressListener implements LeaderRetrievalListener {
367	
368	        private static final Duration defaultLoggingDelay = Duration.ofMillis(400);
369	
370	        private final RpcSystemUtils rpcSystemUtils;
371	
372	        public LeaderConnectingAddressListener(RpcSystemUtils rpcSystemUtils) {
373	            this.rpcSystemUtils = rpcSystemUtils;
374	        }
375	
376	        private enum LeaderRetrievalState {
377	            NOT_RETRIEVED,
378	            RETRIEVED,
379	            NEWLY_RETRIEVED
380	        }
381	
382	        private final Object retrievalLock = new Object();
383	
384	        private String rpcURL;
385	        private LeaderRetrievalState retrievalState = LeaderRetrievalState.NOT_RETRIEVED;
386	        private Exception exception;
387	
388	        public InetAddress findConnectingAddress(Duration timeout) throws LeaderRetrievalException {
389	            return findConnectingAddress(timeout, defaultLoggingDelay);
390	        }
391	
392	        public InetAddress findConnectingAddress(Duration timeout, Duration startLoggingAfter)
393	                throws LeaderRetrievalException {
394	
395	            final long startTimeNanos = System.nanoTime();
396	            long currentSleepTime = MIN_SLEEP_TIME;
397	            long elapsedTimeMillis = 0;
398	            InetSocketAddress targetAddress = null;
399	
400	            try {
401	                while (elapsedTimeMillis < timeout.toMillis()) {
402	
403	                    long maxTimeout = timeout.toMillis() - elapsedTimeMillis;
404	
405	                    synchronized (retrievalLock) {
406	                        if (exception != null) {
407	                            throw exception;
408	                        }
409	
410	                        if (retrievalState == LeaderRetrievalState.NOT_RETRIEVED) {

410	                        if (retrievalState == LeaderRetrievalState.NOT_RETRIEVED) {
411	                            try {
412	                                retrievalLock.wait(maxTimeout);
413	                            } catch (InterruptedException e) {
414	                                throw new Exception(
415	                                        "Finding connecting address was interrupted"
416	                                                + "while waiting for the leader retrieval.");
417	                            }
418	                        } else if (retrievalState == LeaderRetrievalState.NEWLY_RETRIEVED) {
419	                            targetAddress = rpcSystemUtils.getInetSocketAddressFromRpcUrl(rpcURL);
420	
421	                            LOG.debug(
422	                                    "Retrieved new target address {} for RPC URL {}.",
423	                                    targetAddress,
424	                                    rpcURL);
425	
426	                            retrievalState = LeaderRetrievalState.RETRIEVED;
427	
428	                            currentSleepTime = MIN_SLEEP_TIME;
429	                        } else {
430	                            currentSleepTime = Math.min(2 * currentSleepTime, MAX_SLEEP_TIME);
431	                        }
432	                    }
433	
434	                    if (targetAddress != null) {
435	                        AddressDetectionState strategy = AddressDetectionState.LOCAL_HOST;
436	
437	                        boolean logging = elapsedTimeMillis >= startLoggingAfter.toMillis();
438	                        if (logging) {
439	                            LOG.info("Trying to connect to address {}", targetAddress);
440	                        }
441	
442	                        do {
443	                            InetAddress address =
444	                                    ConnectionUtils.findAddressUsingStrategy(
445	                                            strategy, targetAddress, logging);
446	                            if (address != null) {
447	                                return address;
448	                            }
449	
450	                            // pick the next strategy
451	                            switch (strategy) {
452	                                case LOCAL_HOST:
453	                                    strategy = AddressDetectionState.ADDRESS;
454	                                    break;
455	                                case ADDRESS:
456	                                    strategy = AddressDetectionState.FAST_CONNECT;
457	                                    break;
458	                                case FAST_CONNECT:
459	                                    strategy = AddressDetectionState.SLOW_CONNECT;
460	                                    break;
461	                                case SLOW_CONNECT:
462	                                    strategy = null;
463	                                    break;
464	                                default:
465	                                    throw new RuntimeException("Unsupported strategy: " + strategy);
466	                            }
467	                        } while (strategy != null);
468	                    }
469	
470	                    elapsedTimeMillis = (System.nanoTime() - startTimeNanos) / 1_000_000;
471	
472	                    long timeToWait =
473	                            Math.min(
474	                                    Math.max(timeout.toMillis() - elapsedTimeMillis, 0),
475	                                    currentSleepTime);
476	
477	                    if (timeToWait > 0) {
478	                        synchronized (retrievalLock) {
479	                            try {
480	                                retrievalLock.wait(timeToWait);
481	                            } catch (InterruptedException e) {
482	                                throw new Exception(
483	                                        "Finding connecting address was interrupted while pausing.");
484	                            }
485	                        }
486	
487	                        elapsedTimeMillis = (System.nanoTime() - startTimeNanos) / 1_000_000;
488	                    }
489	                }
490	
491	                InetAddress heuristic = null;
492	
493	                if (targetAddress != null) {
494	                    LOG.warn(
495	                            "Could not connect to {}. Selecting a local address using heuristics.",
496	                            targetAddress);
497	                    heuristic =
498	                            findAddressUsingStrategy(
499	                                    AddressDetectionState.HEURISTIC, targetAddress, true);
500	                }
501	
502	                if (heuristic != null) {
503	                    return heuristic;
504	                } else {
505	                    LOG.warn(
506	                            "Could not find any IPv4 address that is not loopback or link-local. Using localhost address.");
507	                    return InetAddress.getLocalHost();
508	                }
509	            } catch (Exception e) {
510	                throw new LeaderRetrievalException(
511	                        "Could not retrieve the connecting address to the "
512	                                + "current leader with the pekko URL "
513	                                + rpcURL
514	                                + ".",
515	                        e);
516	            }
517	        }
518	
519	        @Override
520	        public void notifyLeaderAddress(String leaderAddress, UUID leaderSessionID) {
521	            if (leaderAddress != null && !leaderAddress.isEmpty()) {
522	                synchronized (retrievalLock) {
523	                    rpcURL = leaderAddress;
524	                    retrievalState = LeaderRetrievalState.NEWLY_RETRIEVED;
525	
526	                    retrievalLock.notifyAll();
527	                }
528	            }
529	        }
530	
531	        @Override
532	        public void handleError(Exception exception) {
533	            synchronized (retrievalLock) {
534	                this.exception = exception;
535	                retrievalLock.notifyAll();
536	            }
537	        }
538	    }
539	}

