45	public class HandlerRedirectUtils {
46	
47	    public static final Charset ENCODING = ConfigConstants.DEFAULT_CHARSET;
48	
49	    public static HttpResponse getRedirectResponse(
50	            String redirectAddress, String path, HttpResponseStatus code) {
51	        checkNotNull(redirectAddress, "Redirect address");
52	        checkNotNull(path, "Path");
53	
54	        String newLocation = String.format("%s%s", redirectAddress, path);
55	
56	        HttpResponse redirectResponse = new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, code);
57	        redirectResponse.headers().set(HttpHeaderNames.LOCATION, newLocation);
58	        redirectResponse.headers().set(HttpHeaderNames.CONTENT_LENGTH, 0);
59	
60	        return redirectResponse;
61	    }
62	
63	    public static HttpResponse getResponse(HttpResponseStatus status, @Nullable String message) {
64	        ByteBuf messageByteBuf =
65	                message == null
66	                        ? Unpooled.buffer(0)
67	                        : Unpooled.wrappedBuffer(message.getBytes(ENCODING));
68	        FullHttpResponse response =
69	                new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, status, messageByteBuf);
70	        response.headers()
71	                .set(HttpHeaderNames.CONTENT_TYPE, "text/plain; charset=" + ENCODING.name());
72	        response.headers().set(HttpHeaderNames.CONTENT_LENGTH, response.content().readableBytes());
73	
74	        return response;
75	    }
