import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

/** Tests for {@link ConnectionUtils}. */
class ConnectionUtilsTest {

    @Test
    void findConnectingAddressRejectsNullTargetAddress() {
        final NullPointerException exception =
                assertThrows(
                        NullPointerException.class,
                        () -> ConnectionUtils.findConnectingAddress(null, 100L, 0L));

        assertEquals("targetAddress must not be null", exception.getMessage());
    }

    @Test
    void findConnectingAddressRejectsNonPositiveMaximumWaitTime() {
        final InetSocketAddress target =
                new InetSocketAddress(InetAddress.getLoopbackAddress(), 1);

        final IllegalArgumentException zeroWait =
                assertThrows(
                        IllegalArgumentException.class,
                        () -> ConnectionUtils.findConnectingAddress(target, 0L, 0L));
        final IllegalArgumentException negativeWait =
                assertThrows(
                        IllegalArgumentException.class,
                        () -> ConnectionUtils.findConnectingAddress(target, -1L, 0L));

        assertEquals("Max wait time must be positive", zeroWait.getMessage());
        assertEquals("Max wait time must be positive", negativeWait.getMessage());
    }

    @Test
    void findConnectingAddressReturnsLocalAddressForReachableTarget() throws Exception {
        try (ServerSocket target =
                new ServerSocket(0, 5, InetAddress.getLoopbackAddress())) {
            final InetSocketAddress targetAddress =
                    new InetSocketAddress(InetAddress.getLoopbackAddress(), target.getLocalPort());

            final InetAddress connectingAddress =
                    ConnectionUtils.findConnectingAddress(targetAddress, 5_000L, 0L);

            assertAssignedToLocalInterface(connectingAddress);
        }
    }

    @Test
    void findConnectingAddressFallsBackToLocalAddressWhenTargetIsUnreachable()
            throws Exception {
        final int closedPort;
        try (ServerSocket socket = new ServerSocket(0, 1, InetAddress.getLoopbackAddress())) {
            closedPort = socket.getLocalPort();
        }

        final InetAddress connectingAddress =
                ConnectionUtils.findConnectingAddress(
                        new InetSocketAddress(InetAddress.getLoopbackAddress(), closedPort),
                        100L,
                        0L);

        assertAssignedToLocalInterface(connectingAddress);
    }

    @Test
    void leaderListenerUsesNotifiedLeaderAndReturnsConnectingAddress() throws Exception {
        try (ServerSocket target =
                new ServerSocket(0, 5, InetAddress.getLoopbackAddress())) {
            final InetSocketAddress targetAddress =
                    new InetSocketAddress(InetAddress.getLoopbackAddress(), target.getLocalPort());
            final String rpcUrl = "rpc://leader:1234";
            final RpcSystemUtils rpcSystemUtils = mock(RpcSystemUtils.class);
            when(rpcSystemUtils.getInetSocketAddressFromRpcUrl(rpcUrl))
                    .thenReturn(targetAddress);

            final ConnectionUtils.LeaderConnectingAddressListener listener =
                    new ConnectionUtils.LeaderConnectingAddressListener(rpcSystemUtils);

            final ExecutorService executor = Executors.newSingleThreadExecutor();
            try {
                final Future<InetAddress> result =
                        executor.submit(
                                () ->
                                        listener.findConnectingAddress(
                                                Duration.ofSeconds(5), Duration.ZERO));

                Thread.sleep(100L);
                listener.notifyLeaderAddress(rpcUrl, UUID.randomUUID());

                assertAssignedToLocalInterface(result.get(10, TimeUnit.SECONDS));
                verify(rpcSystemUtils).getInetSocketAddressFromRpcUrl(rpcUrl);
            } finally {
                executor.shutdownNow();
            }
        }
    }

    @Test
    void leaderListenerIgnoresEmptyLeaderAddress() throws Exception {
        final RpcSystemUtils rpcSystemUtils = mock(RpcSystemUtils.class);
        final ConnectionUtils.LeaderConnectingAddressListener listener =
                new ConnectionUtils.LeaderConnectingAddressListener(rpcSystemUtils);

        listener.notifyLeaderAddress(null, null);
        listener.notifyLeaderAddress("", UUID.randomUUID());

        assertAssignedToLocalInterface(
                listener.findConnectingAddress(Duration.ofMillis(100), Duration.ZERO));
        verifyNoInteractions(rpcSystemUtils);
    }

    @Test
    void leaderListenerReportsLeaderRetrievalErrors() {
        final ConnectionUtils.LeaderConnectingAddressListener listener =
                new ConnectionUtils.LeaderConnectingAddressListener(mock(RpcSystemUtils.class));
        final RuntimeException retrievalError = new RuntimeException("leader lookup failed");

        listener.handleError(retrievalError);

        final LeaderRetrievalException exception =
                assertThrows(
                        LeaderRetrievalException.class,
                        () -> listener.findConnectingAddress(Duration.ofSeconds(1)));
        assertSame(retrievalError, exception.getCause());
        assertTrue(exception.getMessage().contains("Could not retrieve the connecting address"));
    }

    private static void assertAssignedToLocalInterface(InetAddress address) throws SocketException {
        assertNotNull(address);
        assertNotNull(
                NetworkInterface.getByInetAddress(address),
                "Address is not assigned to a local network interface: " + address);
    }
}
