        final InetSocketAddress localAddress =
                new InetSocketAddress("127.0.0.1", 31_234);
        final EmbeddedChannel channel =
                new LocalAddressEmbeddedChannel(localAddress, handler);

        try {
            writeHttpRequest(channel, "GET /health HTTP/1.1\r\nHost: localhost\r\n\r\n");
            channel.finish();

            final HttpResponse response = channel.readOutbound();
            assertNotNull(response);
            assertEquals(HttpResponseStatus.MOVED_PERMANENTLY, response.status());
            assertEquals(
                    "https://gateway.example.org:31234/health",
                    response.headers().get(HttpHeaderNames.LOCATION));
        } finally {
            channel.finishAndReleaseAll();
        }
    }

    @Test
    void completedRedirectBaseUrlTakesPrecedenceOverConfiguredHostAndLocalPort()
            throws Exception {
        final SSLHandlerFactory factory = mock(SSLHandlerFactory.class);
        final RedirectingSslHandler handler =
                new RedirectingSslHandler(
                        "ignored.example.org",
                        CompletableFuture.completedFuture("https://external.example.org:9443"),
                        factory);
        final EmbeddedChannel channel =
                new LocalAddressEmbeddedChannel(
                        new InetSocketAddress("127.0.0.1", 31_234), handler);

        try {
            writeHttpRequest(channel, "GET /overview HTTP/1.1\r\nHost: localhost\r\n\r\n");
            channel.finish();

