import static org.apache.flink.shaded.netty4.io.netty.handler.ssl.SslProvider.JDK;
import static org.apache.flink.shaded.netty4.io.netty.handler.ssl.SslProvider.OPENSSL;
import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Tests for {@link SSLUtils}. */
class SSLUtilsTest {

    private static final String TEST_PASSWORD = "password";
    private static final String TEST_PROTOCOL = "TLSv1.2";
    private static final String TEST_CIPHER = "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256";

    @Test
    void defaultSslProviderIsJdk() {
        assertEquals(JDK, SSLUtils.getSSLProvider(new Configuration()));
    }

    @Test
    void sslProviderParsingIsCaseInsensitiveAndRejectsUnknownValues() {
        final Configuration configuration = new Configuration();
        configuration.set(SecurityOptions.SSL_PROVIDER, "jdk");
        assertEquals(JDK, SSLUtils.getSSLProvider(configuration));

        configuration.set(SecurityOptions.SSL_PROVIDER, "OpEnSsL");
        if (OpenSsl.isAvailable()) {
            assertEquals(OPENSSL, SSLUtils.getSSLProvider(configuration));
        } else {
            final IllegalConfigurationException exception =
                    assertThrows(
                            IllegalConfigurationException.class,
                            () -> SSLUtils.getSSLProvider(configuration));
            assertTrue(exception.getMessage().contains("openSSL not available"));
        }

        configuration.set(SecurityOptions.SSL_PROVIDER, "not-a-provider");
        final IllegalConfigurationException unknownProvider =
                assertThrows(
                        IllegalConfigurationException.class,
                        () -> SSLUtils.getSSLProvider(configuration));
        assertTrue(unknownProvider.getMessage().contains("Unknown SSL provider"));
        assertTrue(unknownProvider.getMessage().contains("not-a-provider"));
    }

    @Test
    void disabledSslRejectsAllPublicFactoryMethods() {
        final Configuration disabled = new Configuration();

        assertThrows(
                IllegalConfigurationException.class,
                () -> SSLUtils.createSSLServerSocketFactory(disabled));
        assertThrows(
                IllegalConfigurationException.class,
                () -> SSLUtils.createSSLClientSocketFactory(disabled));
        assertThrows(
                IllegalConfigurationException.class,
                () -> SSLUtils.createInternalServerSSLEngineFactory(disabled));
        assertThrows(
                IllegalConfigurationException.class,
                () -> SSLUtils.createInternalClientSSLEngineFactory(disabled));
        assertThrows(
                IllegalConfigurationException.class,
                () -> SSLUtils.createRestServerSSLEngineFactory(disabled));
        assertThrows(
                IllegalConfigurationException.class,
                () -> SSLUtils.createRestClientSSLEngineFactory(disabled));
    }

    @Test
    void internalServerSocketFactoryConfiguresProtocolsCipherSuitesAndClientAuth()
            throws Exception {
        final Configuration configuration = internalSslConfiguration();
        configuration.set(SecurityOptions.SSL_PROTOCOL, TEST_PROTOCOL);
        configuration.set(SecurityOptions.SSL_ALGORITHMS, TEST_CIPHER);

        final ServerSocketFactory factory = SSLUtils.createSSLServerSocketFactory(configuration);
        try (ServerSocket serverSocket =
                factory.createServerSocket(0, 1, InetAddress.getLoopbackAddress())) {
            assertTrue(serverSocket instanceof SSLServerSocket);
            final SSLServerSocket sslServerSocket = (SSLServerSocket) serverSocket;

            assertArrayEquals(new String[] {TEST_PROTOCOL}, sslServerSocket.getEnabledProtocols());
            assertArrayEquals(new String[] {TEST_CIPHER}, sslServerSocket.getEnabledCipherSuites());
            assertTrue(sslServerSocket.getNeedClientAuth());
        }
    }

    @Test
    void internalHandlerFactoriesConfigureEngineModeAndTimeouts() throws Exception {
        final Configuration configuration = internalSslConfiguration();
        configuration.set(SecurityOptions.SSL_PROTOCOL, TEST_PROTOCOL);
        configuration.set(SecurityOptions.SSL_ALGORITHMS, TEST_CIPHER);
        configuration.set(SecurityOptions.SSL_INTERNAL_HANDSHAKE_TIMEOUT, 3_210);
        configuration.set(SecurityOptions.SSL_INTERNAL_CLOSE_NOTIFY_FLUSH_TIMEOUT, 6_543);

        final SSLHandlerFactory serverFactory =
                SSLUtils.createInternalServerSSLEngineFactory(configuration);
        final SSLHandlerFactory clientFactory =
                SSLUtils.createInternalClientSSLEngineFactory(configuration);

        final SslHandler serverHandler =
                serverFactory.createNettySSLHandler(UnpooledByteBufAllocator.DEFAULT);
        final SslHandler clientHandler =
                clientFactory.createNettySSLHandler(
                        UnpooledByteBufAllocator.DEFAULT, "localhost", 1234);

        assertFalse(serverHandler.engine().getUseClientMode());
        assertTrue(clientHandler.engine().getUseClientMode());
        assertArrayEquals(
                new String[] {TEST_PROTOCOL}, serverHandler.engine().getEnabledProtocols());
        assertArrayEquals(
                new String[] {TEST_CIPHER}, serverHandler.engine().getEnabledCipherSuites());
        assertEquals(3_210L, serverHandler.getHandshakeTimeoutMillis());
        assertEquals(6_543L, serverHandler.getCloseNotifyFlushTimeoutMillis());
        assertEquals(3_210L, clientHandler.getHandshakeTimeoutMillis());
        assertEquals(6_543L, clientHandler.getCloseNotifyFlushTimeoutMillis());
    }

    @Test
    void internalClientAndServerSocketFactoriesCompleteMutualTlsHandshake() throws Exception {
        final Configuration configuration = internalSslConfiguration();
        configuration.set(SecurityOptions.SSL_PROTOCOL, TEST_PROTOCOL);
        configuration.set(SecurityOptions.SSL_ALGORITHMS, TEST_CIPHER);

        final ServerSocketFactory serverSocketFactory =
                SSLUtils.createSSLServerSocketFactory(configuration);
        final SocketFactory clientSocketFactory =
                SSLUtils.createSSLClientSocketFactory(configuration);

        final ExecutorService executor = Executors.newSingleThreadExecutor();
        try (ServerSocket serverSocket =
                serverSocketFactory.createServerSocket(0, 1, InetAddress.getLoopbackAddress())) {
            final Future<Principal> serverPeer =
                    executor.submit(
                            () -> {
                                try (SSLSocket socket = (SSLSocket) serverSocket.accept()) {
                                    socket.setSoTimeout(5_000);
                                    socket.startHandshake();
                                    return socket.getSession().getPeerPrincipal();
                                }
                            });

            try (Socket socket =
                    clientSocketFactory.createSocket(
                            InetAddress.getLoopbackAddress(), serverSocket.getLocalPort())) {
                socket.setSoTimeout(5_000);
                final SSLSocket sslSocket = (SSLSocket) socket;
                sslSocket.startHandshake();
                assertNotNull(sslSocket.getSession().getPeerPrincipal());
            }

            assertNotNull(serverPeer.get(10, TimeUnit.SECONDS));
        } finally {
            executor.shutdownNow();
        }
    }

    @Test
    void restContextsUseExpectedEngineModesAndClientAuth() throws Exception {
        final Configuration configuration = restSslConfiguration();
        configuration.set(SecurityOptions.SSL_PROTOCOL, TEST_PROTOCOL);
        configuration.set(SecurityOptions.SSL_ALGORITHMS, TEST_CIPHER);

        final SslContext serverContext =
                SSLUtils.createRestNettySSLContext(
                        configuration, false, ClientAuth.NONE, SslProvider.JDK);
        final SslContext clientContext =
                SSLUtils.createRestNettySSLContext(
                        configuration, true, ClientAuth.NONE, SslProvider.JDK);
        final SslContext mutualServerContext =
                SSLUtils.createRestNettySSLContext(
                        configuration, false, ClientAuth.REQUIRE, SslProvider.JDK);

        assertFalse(serverContext.newEngine(UnpooledByteBufAllocator.DEFAULT).getUseClientMode());
        assertFalse(serverContext.newEngine(UnpooledByteBufAllocator.DEFAULT).getNeedClientAuth());
        assertTrue(clientContext.newEngine(UnpooledByteBufAllocator.DEFAULT).getUseClientMode());
        assertTrue(
                mutualServerContext
                        .newEngine(UnpooledByteBufAllocator.DEFAULT)
                        .getNeedClientAuth());

        assertNotNull(SSLUtils.createRestSSLContext(configuration, false));
        assertNotNull(SSLUtils.createRestSSLContext(configuration, true));
        assertNotNull(SSLUtils.createRestServerSSLEngineFactory(configuration));
        assertNotNull(SSLUtils.createRestClientSSLEngineFactory(configuration));
    }

    @Test
    void restClientFallsBackToProviderTrustStoreWhenNoTrustStoreIsConfigured() throws Exception {
        final Configuration configuration = restSslConfigurationWithoutTrustStore();

        final SslContext clientContext =
                SSLUtils.createRestNettySSLContext(
                        configuration, true, ClientAuth.NONE, SslProvider.JDK);

        assertTrue(clientContext.newEngine(UnpooledByteBufAllocator.DEFAULT).getUseClientMode());
    }

    @Test
    void missingKeystoreIsReportedWithTheRelevantConfigurationOptions() {
        final Configuration configuration = new Configuration();
        configuration.set(SecurityOptions.SSL_INTERNAL_ENABLED, true);

        final IllegalConfigurationException exception =
                assertThrows(
                        IllegalConfigurationException.class,
                        () -> SSLUtils.createInternalServerSSLEngineFactory(configuration));

        assertTrue(exception.getMessage().contains(SecurityOptions.SSL_INTERNAL_KEYSTORE.key()));
        assertTrue(exception.getMessage().contains(SecurityOptions.SSL_KEYSTORE.key()));
    }

    @Test
    void missingTrustStorePasswordIsReported() {
        final Configuration configuration = internalSslConfigurationWithoutTrustStorePassword();

        final IllegalConfigurationException exception =
                assertThrows(
                        IllegalConfigurationException.class,
                        () -> SSLUtils.createInternalServerSSLEngineFactory(configuration));

        assertTrue(
                exception
                        .getMessage()
                        .contains(SecurityOptions.SSL_INTERNAL_TRUSTSTORE_PASSWORD.key()));
    }

