            return name.matches("^\\d+\\..*") && super.isTransientMetric(name);
        }

        void retainSubtasks(Set<Integer> activeSubtasks) {
            // Retain metrics of pattern subtaskIndex.metricName which are directly stored in
            // TaskMetricStore
            metrics.keySet()
                    .removeIf(
