        assertNotNull(taskStore.getSubtaskMetricStore(0).getAttemptsMetricStore(0));
        assertNotNull(taskStore.getSubtaskMetricStore(0).getAttemptsMetricStore(1));

        store.updateCurrentExecutionAttempts(
                Collections.singletonList(
                        jobDetails(JOB_ID, currentAttempts(VERTEX_ID, 0, 1, setOf(1), false))));

        final TaskMetricStore afterUpdate = store.getTaskMetricStore(JOB_ID, VERTEX_ID);
        assertNull(afterUpdate.getSubtaskMetricStore(0).getAttemptsMetricStore(0));
        assertNotNull(afterUpdate.getSubtaskMetricStore(0).getAttemptsMetricStore(1));
    }

    @Test
    void testTerminalSubtaskRemovesTransientMetrics() {
        final MetricStore store = new MetricStore();
        store.updateCurrentExecutionAttempts(
                Collections.singletonList(
                        jobDetails(JOB_ID, currentAttempts(VERTEX_ID, 0, 0, setOf(0), false))));

        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.TaskQueryScopeInfo(JOB_ID, VERTEX_ID, 0, 0),
                        MetricNames.TASK_IDLE_TIME,
                        "5"));
        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.TaskQueryScopeInfo(JOB_ID, VERTEX_ID, 0, 0),
                        MetricNames.TASK_BUSY_TIME,
                        "6"));
        store.add(
                new MetricDump.GaugeDump(
                        new QueryScopeInfo.TaskQueryScopeInfo(JOB_ID, VERTEX_ID, 0, 0),
                        "numRecords",
                        "100"));

        final TaskMetricStore taskStore = store.getTaskMetricStore(JOB_ID, VERTEX_ID);
        assertEquals("5", taskStore.getMetric("0." + MetricNames.TASK_IDLE_TIME));
        assertEquals(
                "6", taskStore.getSubtaskMetricStore(0).getMetric(MetricNames.TASK_BUSY_TIME));

        store.updateCurrentExecutionAttempts(
                Collections.singletonList(
                        jobDetails(JOB_ID, currentAttempts(VERTEX_ID, 0, 0, setOf(0), true))));

        final TaskMetricStore afterUpdate = store.getTaskMetricStore(JOB_ID, VERTEX_ID);
        assertNull(afterUpdate.getMetric("0." + MetricNames.TASK_IDLE_TIME));
        assertNull(afterUpdate.getSubtaskMetricStore(0).getMetric(MetricNames.TASK_IDLE_TIME));
        assertNull(afterUpdate.getSubtaskMetricStore(0).getMetric(MetricNames.TASK_BUSY_TIME));
        // Non-transient metrics are kept
        assertEquals("100", afterUpdate.getMetric("0.numRecords"));
        assertEquals("100", afterUpdate.getSubtaskMetricStore(0).getMetric("numRecords"));
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static QueryScopeInfo.JobManagerQueryScopeInfo jmScope(String scope) {
        return new QueryScopeInfo.JobManagerQueryScopeInfo(scope);
    }

    private static JobDetails jobDetails(
            String jobId, Map<String, Map<Integer, CurrentAttempts>> currentAttempts) {
        return new JobDetails(
                JobID.fromHexString(jobId),
                "job",
                0L,
                -1L,
                0L,
                JobStatus.RUNNING,
                0L,
                new int[ExecutionState.values().length],
                0,
                currentAttempts);
    }

    private static Map<String, Map<Integer, CurrentAttempts>> currentAttempts(
            String vertexId,
            int subtaskIndex,
            int representativeAttempt,
            Set<Integer> attempts,
            boolean terminal) {
        final Map<Integer, CurrentAttempts> subtaskAttempts = new HashMap<>();
        subtaskAttempts.put(
                subtaskIndex, new CurrentAttempts(representativeAttempt, attempts, terminal));
        final Map<String, Map<Integer, CurrentAttempts>> vertexAttempts = new HashMap<>();
        vertexAttempts.put(vertexId, subtaskAttempts);
        return vertexAttempts;
    }

    private static Set<Integer> setOf(Integer... values) {
        return new HashSet<>(Arrays.asList(values));
    }
