        final Configuration configuration = new Configuration();
        configuration.set(WebOptions.TIMEOUT, Duration.ofMillis(1234L));
        configuration.set(
                MetricOptions.METRIC_FETCHER_UPDATE_INTERVAL, Duration.ofMillis(60_000L));

        final ExecutorService executor = Executors.newDirectExecutorService();
        try {
            final MetricFetcherImpl<RestfulGateway> fetcher =
                    MetricFetcherImpl.fromConfiguration(
                            configuration, queryServiceRetriever, leaderRetriever(), executor);

