            final long firstUpdateTime = fetcher.getLastUpdateTime();
            assertTrue(firstUpdateTime > 0L);

            fetcher.update();
            assertEquals(firstUpdateTime, fetcher.getLastUpdateTime());
        } finally {
            executor.shutdown();
        }
