/** Behavior tests for {@link RexBuilder}. */
class RexBuilderTest {
    private RelDataTypeFactory typeFactory;
    private RexBuilder rexBuilder;
    private RelDataType intType;
    private RelDataType nonNullIntType;
    private RexInputRef intRef;

    @BeforeEach
    void setUp() {
        typeFactory = new JavaTypeFactoryImpl();
        rexBuilder = new RexBuilder(typeFactory);
        intType = typeFactory.createTypeWithNullability(
                typeFactory.createSqlType(SqlTypeName.INTEGER), true);
        nonNullIntType = typeFactory.createTypeWithNullability(
                typeFactory.createSqlType(SqlTypeName.INTEGER), false);
        intRef = rexBuilder.makeInputRef(intType, 3);
    }

    @Test
    void exposesTypeFactoryAndOperatorTable() {
        assertSame(typeFactory, rexBuilder.getTypeFactory());
        assertNotNull(rexBuilder.getOpTab());
        assertSame(SqlStdOperatorTable.instance(), rexBuilder.getOpTab());
    }

    @Test
    void identityProjectsReturnOneInputRefPerField() {
        RelDataType rowType = typeFactory.builder()
                .add("id", nonNullIntType)
                .add("amount", typeFactory.createSqlType(SqlTypeName.BIGINT))
                .build();

        List<RexNode> projects = rexBuilder.identityProjects(rowType);

        assertEquals(2, projects.size());
        assertInstanceOf(RexInputRef.class, projects.get(0));
        assertEquals(0, ((RexInputRef) projects.get(0)).getIndex());
        assertEquals(1, ((RexInputRef) projects.get(1)).getIndex());
        assertEquals(rowType.getFieldList().get(0).getType(), projects.get(0).getType());
        assertEquals(rowType.getFieldList().get(1).getType(), projects.get(1).getType());
    }

    @Test
    void makesFieldAccessByOrdinalAndName() {
        RelDataType rowType = typeFactory.builder()
                .add("id", nonNullIntType)
                .add("label", typeFactory.createSqlType(SqlTypeName.VARCHAR, 10))
                .build();
        RelDataType nullableRowType = typeFactory.createTypeWithNullability(rowType, true);
        RexInputRef rowRef = rexBuilder.makeInputRef(nullableRowType, 0);

        RexNode byOrdinal = rexBuilder.makeFieldAccess(rowRef, 1);
        RexNode byName = rexBuilder.makeFieldAccess(rowRef, "LABEL", false);

        assertInstanceOf(RexFieldAccess.class, byOrdinal);
        assertEquals("label", ((RexFieldAccess) byOrdinal).getField().getName());
        assertEquals(byOrdinal, byName);
        assertTrue(byOrdinal.getType().isNullable());
        assertThrows(AssertionError.class, () -> rexBuilder.makeFieldAccess(rowRef, 2));
        assertThrows(AssertionError.class, () -> rexBuilder.makeFieldAccess(rowRef, "missing", false));
        assertThrows(AssertionError.class, () -> rexBuilder.makeFieldAccess(rowRef, "LABEL", true));
    }

    @Test
    void makeCallDerivesTypeAndPreservesOperands() {
        RexLiteral two = rexBuilder.makeExactLiteral(BigDecimal.valueOf(2));
        RexNode sum = rexBuilder.makeCall(SqlStdOperatorTable.PLUS, intRef, two);

        assertInstanceOf(RexCall.class, sum);
        assertEquals(SqlKind.PLUS, sum.getKind());
        assertEquals(2, ((RexCall) sum).getOperands().size());
        assertSame(intRef, ((RexCall) sum).getOperands().get(0));
        assertSame(two, ((RexCall) sum).getOperands().get(1));
        assertEquals(SqlTypeName.INTEGER, sum.getType().getSqlTypeName());
    }

    @Test
    void makeCallWithExplicitReturnTypeUsesThatType() {
        RelDataType bigintType = typeFactory.createSqlType(SqlTypeName.BIGINT);

        RexNode call = rexBuilder.makeCall(bigintType, SqlStdOperatorTable.PLUS, ImmutableList.of(intRef));

        assertSame(bigintType, call.getType());
        assertEquals(SqlKind.PLUS, call.getKind());
    }

    @Test
    void booleanAndEmptyStringLiteralsAreReused() {
        assertSame(rexBuilder.makeLiteral(true), rexBuilder.makeLiteral(true));
        assertSame(rexBuilder.makeLiteral(false), rexBuilder.makeLiteral(false));
        assertSame(rexBuilder.makeLiteral(""), rexBuilder.makeLiteral(""));
        assertTrue(rexBuilder.makeLiteral(true).getValueAs(Boolean.class));
        assertFalse(rexBuilder.makeLiteral(false).getValueAs(Boolean.class));
    }

    @Test
    void createsNumericLiteralsWithAppropriateTypes() {
        RexLiteral exactInt = rexBuilder.makeExactLiteral(BigDecimal.valueOf(42));
        RexLiteral exactDecimal = rexBuilder.makeExactLiteral(new BigDecimal("12.30"));
        RexLiteral bigint = rexBuilder.makeBigintLiteral(BigDecimal.valueOf(9));
        RexLiteral approx = rexBuilder.makeApproxLiteral(new BigDecimal("1.25"));

        assertEquals(SqlTypeName.INTEGER, exactInt.getType().getSqlTypeName());
        assertEquals(new BigDecimal("42"), exactInt.getValue());
        assertEquals(SqlTypeName.DECIMAL, exactDecimal.getType().getSqlTypeName());
        assertEquals(4, exactDecimal.getType().getPrecision());
        assertEquals(2, exactDecimal.getType().getScale());
        assertEquals(SqlTypeName.BIGINT, bigint.getType().getSqlTypeName());
        assertEquals(SqlTypeName.DOUBLE, approx.getType().getSqlTypeName());
