        assertEquals("Flink", string.getValueAs(String.class));
        assertEquals(SqlTypeName.DATE, date.getType().getSqlTypeName());
        assertEquals(new DateString(2024, 2, 29), date.getValue());
        assertEquals(SqlTypeName.TIME, time.getType().getSqlTypeName());
        assertEquals(new TimeString("12:34:56"), time.getValue());
        assertEquals(SqlTypeName.TIMESTAMP, timestamp.getType().getSqlTypeName());
        assertEquals(new TimestampString("2024-02-29 12:34:56"), timestamp.getValue());
        assertEquals(SqlTypeName.UUID, uuidLiteral.getType().getSqlTypeName());
        assertEquals(uuid, uuidLiteral.getValueAs(UUID.class));
    }

