        assertFalse(nonNullRange.getType().isNullable());
        assertEquals(2, nullableRange.getOffset());
        assertTrue(nullableRange.getType().isNullable());
    }

    @Test
    void makeInUsesSearchForLiteralsAndOrForExpressions() {
        RexLiteral one = rexBuilder.makeExactLiteral(BigDecimal.ONE);
        RexLiteral two = rexBuilder.makeExactLiteral(BigDecimal.valueOf(2));

        RexNode single = rexBuilder.makeIn(intRef, ImmutableList.of(one));
        RexNode multiple = rexBuilder.makeIn(intRef, ImmutableList.of(one, two));
        RexNode expressionBound = rexBuilder.makeCall(SqlStdOperatorTable.PLUS, intRef, one);
        RexNode mixed = rexBuilder.makeIn(intRef, ImmutableList.of(expressionBound, two));
        RexNode empty = rexBuilder.makeIn(intRef, ImmutableList.of());

        assertEquals(SqlKind.EQUALS, single.getKind());
        assertEquals(SqlKind.SEARCH, multiple.getKind());
        assertEquals(SqlTypeName.SARG, ((RexLiteral) ((RexCall) multiple).getOperands().get(1)).getTypeName());
        assertEquals(SqlKind.OR, mixed.getKind());
        assertEquals(2, ((RexCall) mixed).getOperands().size());
        assertTrue(empty.isAlwaysFalse());
    }

    @Test
    void makeBetweenUsesSearchForConstantsAndAndForExpressions() {
        RexLiteral one = rexBuilder.makeExactLiteral(BigDecimal.ONE);
        RexLiteral ten = rexBuilder.makeExactLiteral(BigDecimal.TEN);
        RexNode expressionLower = rexBuilder.makeCall(SqlStdOperatorTable.PLUS, intRef, one);

        RexNode constantBounds = rexBuilder.makeBetween(intRef, one, ten);
        RexNode expressionBounds = rexBuilder.makeBetween(intRef, expressionLower, ten);

        assertEquals(SqlKind.SEARCH, constantBounds.getKind());
        assertEquals(SqlKind.AND, expressionBounds.getKind());
        assertEquals(2, ((RexCall) expressionBounds).getOperands().size());
    }

    @Test
    void createsWindowAndWindowedAggregate() {
        RelDataType bigintType = typeFactory.createSqlType(SqlTypeName.BIGINT);
        RexWindow window = rexBuilder.makeWindow(
                ImmutableList.of(intRef),
                ImmutableList.of(),
                RexWindowBounds.UNBOUNDED_PRECEDING,
                RexWindowBounds.UNBOUNDED_FOLLOWING,
                true);

        RexNode over = rexBuilder.makeOver(
                bigintType,
                SqlStdOperatorTable.COUNT,
                ImmutableList.of(intRef),
                ImmutableList.of(intRef),
                ImmutableList.of(),
                RexWindowBounds.UNBOUNDED_PRECEDING,
                RexWindowBounds.UNBOUNDED_FOLLOWING,
                true,
                true,
                false,
                false,
                false);

        assertEquals(ImmutableList.of(intRef), window.partitionKeys);
        assertTrue(window.orderKeys.isEmpty());
        assertFalse(window.isRows());
        assertInstanceOf(RexOver.class, over);
        assertEquals(SqlKind.OVER, over.getKind());
        assertEquals(bigintType, over.getType());
        assertFalse(((RexOver) over).isDistinct());
    }

    @Test
    void addsAggregateCallOnceAndReusesItsInputReference() {
        RelDataType bigintType = typeFactory.createSqlType(SqlTypeName.BIGINT);
        AggregateCall aggCall = AggregateCall.create(
                SqlStdOperatorTable.SUM0,
                false,
                ImmutableList.of(0),
                -1,
                bigintType,
                "sum0");
        List<AggregateCall> aggCalls = new ArrayList<>();
        Map<AggregateCall, RexNode> mapping = new HashMap<>();

        RexNode first = rexBuilder.addAggCall(aggCall, 2, aggCalls, mapping, i -> true);
        RexNode second = rexBuilder.addAggCall(aggCall, 2, aggCalls, mapping, i -> true);

        assertSame(first, second);
        assertEquals(1, aggCalls.size());
        assertEquals(2, ((RexInputRef) first).getIndex());
        assertEquals(bigintType, first.getType());
    }

    @Test
    void createsNewInvocationAndFlagLiterals() {
        RelDataType rowType = typeFactory.builder().add("i", intType).build();
        RexNode newCall = rexBuilder.makeNewInvocation(rowType, ImmutableList.of(intRef));
        RexLiteral flag = rexBuilder.makeFlag(java.time.temporal.ChronoUnit.DAYS);

        assertEquals(SqlKind.NEW_SPECIFICATION, newCall.getKind());
        assertEquals(rowType, newCall.getType());
        assertEquals(SqlTypeName.SYMBOL, flag.getTypeName());
        assertEquals(java.time.temporal.ChronoUnit.DAYS, flag.getValue());
    }
}
