        nonNullIntType = typeFactory.createTypeWithNullability(
                typeFactory.createSqlType(SqlTypeName.INTEGER), false);
        bigintType = typeFactory.createTypeWithNullability(
                typeFactory.createSqlType(SqlTypeName.BIGINT), true);
        booleanType = typeFactory.createTypeWithNullability(
