    private RexLiteral intLiteral(long value) {
        return rexBuilder.makeExactLiteral(BigDecimal.valueOf(value));
    }

    private RexLiteral booleanLiteral(boolean value) {
        return rexBuilder.makeLiteral(value);
    }

    private RexNode eq(RexNode left, RexNode right) {
        return rexBuilder.makeCall(SqlStdOperatorTable.EQUALS, left, right);
    }

    private RexNode and(RexNode... nodes) {
        return rexBuilder.makeCall(SqlStdOperatorTable.AND, nodes);
    }

    private RexNode or(RexNode... nodes) {
        return rexBuilder.makeCall(SqlStdOperatorTable.OR, nodes);
    }

    @Test
    void getSelectivityUsesSentinelValueForUnknownOrTrue() {
        assertEquals(1d, RexUtil.getSelectivity(null));
        assertEquals(1d, RexUtil.getSelectivity(booleanLiteral(true)));
        assertEquals(0.1d, RexUtil.getSelectivity(eq(intRef, intLiteral(1))));
    }

    @Test
    void identifiesNullLiterals() {
        RexLiteral nullInt = rexBuilder.makeNullLiteral(intType);
        RexNode castNull = rexBuilder.makeAbstractCast(bigintType, nullInt);

        assertTrue(RexUtil.isNullLiteral(rexBuilder.constantNull(), true));
        assertFalse(RexUtil.isNullLiteral(nullInt, true));
        assertTrue(RexUtil.isNull(nullInt));
        assertTrue(RexUtil.isNull(castNull));
        assertFalse(RexUtil.isNull(intLiteral(1)));
        assertFalse(RexUtil.isNull(booleanLiteral(false)));
    }

    @Test
    void identifiesSymbolAndOtherLiterals() {
        RexLiteral flag = rexBuilder.makeFlag(java.time.temporal.ChronoUnit.DAYS);
        RexNode castLiteral = rexBuilder.makeAbstractCast(bigintType, intLiteral(1));
        RexNode castRef = rexBuilder.makeAbstractCast(bigintType, intRef);

        assertTrue(RexUtil.isSymbolLiteral(flag));
        assertFalse(RexUtil.isSymbolLiteral(intLiteral(1)));
        assertTrue(RexUtil.isLiteral(intLiteral(1), false));
        assertTrue(RexUtil.isLiteral(castLiteral, true));
        assertFalse(RexUtil.isLiteral(castLiteral, false));
        assertTrue(RexUtil.allLiterals(ImmutableList.of(intLiteral(1), castLiteral)));
        assertFalse(RexUtil.allLiterals(ImmutableList.of(intLiteral(1), castRef)));
    }

