        RelDataType rowType = typeFactory.builder().add("i", intType).build();
        RexInputRef rowRef = rexBuilder.makeInputRef(
                typeFactory.createTypeWithNullability(rowType, true), 0);
        RexNode fieldAccess = rexBuilder.makeFieldAccess(rowRef, 0);
        RexNode castRef = rexBuilder.makeAbstractCast(bigintType, intRef);

        assertTrue(RexUtil.isReferenceOrAccess(intRef, false));
        assertTrue(RexUtil.isReferenceOrAccess(fieldAccess, false));
        assertTrue(RexUtil.isReferenceOrAccess(castRef, true));
        assertFalse(RexUtil.isReferenceOrAccess(castRef, false));
        assertFalse(RexUtil.isReferenceOrAccess(eq(intRef, intLiteral(1)), true));
    }

    @Test
