        RexNode nonNullRef = rexBuilder.makeInputRef(nonNullIntType, 0);
        RexNode nullableCast = rexBuilder.makeNullable(nonNullRef);
        RexNode intToBigint = rexBuilder.makeAbstractCast(bigintType, intRef);

        assertTrue(RexUtil.isNullabilityCast(typeFactory, nullableCast));
        assertSame(nonNullRef, RexUtil.removeNullabilityCast(typeFactory, nullableCast));
        assertFalse(RexUtil.isNullabilityCast(typeFactory, intToBigint));
        assertSame(intRef, RexUtil.removeCast(intToBigint));
    }

