        RexNode constantSum = rexBuilder.makeCall(
                SqlStdOperatorTable.PLUS, intLiteral(1), intLiteral(2));
        RexNode refSum = rexBuilder.makeCall(
                SqlStdOperatorTable.PLUS, intRef, intLiteral(1));
        RexNode random = rexBuilder.makeCall(
                booleanType, SqlStdOperatorTable.RAND, ImmutableList.of());
        RexNode isOne = eq(intRef, intLiteral(1));
        RexNode plusOne = rexBuilder.makeCall(SqlStdOperatorTable.PLUS, intRef, intLiteral(1));

        assertTrue(RexUtil.isConstant(intLiteral(1)));
        assertTrue(RexUtil.isConstant(constantSum));
        assertFalse(RexUtil.isConstant(refSum));
