        RexNode castNull = rexBuilder.makeAbstractCast(bigintType, nullInt);

        assertTrue(RexUtil.isNullLiteral(rexBuilder.constantNull(), true));
        assertFalse(RexUtil.isNullLiteral(nullInt, true));
        assertTrue(RexUtil.isNull(nullInt));
