        assertTrue(RexUtil.containIdentity(identity, rowType, Litmus.IGNORE));
        assertFalse(RexUtil.isIdentity(reordered, rowType));
        assertFalse(RexUtil.containIdentity(reordered, rowType, Litmus.IGNORE));
    }

    @Test
    void composesAndFlattensConjunctions() {
        RexNode first = eq(intRef, intLiteral(1));
        RexNode second = eq(otherRef, intLiteral(2));
        RexNode nested = and(first, and(second, first));

        RexNode empty = RexUtil.composeConjunction(rexBuilder, ImmutableList.of());
        RexNode withTrue = RexUtil.composeConjunction(
                rexBuilder, ImmutableList.of(booleanLiteral(true), first));
        RexNode withFalse = RexUtil.composeConjunction(
                rexBuilder, ImmutableList.of(first, booleanLiteral(false)));
        RexCall flattened = (RexCall) RexUtil.composeConjunction(
                rexBuilder, ImmutableList.of(nested));

        assertTrue(empty.isAlwaysTrue());
        assertSame(first, withTrue);
        assertTrue(withFalse.isAlwaysFalse());
        assertEquals(SqlKind.AND, flattened.getKind());
        assertEquals(2, flattened.getOperands().size());
        assertEquals(ImmutableList.of(first, second), RexUtil.flattenAnd(ImmutableList.of(nested)));
    }

    @Test
    void composesAndFlattensDisjunctions() {
        RexNode first = eq(intRef, intLiteral(1));
        RexNode second = eq(otherRef, intLiteral(2));
        RexNode nested = or(first, or(second, first));

        RexNode empty = RexUtil.composeDisjunction(rexBuilder, ImmutableList.of());
        RexNode withFalse = RexUtil.composeDisjunction(
                rexBuilder, ImmutableList.of(booleanLiteral(false), first));
        RexNode withTrue = RexUtil.composeDisjunction(
                rexBuilder, ImmutableList.of(first, booleanLiteral(true)));
        RexCall flattened = (RexCall) RexUtil.composeDisjunction(
                rexBuilder, ImmutableList.of(nested));

        assertTrue(empty.isAlwaysFalse());
        assertSame(first, withFalse);
        assertTrue(withTrue.isAlwaysTrue());
        assertEquals(SqlKind.OR, flattened.getKind());
        assertEquals(2, flattened.getOperands().size());
        assertEquals(ImmutableList.of(first, second), RexUtil.flattenOr(ImmutableList.of(nested)));
    }

    @Test
    void convertsBetweenNormalForms() {
        RexNode a = rexBuilder.makeInputRef(booleanType, 0);
        RexNode b = rexBuilder.makeInputRef(booleanType, 1);
        RexNode c = rexBuilder.makeInputRef(booleanType, 2);

        RexNode cnf = RexUtil.toCnf(rexBuilder, or(and(a, b), c));
        RexNode dnf = RexUtil.toDnf(rexBuilder, and(or(a, b), c));

        assertEquals(SqlKind.AND, cnf.getKind());
        assertEquals(2, ((RexCall) cnf).getOperands().size());
        assertTrue(((RexCall) cnf).getOperands().stream()
                .allMatch(node -> node.getKind() == SqlKind.OR));
        assertEquals(SqlKind.OR, dnf.getKind());
        assertEquals(2, ((RexCall) dnf).getOperands().size());
        assertTrue(((RexCall) dnf).getOperands().stream()
                .allMatch(node -> node.getKind() == SqlKind.AND));
    }

    @Test
    void shiftsInputReferences() {
        RexNode expression = eq(intRef, otherRef);

        RexNode shifted = RexUtil.shift(expression, 5);
        RexNode partiallyShifted = RexUtil.shift(expression, 1, 4);
        List<RexNode> shiftedList = RexUtil.shift(ImmutableList.of(intRef, otherRef), 3);

        assertEquals(5, ((RexInputRef) ((RexCall) shifted).getOperands().get(0)).getIndex());
        assertEquals(6, ((RexInputRef) ((RexCall) shifted).getOperands().get(1)).getIndex());
        assertEquals(1, ((RexInputRef) ((RexCall) partiallyShifted).getOperands().get(0)).getIndex());
        assertEquals(5, ((RexInputRef) ((RexCall) partiallyShifted).getOperands().get(1)).getIndex());
        assertEquals(3, ((RexInputRef) shiftedList.get(0)).getIndex());
        assertEquals(4, ((RexInputRef) shiftedList.get(1)).getIndex());
        assertSame(expression, RexUtil.shift(expression, 0));
    }

    @Test
    void fixesInputRefNullabilityToMatchFields() {
        RexInputRef nullableRef = rexBuilder.makeInputRef(intType, 0);

        List<RexNode> result = RexUtil.fixUp(
                rexBuilder, ImmutableList.of(nullableRef), ImmutableList.of(nonNullIntType));

        RexInputRef fixed = (RexInputRef) result.get(0);
        assertEquals(0, fixed.getIndex());
        assertFalse(fixed.getType().isNullable());
        assertThrows(AssertionError.class, () -> RexUtil.fixUp(
                rexBuilder, ImmutableList.of(intRef), ImmutableList.of(bigintType)));
    }

    @Test
    void extractsTypesAndFamilies() {
        List<RelDataType> types = RexUtil.types(ImmutableList.of(intRef, intLiteral(1)));

        assertEquals(ImmutableList.of(intType, intLiteral(1).getType()), types);
        assertEquals(
                ImmutableList.of(intType.getFamily(), intType.getFamily()),
                RexUtil.families(types));
    }

    @Test
    void removesAllMatchingExpressions() {
        RexNode first = eq(intRef, intLiteral(1));
        List<RexNode> nodes = new ArrayList<>(ImmutableList.of(first, intLiteral(1), first));

        assertTrue(RexUtil.removeAll(nodes, first));
        assertEquals(ImmutableList.of(intLiteral(1)), nodes);
        assertFalse(RexUtil.removeAll(nodes, first));
    }

    @Test
    void simplifiesThroughConvenienceMethods() {
        RexNode isOne = eq(intRef, intLiteral(1));

        assertSame(isOne, RexUtil.simplify(rexBuilder, and(booleanLiteral(true), isOne)));
        assertTrue(RexUtil.simplify(rexBuilder, eq(intLiteral(1), intLiteral(2)), true)
                .isAlwaysFalse());
        assertTrue(RexUtil.not(RexUtil.not(isOne)).equals(isOne));
    }

    @Test
    void mapsKindsToOperatorsAndNegatesOrInvertsComparisons() {
        RexNode isOne = eq(intRef, intLiteral(1));
        RexCall comparison = (RexCall) rexBuilder.makeCall(
                SqlStdOperatorTable.LESS_THAN, intRef, intLiteral(1));

        assertSame(SqlStdOperatorTable.EQUALS, RexUtil.op(SqlKind.EQUALS));
        assertSame(SqlStdOperatorTable.AND, RexUtil.op(SqlKind.AND));
        assertThrows(AssertionError.class, () -> RexUtil.op(SqlKind.PLUS));
        assertEquals(SqlKind.NOT_EQUALS, RexUtil.negate(rexBuilder, (RexCall) isOne).getKind());
        assertNull(RexUtil.negate(
                rexBuilder,
                (RexCall) rexBuilder.makeCall(
                        SqlStdOperatorTable.IS_NULL, intRef)));
        RexCall inverted = (RexCall) RexUtil.invert(rexBuilder, comparison);
        assertEquals(SqlKind.GREATER_THAN, inverted.getKind());
        assertEquals(intLiteral(1), inverted.getOperands().get(0));
        assertEquals(intRef, inverted.getOperands().get(1));
    }

    @Test
    void andNotRemovesContradictoryEqualityTerms() {
        RexNode isTen = eq(intRef, intLiteral(10));
        RexNode isTwenty = eq(intRef, intLiteral(20));
        RexNode isThirty = eq(otherRef, intLiteral(30));

        RexNode result = RexUtil.andNot(rexBuilder, isTen, ImmutableList.of(isTwenty, isThirty));

        RexCall conjunction = (RexCall) result;
        assertEquals(SqlKind.AND, conjunction.getKind());
        assertEquals(2, conjunction.getOperands().size());
        assertEquals(isTen, conjunction.getOperands().get(0));
        assertEquals(SqlKind.NOT, conjunction.getOperands().get(1).getKind());
        assertEquals(isThirty, ((RexCall) conjunction.getOperands().get(1)).getOperands().get(0));
        assertSame(isTen, RexUtil.andNot(rexBuilder, isTen, ImmutableList.of(isTwenty)));
    }

    @Test
    void identifiesCasePredicates() {
        RexNode condition = rexBuilder.makeCall(SqlStdOperatorTable.IS_NOT_NULL, intRef);
        RexCall caseCall = (RexCall) rexBuilder.makeCall(
                intType,
                SqlStdOperatorTable.CASE,
                ImmutableList.of(condition, intLiteral(1), intLiteral(2)));

        assertTrue(RexUtil.isCasePredicate(caseCall, 0));
        assertFalse(RexUtil.isCasePredicate(caseCall, 1));
        assertFalse(RexUtil.isCasePredicate(caseCall, 2));
    }

    @Test
    void detectsCorrelationAndReturnsNonConstantColumns() {
        CorrelationId correlationId = new CorrelationId(1);
        RexNode correlation = rexBuilder.makeCorrel(intType, correlationId);
        RexNode condition = rexBuilder.makeCall(SqlStdOperatorTable.IS_NULL, correlation);

        assertEquals(
                ImmutableList.of(true, false),
                ImmutableList.of(
                        RexUtil.containsCorrelation(condition),
                        RexUtil.containsCorrelation(eq(intRef, intLiteral(1)))));
        assertEquals(
                com.google.common.collect.ImmutableBitSet.of(1),
                RexUtil.getNonConstColumns(
                        ImmutableList.of(intLiteral(1), intRef, intLiteral(2))));
    }

    @Test
    void identifiesAtomicExpressionsAndOperatorCalls() {
        RexNode plus = rexBuilder.makeCall(SqlStdOperatorTable.PLUS, intRef, intLiteral(1));

        assertTrue(RexUtil.isAtomic(intLiteral(1)));
        assertTrue(RexUtil.isAtomic(intRef));
        assertFalse(RexUtil.isAtomic(plus));
        assertTrue(RexUtil.isCallTo(plus, SqlStdOperatorTable.PLUS));
        assertFalse(RexUtil.isCallTo(plus, SqlStdOperatorTable.MINUS));
        assertFalse(RexUtil.isCallTo(intRef, SqlStdOperatorTable.PLUS));
    }

    @Test
    void checksLosslessCasts() {
        assertTrue(RexUtil.isLosslessCast(intType, bigintType));
        assertFalse(RexUtil.isLosslessCast(bigintType, intType));
        assertTrue(RexUtil.isLosslessCast(
                typeFactory.createSqlType(SqlTypeName.VARCHAR, 5),
                typeFactory.createSqlType(SqlTypeName.VARCHAR, 10)));
    }

    @Test
    void flattensNestedCalls() {
        RexNode a = eq(intRef, intLiteral(1));
        RexNode b = eq(otherRef, intLiteral(2));
        RexNode c = eq(intRef, intLiteral(3));
        RexCall nested = (RexCall) and(a, and(b, c));
        RexCall alreadyFlat = (RexCall) and(a, b, c);

        RexNode flattened = RexUtil.flatten(rexBuilder, nested);
        List<RexNode> flattenedOperands = RexUtil.flatten(
                ImmutableList.of(a, and(b, c)), SqlStdOperatorTable.AND);

        assertEquals(SqlKind.AND, flattened.getKind());
        assertEquals(3, ((RexCall) flattened).getOperands().size());
        assertSame(alreadyFlat, RexUtil.flatten(rexBuilder, alreadyFlat));
        assertEquals(ImmutableList.of(a, b, c), flattenedOperands);
    }

    @Test
    void generatesCastExpressionsForRowTypeChanges() {
        RelDataType sourceType = typeFactory.builder()
                .add("i", intType)
                .add("s", typeFactory.createSqlType(SqlTypeName.VARCHAR, 10))
                .build();
        RelDataType targetType = typeFactory.builder()
                .add("i", bigintType)
                .add("s", typeFactory.createSqlType(SqlTypeName.VARCHAR, 10))
                .build();

        List<RexNode> casts = RexUtil.generateCastExpressions(rexBuilder, targetType, sourceType);

        assertEquals(2, casts.size());
        assertEquals(SqlKind.CAST, casts.get(0).getKind());
        assertEquals(SqlTypeName.BIGINT, casts.get(0).getType().getSqlTypeName());
        assertInstanceOf(RexInputRef.class, casts.get(1));
        assertEquals(SqlTypeName.VARCHAR, casts.get(1).getType().getSqlTypeName());
    }

    @Test
    void stringRepresentationsPreserveOrder() {
        assertEquals(
                ImmutableList.of("1", "2"),
                RexUtil.strings(ImmutableList.of(intLiteral(1), intLiteral(2))));
    }
