 50	/** Utility class that contains helper methods to manipulating {@link KeySelector} for streaming. */
 51	@Internal
 52	public final class KeySelectorUtil {
 53	
 54	    public static <X> KeySelector<X, Tuple> getSelectorForKeys(
 55	            Keys<X> keys, TypeInformation<X> typeInfo, ExecutionConfig executionConfig) {
 56	        if (!(typeInfo instanceof CompositeType)) {
 57	            throw new InvalidTypesException(
 58	                    "This key operation requires a composite type such as Tuples, POJOs, or Case Classes.");
 59	        }
 60	
 61	        CompositeType<X> compositeType = (CompositeType<X>) typeInfo;
 62	
 63	        int[] logicalKeyPositions = keys.computeLogicalKeyPositions();
 64	        int numKeyFields = logicalKeyPositions.length;
 65	
 66	        TypeInformation<?>[] typeInfos = keys.getKeyFieldTypes();
 67	        // use ascending order here, the code paths for that are usually a slight bit faster
 68	        boolean[] orders = new boolean[numKeyFields];
 69	        for (int i = 0; i < numKeyFields; i++) {
 70	            orders[i] = true;
 71	        }
 72	
 73	        TypeComparator<X> comparator =
 74	                compositeType.createComparator(logicalKeyPositions, orders, 0, executionConfig);
 75	        return new ComparableKeySelector<>(
 76	                comparator, numKeyFields, new TupleTypeInfo<>(typeInfos));
 77	    }
 78	
 79	    public static <X> ArrayKeySelector<X> getSelectorForArray(
 80	            int[] positions, TypeInformation<X> typeInfo) {
 81	        if (positions == null || positions.length == 0 || positions.length > Tuple.MAX_ARITY) {
 82	            throw new IllegalArgumentException(
 83	                    "Array keys must have between 1 and " + Tuple.MAX_ARITY + " fields.");
 84	        }
 85	
 86	        TypeInformation<?> componentType;
 87	
 88	        if (typeInfo instanceof BasicArrayTypeInfo) {
 89	            BasicArrayTypeInfo<X, ?> arrayInfo = (BasicArrayTypeInfo<X, ?>) typeInfo;
 90	            componentType = arrayInfo.getComponentInfo();
 91	        } else if (typeInfo instanceof PrimitiveArrayTypeInfo) {
 92	            PrimitiveArrayTypeInfo<X> arrayType = (PrimitiveArrayTypeInfo<X>) typeInfo;
 93	            componentType = arrayType.getComponentType();
 94	        } else {
 95	            throw new IllegalArgumentException(
 96	                    "This method only supports arrays of primitives and boxed primitives.");
 97	        }
 98	
 99	        TypeInformation<?>[] primitiveInfos = new TypeInformation<?>[positions.length];
100	        Arrays.fill(primitiveInfos, componentType);
101	
102	        return new ArrayKeySelector<>(positions, new TupleTypeInfo<>(primitiveInfos));
103	    }
104	
105	    public static <X, K> KeySelector<X, K> getSelectorForOneKey(
106	            Keys<X> keys,
107	            Partitioner<K> partitioner,
108	            TypeInformation<X> typeInfo,
109	            ExecutionConfig executionConfig) {
110	        if (!(typeInfo instanceof CompositeType)) {
111	            throw new InvalidTypesException(
112	                    "This key operation requires a composite type such as Tuples, POJOs, case classes, etc");
113	        }
114	        if (partitioner != null) {
115	            keys.validateCustomPartitioner(partitioner, null);
116	        }
117	
118	        CompositeType<X> compositeType = (CompositeType<X>) typeInfo;
119	        int[] logicalKeyPositions = keys.computeLogicalKeyPositions();
120	        if (logicalKeyPositions.length != 1) {
121	            throw new IllegalArgumentException("There must be exactly 1 key specified");
122	        }
123	
124	        TypeComparator<X> comparator =
125	                compositeType.createComparator(
126	                        logicalKeyPositions, new boolean[] {true}, 0, executionConfig);
127	        return new OneKeySelector<>(comparator);
128	    }
