130	    /**
131	     * Validates that a given type of element (as encoded by the provided {@link TypeInformation})
132	     * can be used as a key. This is done by searching depth-first the key type and checking if each
133	     * of the composite types satisfies the required conditions (see {@link
134	     * #isKeyTypeHashable(TypeInformation)}).
135	     *
136	     * @param keyType The {@link TypeInformation} of the key.
137	     * @return The validated key type.
138	     * @throws InvalidProgramException If the key type, or one of its contained types, cannot be
139	     *     used as a key.
140	     */
141	    @SuppressWarnings("rawtypes")
142	    public static <KEY> TypeInformation<KEY> validateKeyType(TypeInformation<KEY> keyType) {
143	        Stack<TypeInformation<?>> stack = new Stack<>();
144	        stack.push(keyType);
145	
146	        List<TypeInformation<?>> unsupportedTypes = new ArrayList<>();
147	
148	        while (!stack.isEmpty()) {
149	            TypeInformation<?> typeInfo = stack.pop();
150	
151	            if (!isKeyTypeHashable(typeInfo)) {
152	                unsupportedTypes.add(typeInfo);
153	            }
154	
155	            if (typeInfo instanceof TupleTypeInfoBase) {
156	                for (int i = 0; i < typeInfo.getArity(); i++) {
157	                    stack.push(((TupleTypeInfoBase) typeInfo).getTypeAt(i));
158	                }
159	            }
160	        }
161	
162	        if (!unsupportedTypes.isEmpty()) {
163	            throw new InvalidProgramException(
164	                    "Type "
165	                            + keyType
166	                            + " cannot be used as key. Contained "
167	                            + "UNSUPPORTED key types: "
168	                            + StringUtils.join(unsupportedTypes, ", ")
169	                            + ". Look "
170	                            + "at the keyBy() documentation for the conditions a type has to satisfy in order to be "
171	                            + "eligible for a key.");
172	        }
173	
174	        return keyType;
175	    }
176	
177	    /**
178	     * Checks that a given type of element (as encoded by the provided {@link TypeInformation}) can
179	     * be used as a key.
180	     *
181	     * @param type The {@link TypeInformation} of the type to check.
182	     * @return {@code false} if:
183	     *     <ol>
184	     *       <li>it is a POJO type but does not override the {@link Object#hashCode()} method and
185	     *           relies on the {@link Object#hashCode()} implementation.
186	     *       <li>it is an array of any type (see {@link PrimitiveArrayTypeInfo}, {@link
187	     *           BasicArrayTypeInfo}, {@link ObjectArrayTypeInfo}).
188	     *       <li>it is enum type
189	     *     </ol>
190	     *     , {@code true} otherwise.
191	     */
192	    private static boolean isKeyTypeHashable(TypeInformation<?> type) {
193	        try {
194	            return (type instanceof PojoTypeInfo)
195	                    ? !type.getTypeClass()
196	                            .getMethod("hashCode")
197	                            .getDeclaringClass()
198	                            .equals(Object.class)
199	                    : !(isArrayType(type) || isEnumType(type));
200	        } catch (NoSuchMethodException ignored) {
201	            // this should never happen as we are just searching for the hashCode() method.
202	        }
203	        return false;
204	    }
205	
206	    private static boolean isArrayType(TypeInformation<?> type) {
207	        return type instanceof PrimitiveArrayTypeInfo
208	                || type instanceof BasicArrayTypeInfo
209	                || type instanceof ObjectArrayTypeInfo;
210	    }
211	
212	    private static boolean isEnumType(TypeInformation<?> type) {
213	        return type instanceof EnumTypeInfo;
214	    }
