225	    /**
226	     * Key extractor that extracts a single field via a generic comparator.
227	     *
228	     * @param <IN> The type of the elements where the key is extracted from.
229	     * @param <K> The type of the key.
230	     */
231	    public static final class OneKeySelector<IN, K> implements KeySelector<IN, K> {
232	
233	        private static final long serialVersionUID = 1L;
234	
235	        private final TypeComparator<IN> comparator;
236	
237	        /**
238	         * Reusable array to hold the key objects. Since this is initially empty (all positions are
239	         * null), it does not have any serialization problems
240	         */
241	        @SuppressWarnings("NonSerializableFieldInSerializableClass")
242	        private final Object[] keyArray;
243	
244	        OneKeySelector(TypeComparator<IN> comparator) {
245	            this.comparator = comparator;
246	            this.keyArray = new Object[1];
247	        }
248	
249	        @Override
250	        @SuppressWarnings("unchecked")
251	        public K getKey(IN value) throws Exception {
252	            comparator.extractKeys(value, keyArray, 0);
253	            return (K) keyArray[0];
254	        }
255	    }
