259	    /**
260	     * A key selector for selecting key fields via a TypeComparator.
261	     *
262	     * @param <IN> The type from which the key is extracted.
263	     */
264	    public static final class ComparableKeySelector<IN>
265	            implements KeySelector<IN, Tuple>, ResultTypeQueryable<Tuple> {
266	
267	        private static final long serialVersionUID = 1L;
268	
269	        private final TypeComparator<IN> comparator;
270	        private final int keyLength;
271	        private transient TupleTypeInfo<Tuple> tupleTypeInfo;
272	
273	        /**
274	         * Reusable array to hold the key objects. Since this is initially empty (all positions are
275	         * null), it does not have any serialization problems
276	         */
277	        @SuppressWarnings("NonSerializableFieldInSerializableClass")
278	        private final Object[] keyArray;
279	
280	        ComparableKeySelector(
281	                TypeComparator<IN> comparator, int keyLength, TupleTypeInfo<Tuple> tupleTypeInfo) {
282	            this.comparator = comparator;
283	            this.keyLength = keyLength;
284	            this.tupleTypeInfo = tupleTypeInfo;
285	            this.keyArray = new Object[keyLength];
286	        }
