 37	/**
 38	 * These classes encapsulate the logic of accessing a field specified by the user as either an index
 39	 * or a field expression string. TypeInformation can also be requested for the field. The position
 40	 * index might specify a field of a Tuple, an array, or a simple type(only "0th field").
 41	 *
 42	 * <p>Field expressions that specify nested fields (e.g. "f1.a.foo") result in nested field
 43	 * accessors. These penetrate one layer, and then delegate the rest of the work to an
 44	 * "innerAccessor". (see PojoFieldAccessor, RecursiveTupleFieldAccessor,
 45	 * RecursiveProductFieldAccessor)
 46	 */
 47	@Internal
 48	public abstract class FieldAccessor<T, F> implements Serializable {
 49	
 50	    private static final long serialVersionUID = 1L;
 51	
 52	    protected TypeInformation fieldType;
 53	
 54	    /**
 55	     * Gets the TypeInformation for the type of the field. Note: For an array of a primitive type,
 56	     * it returns the corresponding basic type (Integer for int[]).
 57	     */
 58	    @SuppressWarnings("unchecked")
 59	    public TypeInformation<F> getFieldType() {
 60	        return fieldType;
 61	    }
 62	
 63	    /**
 64	     * Gets the value of the field (specified in the constructor) of the given record.
 65	     *
 66	     * @param record The record on which the field will be accessed
 67	     * @return The value of the field.
 68	     */
 69	    public abstract F get(T record);
 70	
 71	    /**
 72	     * Sets the field (specified in the constructor) of the given record to the given value.
 73	     *
 74	     * <p>Warning: This might modify the original object, or might return a new object instance.
 75	     * (This is necessary, because the record might be immutable.)
 76	     *
 77	     * @param record The record to modify
 78	     * @param fieldValue The new value of the field
 79	     * @return A record that has the given field value. (this might be a new instance or the
 80	     *     original)
 81	     */
 82	    public abstract T set(T record, F fieldValue);
 83	
 84	    // --------------------------------------------------------------------------------------------------
 85	
 86	    /**
 87	     * This is when the entire record is considered as a single field. (eg. field 0 of a basic type,
 88	     * or a field of a POJO that is itself some composite type but is not further decomposed)
 89	     */
 90	    static final class SimpleFieldAccessor<T> extends FieldAccessor<T, T> {
 91	
 92	        private static final long serialVersionUID = 1L;
 93	
 94	        public SimpleFieldAccessor(TypeInformation<T> typeInfo) {
 95	            checkNotNull(typeInfo, "typeInfo must not be null.");
 96	
 97	            this.fieldType = typeInfo;
 98	        }
 99	
100	        @Override
101	        public T get(T record) {
102	            return record;
103	        }
104	
105	        @Override
106	        public T set(T record, T fieldValue) {
107	            return fieldValue;
108	        }
109	    }
110	
111	    static final class ArrayFieldAccessor<T, F> extends FieldAccessor<T, F> {
112	
113	        private static final long serialVersionUID = 1L;
114	
115	        private final int pos;
116	
117	        public ArrayFieldAccessor(int pos, TypeInformation typeInfo) {
118	            if (pos < 0) {
119	                throw new CompositeType.InvalidFieldReferenceException(
120	                        "The "
121	                                + ((Integer) pos).toString()
122	                                + ". field selected on"
123	                                + " an array, which is an invalid index.");
124	            }
125	            checkNotNull(typeInfo, "typeInfo must not be null.");
126	
127	            this.pos = pos;
128	            this.fieldType = BasicTypeInfo.getInfoFor(typeInfo.getTypeClass().getComponentType());
129	        }
130	
131	        @SuppressWarnings("unchecked")
132	        @Override
133	        public F get(T record) {
134	            return (F) Array.get(record, pos);
135	        }
136	
137	        @Override
138	        public T set(T record, F fieldValue) {
139	            Array.set(record, pos, fieldValue);
140	            return record;
141	        }
142	    }
143	
144	    /**
145	     * There are two versions of TupleFieldAccessor, differing in whether there is an other
146	     * FieldAccessor nested inside. The no inner accessor version is probably a little faster.
147	     */
148	    static final class SimpleTupleFieldAccessor<T extends Tuple, F> extends FieldAccessor<T, F> {
149	
150	        private static final long serialVersionUID = 1L;
151	
152	        private final int pos;
153	
154	        SimpleTupleFieldAccessor(int pos, TypeInformation<T> typeInfo) {
155	            checkNotNull(typeInfo, "typeInfo must not be null.");
156	            int arity = ((TupleTypeInfo) typeInfo).getArity();
157	            if (pos < 0 || pos >= arity) {
158	                throw new CompositeType.InvalidFieldReferenceException(
159	                        "Tried to select "
160	                                + ((Integer) pos).toString()
161	                                + ". field on \""
162	                                + typeInfo.toString()
163	                                + "\", which is an invalid index.");
164	            }
165	
166	            this.pos = pos;
167	            this.fieldType = ((TupleTypeInfo) typeInfo).getTypeAt(pos);
168	        }
169	
170	        @SuppressWarnings("unchecked")
171	        @Override
172	        public F get(T record) {
173	            return (F) record.getField(pos);
174	        }
175	
176	        @Override
177	        public T set(T record, F fieldValue) {
178	            record.setField(fieldValue, pos);
179	            return record;
180	        }
181	    }
182	
183	    /**
184	     * @param <T> The Tuple type
185	     * @param <R> The field type at the first level
186	     * @param <F> The field type at the innermost level
187	     */
188	    static final class RecursiveTupleFieldAccessor<T extends Tuple, R, F>
189	            extends FieldAccessor<T, F> {
190	
191	        private static final long serialVersionUID = 1L;
192	
193	        private final int pos;
194	        private final FieldAccessor<R, F> innerAccessor;
195	
196	        RecursiveTupleFieldAccessor(
197	                int pos, FieldAccessor<R, F> innerAccessor, TypeInformation<T> typeInfo) {
198	            checkNotNull(typeInfo, "typeInfo must not be null.");
199	            checkNotNull(innerAccessor, "innerAccessor must not be null.");
200	
201	            int arity = ((TupleTypeInfo) typeInfo).getArity();
202	            if (pos < 0 || pos >= arity) {
203	                throw new CompositeType.InvalidFieldReferenceException(
204	                        "Tried to select "
205	                                + ((Integer) pos).toString()
206	                                + ". field on \""
207	                                + typeInfo.toString()
208	                                + "\", which is an invalid index.");
209	            }
210	
211	            this.pos = pos;
212	            this.innerAccessor = innerAccessor;
213	            this.fieldType = innerAccessor.fieldType;
214	        }
215	
216	        @Override
217	        public F get(T record) {
218	            final R inner = record.getField(pos);
219	            return innerAccessor.get(inner);
220	        }
221	
222	        @Override
223	        public T set(T record, F fieldValue) {
224	            final R inner = record.getField(pos);
225	            record.setField(innerAccessor.set(inner, fieldValue), pos);
226	            return record;
227	        }
228	    }
229	
230	    /**
231	     * @param <T> The POJO type
232	     * @param <R> The field type at the first level
233	     * @param <F> The field type at the innermost level
234	     */
235	    static final class PojoFieldAccessor<T, R, F> extends FieldAccessor<T, F> {
236	
237	        private static final long serialVersionUID = 1L;
238	
239	        private transient Field field;
240	        private final FieldAccessor<R, F> innerAccessor;
241	
242	        PojoFieldAccessor(Field field, FieldAccessor<R, F> innerAccessor) {
243	            checkNotNull(field, "field must not be null.");
244	            checkNotNull(innerAccessor, "innerAccessor must not be null.");
245	
246	            this.field = field;
247	            this.innerAccessor = innerAccessor;
248	            this.fieldType = innerAccessor.fieldType;
249	        }
250	
251	        @Override
252	        public F get(T pojo) {
253	            try {
254	                @SuppressWarnings("unchecked")
255	                final R inner = (R) field.get(pojo);
256	                return innerAccessor.get(inner);
257	            } catch (IllegalAccessException iaex) {
258	                // The Field class is transient and when deserializing its value we also make it
259	                // accessible
260	                throw new RuntimeException(
261	                        "This should not happen since we call setAccesssible(true) in readObject."
262	                                + " fields: "
263	                                + field
264	                                + " obj: "
265	                                + pojo);
266	            }
267	        }
268	
269	        @Override
270	        public T set(T pojo, F valueToSet) {
271	            try {
272	                @SuppressWarnings("unchecked")
273	                final R inner = (R) field.get(pojo);
274	                field.set(pojo, innerAccessor.set(inner, valueToSet));
275	                return pojo;
276	            } catch (IllegalAccessException iaex) {
277	                // The Field class is transient and when deserializing its value we also make it
278	                // accessible
279	                throw new RuntimeException(
280	                        "This should not happen since we call setAccesssible(true) in readObject."
281	                                + " fields: "
282	                                + field
283	                                + " obj: "
284	                                + pojo);
285	            }
286	        }
287	
288	        private void writeObject(ObjectOutputStream out)
289	                throws IOException, ClassNotFoundException {
290	            out.defaultWriteObject();
291	            FieldSerializer.serializeField(field, out);
292	        }
293	
294	        private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
295	            in.defaultReadObject();
296	            field = FieldSerializer.deserializeField(in);
297	        }
298	    }
299	}

