 42	/** Static factories for the {@link FieldAccessor} utilities. */
 43	@Internal
 44	public class FieldAccessorFactory implements Serializable {
 45	
 46	    private static final Logger LOG = LoggerFactory.getLogger(FieldAccessorFactory.class);
 47	
 48	    @Nullable
 49	    private static final ScalaProductFieldAccessorFactory scalaProductFieldAccessorFactory =
 50	            ScalaProductFieldAccessorFactory.load(LOG);
 51	
 52	    /**
 53	     * Creates a {@link FieldAccessor} for the given field position, which can be used to get and
 54	     * set the specified field on instances of this type.
 55	     *
 56	     * @param pos The field position (zero-based)
 57	     * @param config Configuration object
 58	     * @param <F> The type of the field to access
 59	     * @return The created FieldAccessor
 60	     */
 61	    @Internal
 62	    public static <T, F> FieldAccessor<T, F> getAccessor(
 63	            TypeInformation<T> typeInfo, int pos, ExecutionConfig config) {
 64	
 65	        // In case of arrays
 66	        if (typeInfo instanceof BasicArrayTypeInfo || typeInfo instanceof PrimitiveArrayTypeInfo) {
 67	            return new FieldAccessor.ArrayFieldAccessor<>(pos, typeInfo);
 68	
 69	            // In case of basic types
 70	        } else if (typeInfo instanceof BasicTypeInfo) {
 71	            if (pos != 0) {
 72	                throw new CompositeType.InvalidFieldReferenceException(
 73	                        "The "
 74	                                + ((Integer) pos).toString()
 75	                                + ". field selected on a "
 76	                                + "basic type ("
 77	                                + typeInfo.toString()
 78	                                + "). A field expression on a basic type can only select "
 79	                                + "the 0th field (which means selecting the entire basic type).");
 80	            }
 81	            @SuppressWarnings("unchecked")
 82	            FieldAccessor<T, F> result =
 83	                    (FieldAccessor<T, F>) new FieldAccessor.SimpleFieldAccessor<>(typeInfo);
 84	            return result;
 85	
 86	            // In case of case classes
 87	        } else if (typeInfo.isTupleType() && ((TupleTypeInfoBase) typeInfo).isCaseClass()) {
 88	            TupleTypeInfoBase tupleTypeInfo = (TupleTypeInfoBase) typeInfo;
 89	            @SuppressWarnings("unchecked")
 90	            TypeInformation<F> fieldTypeInfo = (TypeInformation<F>) tupleTypeInfo.getTypeAt(pos);
 91	
 92	            if (scalaProductFieldAccessorFactory != null) {
 93	                return scalaProductFieldAccessorFactory.createRecursiveProductFieldAccessor(
 94	                        pos,
 95	                        typeInfo,
 96	                        new FieldAccessor.SimpleFieldAccessor<>(fieldTypeInfo),
 97	                        config);
 98	            } else {
 99	                throw new IllegalStateException(
100	                        "Scala products are used but Scala API is not on the classpath.");
101	            }
102	
103	            // In case of tuples
104	        } else if (typeInfo.isTupleType()) {
105	            @SuppressWarnings("unchecked")
106	            FieldAccessor<T, F> result = new FieldAccessor.SimpleTupleFieldAccessor(pos, typeInfo);
107	            return result;
108	
109	            // Default case, PojoType is directed to this statement
110	        } else {
111	            throw new CompositeType.InvalidFieldReferenceException(
112	                    "Cannot reference field by position on "
113	                            + typeInfo.toString()
114	                            + "Referencing a field by position is supported on tuples, case classes, and arrays. "
115	                            + "Additionally, you can select the 0th field of a primitive/basic type (e.g. int).");
116	        }
117	    }
118	
119	    /**
120	     * Creates a {@link FieldAccessor} for the field that is given by a field expression, which can
121	     * be used to get and set the specified field on instances of this type.
122	     *
123	     * @param field The field expression
124	     * @param config Configuration object
125	     * @param <F> The type of the field to access
126	     * @return The created FieldAccessor
127	     */
128	    @Internal
129	    public static <T, F> FieldAccessor<T, F> getAccessor(
130	            TypeInformation<T> typeInfo, String field, ExecutionConfig config) {
131	
132	        // In case of arrays
133	        if (typeInfo instanceof BasicArrayTypeInfo || typeInfo instanceof PrimitiveArrayTypeInfo) {
134	            try {
135	                return new FieldAccessor.ArrayFieldAccessor<>(Integer.parseInt(field), typeInfo);
136	            } catch (NumberFormatException ex) {
137	                throw new CompositeType.InvalidFieldReferenceException(
138	                        "A field expression on an array must be an integer index (that might be given as a string).");
139	            }
140	
141	            // In case of basic types
142	        } else if (typeInfo instanceof BasicTypeInfo) {
143	            try {
144	                int pos =
145	                        field.equals(Keys.ExpressionKeys.SELECT_ALL_CHAR)
146	                                ? 0
147	                                : Integer.parseInt(field);
148	                return FieldAccessorFactory.getAccessor(typeInfo, pos, config);
149	            } catch (NumberFormatException ex) {
150	                throw new CompositeType.InvalidFieldReferenceException(
151	                        "You tried to select the field \""
152	                                + field
153	                                + "\" on a "
154	                                + typeInfo.toString()
155	                                + ". A field expression on a basic type can only be \"*\" or \"0\""
156	                                + " (both of which mean selecting the entire basic type).");
157	            }
158	
159	            // In case of Pojos
160	        } else if (typeInfo instanceof PojoTypeInfo) {
161	            FieldExpression decomp = decomposeFieldExpression(field);
162	            PojoTypeInfo<?> pojoTypeInfo = (PojoTypeInfo) typeInfo;
163	
164	            int fieldIndex = pojoTypeInfo.getFieldIndex(decomp.head);
165	
166	            if (fieldIndex == -1) {
167	                throw new CompositeType.InvalidFieldReferenceException(
168	                        "Unable to find field \"" + decomp.head + "\" in type " + typeInfo + ".");
169	            } else {
170	                PojoField pojoField = pojoTypeInfo.getPojoFieldAt(fieldIndex);
171	                TypeInformation<?> fieldType = pojoTypeInfo.getTypeAt(fieldIndex);
172	                if (decomp.tail == null) {
173	                    @SuppressWarnings("unchecked")
174	                    FieldAccessor<F, F> innerAccessor =
175	                            new FieldAccessor.SimpleFieldAccessor<>((TypeInformation<F>) fieldType);
176	                    return new FieldAccessor.PojoFieldAccessor<>(
177	                            pojoField.getField(), innerAccessor);
178	                } else {
179	                    @SuppressWarnings("unchecked")
180	                    FieldAccessor<Object, F> innerAccessor =
181	                            FieldAccessorFactory.getAccessor(
182	                                    (TypeInformation<Object>) fieldType, decomp.tail, config);
183	                    return new FieldAccessor.PojoFieldAccessor<>(
184	                            pojoField.getField(), innerAccessor);
185	                }
186	            }
187	            // In case of case classes
188	        } else if (typeInfo.isTupleType() && ((TupleTypeInfoBase) typeInfo).isCaseClass()) {
189	            TupleTypeInfoBase tupleTypeInfo = (TupleTypeInfoBase) typeInfo;
190	            FieldExpression decomp = decomposeFieldExpression(field);
191	            int fieldPos = tupleTypeInfo.getFieldIndex(decomp.head);
192	            if (fieldPos < 0) {
193	                throw new CompositeType.InvalidFieldReferenceException(
194	                        "Invalid field selected: " + field);
195	            }
196	
197	            if (decomp.tail == null) {
198	                if (scalaProductFieldAccessorFactory != null) {
199	                    return scalaProductFieldAccessorFactory.createSimpleProductFieldAccessor(
200	                            fieldPos, typeInfo, config);
201	                } else {
202	                    throw new IllegalStateException(
203	                            "Scala products are used but Scala API is not on the classpath.");
204	                }
205	            } else {
206	                @SuppressWarnings("unchecked")
207	                FieldAccessor<Object, F> innerAccessor =
208	                        getAccessor(tupleTypeInfo.getTypeAt(fieldPos), decomp.tail, config);
209	
210	                if (scalaProductFieldAccessorFactory != null) {
211	                    return scalaProductFieldAccessorFactory.createRecursiveProductFieldAccessor(
212	                            fieldPos, typeInfo, innerAccessor, config);
213	                } else {
214	                    throw new IllegalStateException(
215	                            "Scala products are used but Scala API is not on the classpath.");
216	                }
217	            }
218	
219	            // In case of tuples
220	        } else if (typeInfo.isTupleType() && typeInfo instanceof TupleTypeInfo) {
221	            TupleTypeInfo tupleTypeInfo = (TupleTypeInfo) typeInfo;
222	            FieldExpression decomp = decomposeFieldExpression(field);
223	            int fieldPos = tupleTypeInfo.getFieldIndex(decomp.head);
224	            if (fieldPos == -1) {
225	                try {
226	                    fieldPos = Integer.parseInt(decomp.head);
227	                } catch (NumberFormatException ex) {
228	                    throw new CompositeType.InvalidFieldReferenceException(
229	                            "Tried to select field \""
230	                                    + decomp.head
231	                                    + "\" on "
232	                                    + typeInfo.toString()
233	                                    + " . Only integer values are allowed here.");
234	                }
235	            }
236	            if (decomp.tail == null) {
237	                @SuppressWarnings("unchecked")
238	                FieldAccessor<T, F> result =
239	                        new FieldAccessor.SimpleTupleFieldAccessor(fieldPos, tupleTypeInfo);
240	                return result;
241	            } else {
242	                @SuppressWarnings("unchecked")
243	                FieldAccessor<?, F> innerAccessor =
244	                        getAccessor(tupleTypeInfo.getTypeAt(fieldPos), decomp.tail, config);
245	                @SuppressWarnings("unchecked")
246	                FieldAccessor<T, F> result =
247	                        new FieldAccessor.RecursiveTupleFieldAccessor(
248	                                fieldPos, innerAccessor, tupleTypeInfo);
249	                return result;
250	            }
251	
252	            // Default statement
253	        } else {
254	            throw new CompositeType.InvalidFieldReferenceException(
255	                    "Cannot reference field by field expression on "
256	                            + typeInfo.toString()
257	                            + "Field expressions are only supported on POJO types, tuples, and case classes. "
258	                            + "(See the Flink documentation on what is considered a POJO.)");
259	        }
260	    }

public static <X> ArrayKeySelector<X> getSelectorForArray(
        int[] positions, TypeInformation<X> typeInfo) {
    if (positions == null || positions.length == 0 || positions.length > Tuple.MAX_ARITY) {
        throw new IllegalArgumentException(
                "Array keys must have between 1 and " + Tuple.MAX_ARITY + " fields.");
    }

    TypeInformation<?> componentType;

    if (typeInfo instanceof BasicArrayTypeInfo) {
        BasicArrayTypeInfo<X, ?> arrayInfo = (BasicArrayTypeInfo<X, ?>) typeInfo;
        componentType = arrayInfo.getComponentInfo();
    } else if (typeInfo instanceof PrimitiveArrayTypeInfo) {
        PrimitiveArrayTypeInfo<X> arrayType = (PrimitiveArrayTypeInfo<X>) typeInfo;
        componentType = arrayType.getComponentType();
    } else {
        throw new IllegalArgumentException(
                "This method only supports arrays of primitives and boxed primitives.");
    }

    TypeInformation<?>[] primitiveInfos = new TypeInformation<?>[positions.length];
    Arrays.fill(primitiveInfos, componentType);

    return new ArrayKeySelector<>(positions, new TupleTypeInfo<>(primitiveInfos));
}

public static <X, K> KeySelector<X, K> getSelectorForOneKey(
        Keys<X> keys,
        Partitioner<K> partitioner,
        TypeInformation<X> typeInfo,
        ExecutionConfig executionConfig) {
    if (!(typeInfo instanceof CompositeType)) {
        throw new InvalidTypesException(
                "This key operation requires a composite type such as Tuples, POJOs, case classes, etc");
    }
    if (partitioner != null) {
        keys.validateCustomPartitioner(partitioner, null);
    }

    CompositeType<X> compositeType = (CompositeType<X>) typeInfo;
    int[] logicalKeyPositions = keys.computeLogicalKeyPositions();
    if (logicalKeyPositions.length != 1) {
        throw new IllegalArgumentException("There must be exactly 1 key specified");
    }

    TypeComparator<X> comparator =
            compositeType.createComparator(
                    logicalKeyPositions, new boolean[] {true}, 0, executionConfig);
    return new OneKeySelector<>(comparator);
}

/**
 * Validates that a given type of element (as encoded by the provided {@link TypeInformation})
 * can be used as a key. This is done by searching depth-first the key type and checking if each
 * of the composite types satisfies the required conditions (see {@link
 * #isKeyTypeHashable(TypeInformation)}).
 *
 * @param keyType The {@link TypeInformation} of the key.
 * @return The validated key type.
 * @throws InvalidProgramException If the key type, or one of its contained types, cannot be
 *     used as a key.
 */
@SuppressWarnings("rawtypes")
public static <KEY> TypeInformation<KEY> validateKeyType(TypeInformation<KEY> keyType) {
    Stack<TypeInformation<?>> stack = new Stack<>();
    stack.push(keyType);

    List<TypeInformation<?>> unsupportedTypes = new ArrayList<>();

    while (!stack.isEmpty()) {
        TypeInformation<?> typeInfo = stack.pop();

        if (!isKeyTypeHashable(typeInfo)) {
            unsupportedTypes.add(typeInfo);
        }

        if (typeInfo instanceof TupleTypeInfoBase) {
            for (int i = 0; i < typeInfo.getArity(); i++) {
                stack.push(((TupleTypeInfoBase) typeInfo).getTypeAt(i));
            }
        }
    }

    if (!unsupportedTypes.isEmpty()) {
        throw new InvalidProgramException(
                "Type "
                        + keyType
                        + " cannot be used as key. Contained "
                        + "UNSUPPORTED key types: "
                        + StringUtils.join(unsupportedTypes, ", ")
                        + ". Look "
                        + "at the keyBy() documentation for the conditions a type has to satisfy in order to be "
                        + "eligible for a key.");
    }

    return keyType;
}

/**
 * Checks that a given type of element (as encoded by the provided {@link TypeInformation}) can
 * be used as a key.
 *
 * @param type The {@link TypeInformation} of the type to check.
 * @return {@code false} if:
 *     <ol>
 *       <li>it is a POJO type but does not override the {@link Object#hashCode()} method and
 *           relies on the {@link Object#hashCode()} implementation.
 *       <li>it is an array of any type (see {@link PrimitiveArrayTypeInfo}, {@link
 *           BasicArrayTypeInfo}, {@link ObjectArrayTypeInfo}).
 *       <li>it is enum type
 *     </ol>
 *     , {@code true} otherwise.
 */
private static boolean isKeyTypeHashable(TypeInformation<?> type) {
    try {
        return (type instanceof PojoTypeInfo)
                ? !type.getTypeClass()
                        .getMethod("hashCode")
                        .getDeclaringClass()
                        .equals(Object.class)
                : !(isArrayType(type) || isEnumType(type));
    } catch (NoSuchMethodException ignored) {
        // this should never happen as we are just searching for the hashCode() method.
    }
    return false;
}

private static boolean isArrayType(TypeInformation<?> type) {
    return type instanceof PrimitiveArrayTypeInfo
            || type instanceof BasicArrayTypeInfo
            || type instanceof ObjectArrayTypeInfo;
}

private static boolean isEnumType(TypeInformation<?> type) {
    return type instanceof EnumTypeInfo;
}

