        this.originalKeyTypes = new TypeInformation<?>[keyPositions.length];
        ArrayList<FlatFieldDescriptor> tmpList = new ArrayList<>();
        for (int i = 0; i < keyPositions.length; i++) {
            int keyPos = keyPositions[i];
