import org.apache.flink.streaming.runtime.streamrecord.LatencyMarker;

import org.junit.jupiter.api.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Tests for {@link LatencyStats}. */
class LatencyStatsTest {

    @Test
    void testSingleGranularityUsesOneHistogramForDifferentSourcesAndRecordsAllMeasurements() {
        RecordingMetricGroup metricGroup = new RecordingMetricGroup();
        OperatorID targetOperator = new OperatorID(1L, 2L);
        LatencyStats stats =
                new LatencyStats(
                        metricGroup, 10, 3, targetOperator, LatencyStats.Granularity.SINGLE);

        stats.reportLatency(
                new LatencyMarker(System.currentTimeMillis() - 1000L, new OperatorID(3L, 4L), 0));
        stats.reportLatency(
                new LatencyMarker(System.currentTimeMillis() - 1000L, new OperatorID(5L, 6L), 1));

        String expectedPath =
                "operator_id="
                        + targetOperator
                        + ".operator_subtask_index=3.latency";
        assertEquals(Collections.singleton(expectedPath), metricGroup.histograms.keySet());
        Histogram histogram = metricGroup.histograms.get(expectedPath);
        assertNotNull(histogram);
        assertEquals(2L, histogram.getCount());
        assertTrue(histogram.getStatistics().getMin() >= 1000L);
    }

    @Test
    void testOperatorGranularitySeparatesHistogramsBySourceOperator() {
        RecordingMetricGroup metricGroup = new RecordingMetricGroup();
        OperatorID targetOperator = new OperatorID(11L, 12L);
        OperatorID firstSource = new OperatorID(21L, 22L);
        OperatorID secondSource = new OperatorID(31L, 32L);
        LatencyStats stats =
                new LatencyStats(
                        metricGroup, 10, 4, targetOperator, LatencyStats.Granularity.OPERATOR);

        long markedTime = System.currentTimeMillis() - 1000L;
        stats.reportLatency(new LatencyMarker(markedTime, firstSource, 0));
        stats.reportLatency(new LatencyMarker(markedTime, firstSource, 1));
        stats.reportLatency(new LatencyMarker(markedTime, secondSource, 0));

        String firstPath =
                "source_id="
                        + firstSource
                        + ".operator_id="
                        + targetOperator
                        + ".operator_subtask_index=4.latency";
        String secondPath =
                "source_id="
                        + secondSource
                        + ".operator_id="
                        + targetOperator
                        + ".operator_subtask_index=4.latency";

        assertEquals(2, metricGroup.histograms.size());
        assertEquals(2L, metricGroup.histograms.get(firstPath).getCount());
        assertEquals(1L, metricGroup.histograms.get(secondPath).getCount());
        assertTrue(
                !firstPath.equals(secondPath)
                        && metricGroup.histograms.get(firstPath)
                                != metricGroup.histograms.get(secondPath));
    }

    @Test
    void testSubtaskGranularitySeparatesHistogramsBySourceSubtask() {
        RecordingMetricGroup metricGroup = new RecordingMetricGroup();
        OperatorID targetOperator = new OperatorID(41L, 42L);
        OperatorID source = new OperatorID(51L, 52L);
        LatencyStats stats =
                new LatencyStats(
                        metricGroup, 5, 2, targetOperator, LatencyStats.Granularity.SUBTASK);

        long markedTime = System.currentTimeMillis() - 1000L;
        stats.reportLatency(new LatencyMarker(markedTime, source, 7));
        stats.reportLatency(new LatencyMarker(markedTime, source, 7));
        stats.reportLatency(new LatencyMarker(markedTime, source, 8));

        String subtaskSevenPath =
                "source_id="
                        + source
                        + ".source_subtask_index=7.operator_id="
                        + targetOperator
                        + ".operator_subtask_index=2.latency";
        String subtaskEightPath =
                "source_id="
                        + source
                        + ".source_subtask_index=8.operator_id="
                        + targetOperator
                        + ".operator_subtask_index=2.latency";

        assertEquals(2, metricGroup.histograms.size());
        assertEquals(2L, metricGroup.histograms.get(subtaskSevenPath).getCount());
        assertEquals(1L, metricGroup.histograms.get(subtaskEightPath).getCount());
    }

    @Test
    void testHistogramKeepsConfiguredHistoryWindowWhileCountingAllUpdates() {
        RecordingMetricGroup metricGroup = new RecordingMetricGroup();
        OperatorID targetOperator = new OperatorID(61L, 62L);
