                new LatencyStats(
                        metricGroup, 2, 0, targetOperator, LatencyStats.Granularity.SINGLE);
        LatencyMarker marker =
                new LatencyMarker(
                        System.currentTimeMillis() - 1000L, new OperatorID(71L, 72L), 0);

        stats.reportLatency(marker);
        Histogram histogram =
                metricGroup.histograms.get(
                        "operator_id="
                                + targetOperator
                                + ".operator_subtask_index=0.latency");
        stats.reportLatency(marker);
        stats.reportLatency(marker);

        assertSame(
                histogram,
                metricGroup.histograms.get(
                        "operator_id="
                                + targetOperator
                                + ".operator_subtask_index=0.latency"));
        assertEquals(3L, histogram.getCount());
        assertEquals(2, histogram.getStatistics().size());
        assertEquals(1, metricGroup.histograms.size());
    }

    private static final class RecordingMetricGroup implements MetricGroup {
        private final String path;
        private final Map<String, Histogram> histograms;

        private RecordingMetricGroup() {
            this("", new LinkedHashMap<>());
        }

        private RecordingMetricGroup(String path, Map<String, Histogram> histograms) {
            this.path = path;
            this.histograms = histograms;
        }

        private String append(String component) {
            return path.isEmpty() ? component : path + "." + component;
        }

        @Override
        public Counter counter(String name) {
            return new SimpleCounter();
        }

        @Override
        public <C extends Counter> C counter(String name, C counter) {
            return counter;
        }

        @Override
        public <T, G extends Gauge<T>> G gauge(String name, G gauge) {
            return gauge;
        }

        @Override
        public <H extends Histogram> H histogram(String name, H histogram) {
            histograms.put(append(name), histogram);
            return histogram;
        }

        @Override
        public <M extends Meter> M meter(String name, M meter) {
            return meter;
        }

        @Override
        public MetricGroup addGroup(String name) {
            return new RecordingMetricGroup(append(name), histograms);
        }

        @Override
        public MetricGroup addGroup(String key, String value) {
            return addGroup(key + "=" + value);
        }

        @Override
        public String[] getScopeComponents() {
            return path.isEmpty() ? new String[0] : path.split("\\.");
        }

        @Override
        public Map<String, String> getAllVariables() {
            return Collections.emptyMap();
        }

        @Override
        public String getMetricIdentifier(String metricName) {
            return append(metricName);
        }

        @Override
        public String getMetricIdentifier(String metricName, CharacterFilter filter) {
            return append(metricName);
        }
    }
}
