    @Test
    void testRestoreFunctionStateRestoresListCheckpointedState() throws Exception {
        StateInitializationContext context = mock(StateInitializationContext.class);
        OperatorStateStore stateStore = mock(OperatorStateStore.class);
        @SuppressWarnings("unchecked")
        ListState<Serializable> listState = mock(ListState.class);
        when(context.isRestored()).thenReturn(true);
        when(context.getOperatorStateStore()).thenReturn(stateStore);
        when(stateStore.getListState(any(ListStateDescriptor.class))).thenReturn(listState);
        when(listState.get()).thenReturn(Arrays.asList("alpha", "beta"));

        ListCheckpointedTestFunction function = new ListCheckpointedTestFunction();

        StreamingFunctionUtils.restoreFunctionState(context, function);

        assertEquals(Arrays.asList("alpha", "beta"), function.restoredState);
    }

    @Test
    void testRestoreFunctionStateDoesNotRestoreListCheckpointedFunctionWithoutRestoredState()
