    }

    private static final class ConfigurableFunction
            implements Function, OutputTypeConfigurable<String> {
        private TypeInformation<String> outputType;
        private ExecutionConfig executionConfig;
        private int setOutputTypeCalls;

        @Override
        public void setOutputType(
                TypeInformation<String> outTypeInfo, ExecutionConfig executionConfig) {
            this.outputType = outTypeInfo;
            this.executionConfig = executionConfig;
            this.setOutputTypeCalls++;
        }
    }

    private static final class CheckpointedTestFunction
            implements Function, CheckpointedFunction {
        private int snapshotCalls;
        private int initializeCalls;
        private StateSnapshotContext snapshotContext;
        private StateInitializationContext initializationContext;

        @Override
        public void snapshotState(
                org.apache.flink.runtime.state.FunctionSnapshotContext context) {
            snapshotCalls++;
            snapshotContext = (StateSnapshotContext) context;
        }

        @Override
        public void initializeState(
                org.apache.flink.runtime.state.FunctionInitializationContext context)
                throws Exception {
            initializeCalls++;
            initializationContext = (StateInitializationContext) context;
        }
    }

    @SuppressWarnings("deprecation")
    private static final class ListCheckpointedTestFunction
            implements Function, ListCheckpointed<Serializable> {
        private List<Serializable> stateToSnapshot = Collections.emptyList();
        private List<Serializable> restoredState;
        private long snapshotCheckpointId = -1L;
        private long snapshotTimestamp = -1L;

        @Override
        public List<Serializable> snapshotState(long checkpointId, long timestamp) {
            snapshotCheckpointId = checkpointId;
            snapshotTimestamp = timestamp;
            return stateToSnapshot;
        }

        @Override
        public void restoreState(List<Serializable> state) {
            restoredState = state;
        }
    }
}
