        assertThrows(
                IllegalArgumentException.class,
                () ->
                        KeySelectorUtil.getSelectorForOneKey(
                                keys, null, typeInfo, new ExecutionConfig()));
    }

    @Test
    void testSelectorForOneKeyRejectsIncompatibleCustomPartitioner() {
        TypeInformation<Tuple2<String, Integer>> typeInfo =
                Types.TUPLE(Types.STRING, Types.INT);
        Keys<Tuple2<String, Integer>> keys =
                new Keys.ExpressionKeys<>(new int[] {1}, typeInfo);

        assertThrows(
                InvalidProgramException.class,
                () ->
                        KeySelectorUtil.getSelectorForOneKey(
                                keys,
                                new StringPartitioner(),
                                typeInfo,
                                new ExecutionConfig()));
    }

    @Test
    void testSelectorForOneKeyRejectsNonCompositeType() {
        TypeInformation<String> typeInfo = Types.STRING;
        Keys<String> keys = new Keys.ExpressionKeys<>(typeInfo);

        assertThrows(
                InvalidTypesException.class,
                () ->
                        KeySelectorUtil.getSelectorForOneKey(
                                keys, null, typeInfo, new ExecutionConfig()));
    }

    @Test
    void testSelectorForPrimitiveArrayExtractsRequestedPositions() throws Exception {
