        TypeInformation<int[]> typeInfo =
                (TypeInformation<int[]>) Types.PRIMITIVE_ARRAY(Types.INT);
        KeySelector<int[], Tuple> selector =
                KeySelectorUtil.getSelectorForArray(new int[] {2, 0}, typeInfo);

        Tuple key = selector.getKey(new int[] {10, 20, 30});
        assertEquals(30, key.getField(0));
        assertEquals(10, key.getField(1));
        assertEquals(Types.INT, ((KeySelectorUtil.ArrayKeySelector<int[]>) selector).getProducedType().getTypeAt(0));
        assertEquals(Types.INT, ((KeySelectorUtil.ArrayKeySelector<int[]>) selector).getProducedType().getTypeAt(1));
    }

    @Test
    void testSelectorForBoxedArrayUsesComponentTypeInformation() throws Exception {
        TypeInformation<Integer[]> typeInfo = BasicArrayTypeInfo.INT_ARRAY_TYPE_INFO;
        KeySelector<Integer[], Tuple> selector =
                KeySelectorUtil.getSelectorForArray(new int[] {1, 0}, typeInfo);

        Tuple key = selector.getKey(new Integer[] {4, 9});
        assertEquals(9, key.getField(0));
        assertEquals(4, key.getField(1));
        assertEquals(Types.INT, ((KeySelectorUtil.ArrayKeySelector<Integer[]>) selector).getProducedType().getTypeAt(0));
    }

    @Test
    void testSelectorForArrayValidatesNumberOfPositions() {
        @SuppressWarnings("unchecked")
        TypeInformation<int[]> primitiveArrayType =
                (TypeInformation<int[]>) Types.PRIMITIVE_ARRAY(Types.INT);

        assertThrows(
                IllegalArgumentException.class,
                () -> KeySelectorUtil.getSelectorForArray(null, primitiveArrayType));
        assertThrows(
                IllegalArgumentException.class,
                () -> KeySelectorUtil.getSelectorForArray(new int[0], primitiveArrayType));
        assertThrows(
                IllegalArgumentException.class,
                () ->
                        KeySelectorUtil.getSelectorForArray(
                                new int[Tuple.MAX_ARITY + 1], primitiveArrayType));
    }

    @Test
    void testSelectorForArrayAcceptsMaximumNumberOfPositions() throws Exception {
        int[] positions = new int[Tuple.MAX_ARITY];
        int[] values = new int[Tuple.MAX_ARITY];
        for (int i = 0; i < Tuple.MAX_ARITY; i++) {
            positions[i] = i;
            values[i] = i * 2;
        }
        @SuppressWarnings("unchecked")
        TypeInformation<int[]> typeInfo =
                (TypeInformation<int[]>) Types.PRIMITIVE_ARRAY(Types.INT);

        KeySelector<int[], Tuple> selector =
                KeySelectorUtil.getSelectorForArray(positions, typeInfo);

        Tuple key = selector.getKey(values);
        assertEquals(Tuple.MAX_ARITY, key.getArity());
        assertEquals(values[0], key.getField(0));
        assertEquals(values[Tuple.MAX_ARITY - 1], key.getField(Tuple.MAX_ARITY - 1));
    }

    @Test
    void testSelectorForArrayRejectsUnsupportedArrayTypes() {
        @SuppressWarnings("unchecked")
        TypeInformation<Integer[]> objectArrayType =
                (TypeInformation<Integer[]>) Types.OBJECT_ARRAY(Types.INT);

        assertThrows(
                IllegalArgumentException.class,
                () -> KeySelectorUtil.getSelectorForArray(new int[] {0}, objectArrayType));
        assertThrows(
                IllegalArgumentException.class,
                () -> KeySelectorUtil.getSelectorForArray(new int[] {0}, Types.STRING));
    }

    @Test
    void testSerializedSelectorDoesNotExposeTransientTypeInformation() throws Exception {
        TypeInformation<Tuple2<String, Integer>> typeInfo =
                Types.TUPLE(Types.STRING, Types.INT);
        Keys<Tuple2<String, Integer>> keys =
                new Keys.ExpressionKeys<>(new int[] {1}, typeInfo);
        @SuppressWarnings("unchecked")
        KeySelectorUtil.ComparableKeySelector<Tuple2<String, Integer>> selector =
                (KeySelectorUtil.ComparableKeySelector<Tuple2<String, Integer>>)
                        KeySelectorUtil.getSelectorForKeys(
                                keys, typeInfo, new ExecutionConfig());

        KeySelectorUtil.ComparableKeySelector<Tuple2<String, Integer>> copy =
                roundTrip(selector);

        assertEquals(23, copy.getKey(Tuple2.of("ignored", 23)).getField(0));
        assertThrows(IllegalStateException.class, copy::getProducedType);
    }

    @Test
    void testValidateKeyTypeAcceptsHashableNestedTypes() {
        TypeInformation<Tuple2<String, HashablePojo>> typeInfo =
                Types.TUPLE(Types.STRING, Types.POJO(HashablePojo.class));

        assertSame(typeInfo, KeySelectorUtil.validateKeyType(typeInfo));
    }

    @Test
    void testValidateKeyTypeRejectsArraysAndEnums() {
        @SuppressWarnings("unchecked")
        TypeInformation<int[]> arrayType =
                (TypeInformation<int[]>) Types.PRIMITIVE_ARRAY(Types.INT);
        TypeInformation<TestEnum> enumType = Types.ENUM(TestEnum.class);

        assertThrows(InvalidProgramException.class, () -> KeySelectorUtil.validateKeyType(arrayType));
        assertThrows(InvalidProgramException.class, () -> KeySelectorUtil.validateKeyType(enumType));
    }

    @Test
    void testValidateKeyTypeRejectsPojoWithoutHashCode() {
        TypeInformation<NonHashablePojo> typeInfo = Types.POJO(NonHashablePojo.class);

        InvalidProgramException exception =
                assertThrows(
                        InvalidProgramException.class,
                        () -> KeySelectorUtil.validateKeyType(typeInfo));

        assertTrue(exception.getMessage().contains("UNSUPPORTED key types"));
    }

    @Test
    void testValidateKeyTypeRejectsUnsupportedNestedField() {
        @SuppressWarnings("unchecked")
        TypeInformation<Tuple2<String, int[]>> typeInfo =
                (TypeInformation<Tuple2<String, int[]>>)
                        Types.TUPLE(Types.STRING, Types.PRIMITIVE_ARRAY(Types.INT));

        assertThrows(InvalidProgramException.class, () -> KeySelectorUtil.validateKeyType(typeInfo));
    }

    @Test
    void testValidateKeyTypeRejectsArrayOfUnsupportedValues() {
        assertThrows(
                InvalidProgramException.class,
                () -> KeySelectorUtil.validateKeyType(Types.OBJECT_ARRAY(Types.INT)));
    }

    @SuppressWarnings("unchecked")
    private static <T> T roundTrip(T value) throws Exception {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
            output.writeObject(value);
        }
        try (ObjectInputStream input =
                new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
            return (T) input.readObject();
        }
    }

    private enum TestEnum {
        FIRST,
        SECOND
    }

    public static class HashablePojo {
        public int value;

        public HashablePojo() {}

        public HashablePojo(int value) {
            this.value = value;
        }

        @Override
        public int hashCode() {
            return value;
        }

        @Override
        public boolean equals(Object other) {
            return other instanceof HashablePojo && ((HashablePojo) other).value == value;
        }
    }

    public static class NonHashablePojo {
        public int value;
    }

    private static final class IntegerPartitioner implements Partitioner<Integer> {
        @Override
        public int partition(Integer key, int numPartitions) {
            return Math.floorMod(key, numPartitions);
        }
    }

    private static final class StringPartitioner implements Partitioner<String> {
        @Override
        public int partition(String key, int numPartitions) {
            return Math.floorMod(key.hashCode(), numPartitions);
        }
    }
