import org.junit.jupiter.api.Test;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

/** Tests for {@link FieldAccessorFactory} and the accessors it creates. */
class FieldAccessorFactoryTest {

    private final ExecutionConfig executionConfig = new ExecutionConfig();

    @Test
    void testBasicTypeAccessorExposesWholeValue() {
        FieldAccessor<Integer, Integer> accessor =
                FieldAccessorFactory.getAccessor(Types.INT, 0, executionConfig);

        assertEquals(Types.INT, accessor.getFieldType());
        assertEquals(4, accessor.get(4));
        assertEquals(9, accessor.set(4, 9));
        assertThrows(
                CompositeType.InvalidFieldReferenceException.class,
                () -> FieldAccessorFactory.getAccessor(Types.INT, 1, executionConfig));
    }

    @Test
    void testPrimitiveArrayAccessorGetsAndSetsByPosition() {
        @SuppressWarnings("unchecked")
        TypeInformation<int[]> typeInfo =
                (TypeInformation<int[]>) Types.PRIMITIVE_ARRAY(Types.INT);
        int[] record = new int[] {10, 20, 30};
        FieldAccessor<int[], Integer> accessor =
                FieldAccessorFactory.getAccessor(typeInfo, 1, executionConfig);

        assertEquals(BasicTypeInfo.INT_TYPE_INFO, accessor.getFieldType());
        assertEquals(20, accessor.get(record));
        assertSame(record, accessor.set(record, 99));
        assertEquals(99, record[1]);
        assertThrows(
                CompositeType.InvalidFieldReferenceException.class,
                () -> FieldAccessorFactory.getAccessor(typeInfo, -1, executionConfig));
    }

    @Test
    void testBoxedArrayAccessorSupportsIndexExpression() {
        Integer[] record = new Integer[] {3, 5, 8};
        FieldAccessor<Integer[], Integer> accessor =
                FieldAccessorFactory.getAccessor(
                        BasicArrayTypeInfo.INT_ARRAY_TYPE_INFO, "2", executionConfig);

        assertEquals(BasicTypeInfo.INT_TYPE_INFO, accessor.getFieldType());
        assertEquals(8, accessor.get(record));
        accessor.set(record, 13);
        assertEquals(13, record[2]);
        assertThrows(
                CompositeType.InvalidFieldReferenceException.class,
                () ->
                        FieldAccessorFactory.getAccessor(
                                BasicArrayTypeInfo.INT_ARRAY_TYPE_INFO,
                                "not-an-index",
                                executionConfig));
    }

    @Test
    void testTupleAccessorSupportsPositionAndFieldName() {
        TypeInformation<Tuple2<String, Integer>> typeInfo =
                Types.TUPLE(Types.STRING, Types.INT);
        Tuple2<String, Integer> record = Tuple2.of("before", 1);

        FieldAccessor<Tuple2<String, Integer>, Integer> byPosition =
                FieldAccessorFactory.getAccessor(typeInfo, 1, executionConfig);
        FieldAccessor<Tuple2<String, Integer>, String> byName =
                FieldAccessorFactory.getAccessor(typeInfo, "f0", executionConfig);

        assertEquals(Types.INT, byPosition.getFieldType());
        assertEquals(1, byPosition.get(record));
        byPosition.set(record, 2);
        assertEquals(2, record.f1);

        assertEquals(Types.STRING, byName.getFieldType());
        assertEquals("before", byName.get(record));
        byName.set(record, "after");
        assertEquals("after", record.f0);

        assertThrows(
                CompositeType.InvalidFieldReferenceException.class,
                () -> FieldAccessorFactory.getAccessor(typeInfo, 2, executionConfig));
        assertThrows(
                CompositeType.InvalidFieldReferenceException.class,
                () -> FieldAccessorFactory.getAccessor(typeInfo, "unknown", executionConfig));
        assertThrows(
                CompositeType.InvalidFieldReferenceException.class,
                () -> FieldAccessorFactory.getAccessor(typeInfo, "*", executionConfig));
    }

    @Test
    void testNestedTupleAccessorTraversesBothLevels() {
        @SuppressWarnings("unchecked")
        TypeInformation<Tuple2<Tuple2<String, Integer>, Long>> typeInfo =
                (TypeInformation<Tuple2<Tuple2<String, Integer>, Long>>)
                        Types.TUPLE(Types.TUPLE(Types.STRING, Types.INT), Types.LONG);
        Tuple2<Tuple2<String, Integer>, Long> record =
                Tuple2.of(Tuple2.of("key", 5), 100L);

        FieldAccessor<Tuple2<Tuple2<String, Integer>, Long>, Integer> accessor =
                FieldAccessorFactory.getAccessor(typeInfo, "f0.f1", executionConfig);

        assertEquals(Types.INT, accessor.getFieldType());
        assertEquals(5, accessor.get(record));
        assertSame(record, accessor.set(record, 21));
        assertEquals(21, record.f0.f1);
    }

    @Test
    void testPojoAccessorGetsAndSetsSimpleAndNestedFields() {
        TypeInformation<OuterPojo> typeInfo = Types.POJO(OuterPojo.class);
        OuterPojo record = new OuterPojo("old", new InnerPojo(1, "inner-old"));
        FieldAccessor<OuterPojo, String> nameAccessor =
                FieldAccessorFactory.getAccessor(typeInfo, "name", executionConfig);
        FieldAccessor<OuterPojo, Integer> numberAccessor =
                FieldAccessorFactory.getAccessor(typeInfo, "inner.number", executionConfig);

        assertEquals(Types.STRING, nameAccessor.getFieldType());
        assertEquals("old", nameAccessor.get(record));
        assertSame(record, nameAccessor.set(record, "new"));
        assertEquals("new", record.name);

        assertEquals(Types.INT, numberAccessor.getFieldType());
        assertEquals(1, numberAccessor.get(record));
        assertSame(record, numberAccessor.set(record, 42));
        assertEquals(42, record.inner.number);
    }

    @Test
    void testPojoAccessorSurvivesSerialization() throws Exception {
        TypeInformation<OuterPojo> typeInfo = Types.POJO(OuterPojo.class);
        FieldAccessor<OuterPojo, Integer> accessor =
                FieldAccessorFactory.getAccessor(typeInfo, "inner.number", executionConfig);
        OuterPojo record = new OuterPojo("name", new InnerPojo(3, "text"));

        FieldAccessor<OuterPojo, Integer> copy = roundTrip(accessor);

        assertEquals(3, copy.get(record));
        copy.set(record, 77);
        assertEquals(77, record.inner.number);
    }

    @Test
    void testPojoAccessorRejectsUnknownFieldAndPositionalSelection() {
        TypeInformation<OuterPojo> typeInfo = Types.POJO(OuterPojo.class);

        assertThrows(
                CompositeType.InvalidFieldReferenceException.class,
                () -> FieldAccessorFactory.getAccessor(typeInfo, "missing", executionConfig));
        assertThrows(
                CompositeType.InvalidFieldReferenceException.class,
                () -> FieldAccessorFactory.getAccessor(typeInfo, 0, executionConfig));
    }

    @Test
    void testBasicFieldExpressionsAcceptOnlyWildcardOrZero() {
        FieldAccessor<String, String> wildcard =
                FieldAccessorFactory.getAccessor(Types.STRING, "*", executionConfig);
        FieldAccessor<String, String> zero =
                FieldAccessorFactory.getAccessor(Types.STRING, "0", executionConfig);

        assertEquals("value", wildcard.get("value"));
        assertEquals("replacement", wildcard.set("value", "replacement"));
        assertEquals("value", zero.get("value"));

        assertThrows(
                CompositeType.InvalidFieldReferenceException.class,
                () -> FieldAccessorFactory.getAccessor(Types.STRING, "1", executionConfig));
        assertThrows(
                CompositeType.InvalidFieldReferenceException.class,
                () -> FieldAccessorFactory.getAccessor(Types.STRING, "text", executionConfig));
    }

    @Test
    void testArrayAccessorRejectsNegativePositionExpression() {
        assertThrows(
                CompositeType.InvalidFieldReferenceException.class,
                () ->
                        FieldAccessorFactory.getAccessor(
                                BasicArrayTypeInfo.INT_ARRAY_TYPE_INFO,
                                "-1",
                                executionConfig));
    }

    @SuppressWarnings("unchecked")
    private static <T> T roundTrip(T value) throws Exception {
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
            output.writeObject(value);
        }
        try (ObjectInputStream input =
                new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
            return (T) input.readObject();
        }
    }

    public static class InnerPojo {
        public int number;
        public String text;

        public InnerPojo() {}

        public InnerPojo(int number, String text) {
            this.number = number;
            this.text = text;
        }
