    @Test
    void testSetOutputTypeConfiguresWrappedFunction() {
        ConfigurableFunction function = new ConfigurableFunction();
        TypeInformation<String> outputType = Types.STRING;
        ExecutionConfig executionConfig = new ExecutionConfig();

        StreamingFunctionUtils.setOutputType(
                new TestWrappingFunction(new TestWrappingFunction(function)),
                outputType,
                executionConfig);

        assertEquals(1, function.setOutputTypeCalls);
        assertSame(outputType, function.outputType);
        assertSame(executionConfig, function.executionConfig);
    }

    @Test
    void testSetOutputTypeIgnoresFunctionThatDoesNotImplementOutputTypeConfigurable() {
        StreamingFunctionUtils.setOutputType(
                new NoOpFunction(), Types.STRING, new ExecutionConfig());
    }

    @Test
    void testSetOutputTypeRejectsNullArguments() {
