import org.junit.jupiter.api.Test;

import java.util.Collections;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/** Tests for {@link StreamGraphUtils}. */
class StreamGraphUtilsTest {

    @Test
    void testUidValidationIsSkippedWhenAutoGenerationIsEnabled() {
        StreamGraph graph = graphWithAutoGeneratedUids(true);
        PhysicalTransformation<String> transformation = physicalTransformation("map");

        assertDoesNotThrow(() -> StreamGraphUtils.validateTransformationUid(graph, transformation));
    }

    @Test
    void testUidValidationRejectsPhysicalTransformationWithoutUidOrHash() {
        StreamGraph graph = graphWithAutoGeneratedUids(false);
        PhysicalTransformation<String> transformation = physicalTransformation("map");

        IllegalStateException exception =
                assertThrows(
                        IllegalStateException.class,
                        () -> StreamGraphUtils.validateTransformationUid(graph, transformation));

        assertTrue(exception.getMessage().contains("Auto generated UIDs have been disabled"));
        assertTrue(exception.getMessage().contains("map"));
    }

    @Test
    void testUidValidationAcceptsUidOrUserProvidedHash() {
        StreamGraph graph = graphWithAutoGeneratedUids(false);
        PhysicalTransformation<String> withUid = physicalTransformation("with-uid");
        withUid.setUid("my-uid");

        PhysicalTransformation<String> withHash = physicalTransformation("with-hash");
        withHash.setUidHash("0123456789abcdef0123456789abcdef");

        assertDoesNotThrow(() -> StreamGraphUtils.validateTransformationUid(graph, withUid));
        assertDoesNotThrow(() -> StreamGraphUtils.validateTransformationUid(graph, withHash));
    }

    @Test
    void testUidValidationIgnoresNonPhysicalTransformations() {
        StreamGraph graph = graphWithAutoGeneratedUids(false);
        Transformation<String> logicalTransformation =
                new Transformation<String>("logical", Types.STRING, 1) {
                    @Override
                    protected List<Transformation<?>> getTransitivePredecessorsInternal() {
                        return Collections.emptyList();
                    }

                    @Override
                    public List<Transformation<?>> getInputs() {
                        return Collections.emptyList();
                    }
                };

        assertDoesNotThrow(
                () ->
                        StreamGraphUtils.validateTransformationUid(
                                graph, logicalTransformation));
    }

    @Test
    void testExplicitBufferTimeoutOverridesDefault() {
        TestStreamGraph graph = graphWithAutoGeneratedUids(true);
        graph.addOperatorNode(7);
        Transformation<String> transformation = physicalTransformation("explicit");
        transformation.setBufferTimeout(0L);

        StreamGraphUtils.configureBufferTimeout(graph, 7, transformation, 100L);

        assertEquals(0L, graph.getStreamNode(7).getBufferTimeout());
    }

    @Test
    void testNegativeBufferTimeoutUsesDefault() {
        TestStreamGraph graph = graphWithAutoGeneratedUids(true);
        graph.addOperatorNode(8);
        Transformation<String> transformation = physicalTransformation("default");

        StreamGraphUtils.configureBufferTimeout(graph, 8, transformation, 200L);

        assertEquals(200L, graph.getStreamNode(8).getBufferTimeout());
    }

    @Test
    void testAnyNegativeBufferTimeoutUsesDefault() {
        TestStreamGraph graph = graphWithAutoGeneratedUids(true);
        graph.addOperatorNode(9);
        Transformation<String> transformation = physicalTransformation("default");
        transformation.setBufferTimeout(-123L);

        StreamGraphUtils.configureBufferTimeout(graph, 9, transformation, 300L);

        assertEquals(300L, graph.getStreamNode(9).getBufferTimeout());
    }

    private static TestStreamGraph graphWithAutoGeneratedUids(boolean enabled) {
        ExecutionConfig executionConfig = new ExecutionConfig();
        if (enabled) {
            executionConfig.enableAutoGeneratedUIDs();
        } else {
            executionConfig.disableAutoGeneratedUIDs();
        }
        return new TestStreamGraph(executionConfig);
    }

    private static PhysicalTransformation<String> physicalTransformation(String name) {
        return new OneInputTransformation<>(
                null, name, (StreamOperatorFactory<String>) null, Types.STRING, 1);
    }

    private static final class TestStreamGraph extends StreamGraph {
        private TestStreamGraph(ExecutionConfig executionConfig) {
            super(
                    new Configuration(),
                    executionConfig,
                    new CheckpointConfig(),
                    org.apache.flink.streaming.api.environment.SavepointRestoreSettings.none());
        }

        private void addOperatorNode(int id) {
            addNode(
                    id,
                    null,
                    null,
                    OneInputStreamTask.class,
                    (StreamOperatorFactory<?>) null,
                    "node-" + id);
        }
    }
}
EOF"}

