        ts.setNanos(ts.getNanos() + value.getNanoOfMillisecond());
        return ts;
    }

    @Override
    Timestamp toExternalImpl(RowData row, int column) {
        return toExternalImpl(row.getTimestamp(column, precision));
    }
}

