public static DataFormatConverter getConverterForDataType(DataType originDataType) {
    DataType dataType = originDataType.nullable();
    DataFormatConverter converter = TYPE_TO_CONVERTER.get(dataType);
    if (converter != null) {
        return converter;
    }

    Class<?> clazz = dataType.getConversionClass();
    LogicalType logicalType = dataType.getLogicalType();
    switch (logicalType.getTypeRoot()) {
        case CHAR:
        case VARCHAR:
            if (clazz == String.class) {
                return StringConverter.INSTANCE;
            } else if (clazz == StringData.class) {
                return StringDataConverter.INSTANCE;
            } else {
                throw new RuntimeException("Not support class for VARCHAR: " + clazz);
            }
        case BINARY:
        case VARBINARY:
            return PrimitiveByteArrayConverter.INSTANCE;
        case DECIMAL:
            Tuple2<Integer, Integer> ps = getPrecision(logicalType);
            if (clazz == BigDecimal.class) {
                return new BigDecimalConverter(ps.f0, ps.f1);
            } else if (clazz == DecimalData.class) {
                return new DecimalDataConverter(ps.f0, ps.f1);
            } else {
                throw new RuntimeException(
                        "Not support conversion class for DECIMAL: " + clazz);
            }
        case TIMESTAMP_WITHOUT_TIME_ZONE:
            int precisionOfTS = getDateTimePrecision(logicalType);
            if (clazz == Timestamp.class) {
                return new TimestampConverter(precisionOfTS);
            } else if (clazz == LocalDateTime.class) {
                return new LocalDateTimeConverter(precisionOfTS);
            } else if (clazz == TimestampData.class) {
                return new TimestampDataConverter(precisionOfTS);
            } else {
                throw new RuntimeException(
                        "Not support conversion class for TIMESTAMP WITHOUT TIME ZONE: "
                                + clazz);
            }
        case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
            int precisionOfLZTS = getDateTimePrecision(logicalType);
            if (clazz == Instant.class) {
                return new InstantConverter(precisionOfLZTS);
            } else if (clazz == Long.class || clazz == long.class) {
                return new LongTimestampDataConverter(precisionOfLZTS);
            } else if (clazz == TimestampData.class) {
                return new TimestampDataConverter(precisionOfLZTS);
            } else if (clazz == Timestamp.class) {
                return new TimestampLtzConverter(precisionOfLZTS);
            } else {
                throw new RuntimeException(
                        "Not support conversion class for TIMESTAMP WITH LOCAL TIME ZONE: "
                                + clazz);
            }
        case ARRAY:
            if (clazz == ArrayData.class) {
                return ArrayDataConverter.INSTANCE;
            } else if (clazz == boolean[].class) {
                return PrimitiveBooleanArrayConverter.INSTANCE;
            } else if (clazz == short[].class) {
                return PrimitiveShortArrayConverter.INSTANCE;
            } else if (clazz == int[].class) {
                return PrimitiveIntArrayConverter.INSTANCE;
            } else if (clazz == long[].class) {
                return PrimitiveLongArrayConverter.INSTANCE;
            } else if (clazz == float[].class) {
                return PrimitiveFloatArrayConverter.INSTANCE;
            } else if (clazz == double[].class) {
                return PrimitiveDoubleArrayConverter.INSTANCE;
            }
            if (dataType instanceof CollectionDataType) {
                return new ObjectArrayConverter(
                        ((CollectionDataType) dataType)
                                .getElementDataType()
                                .bridgedTo(clazz.getComponentType()));
            } else {
                BasicArrayTypeInfo typeInfo =
                        (BasicArrayTypeInfo)
                                ((LegacyTypeInformationType) dataType.getLogicalType())
                                        .getTypeInformation();
                return new ObjectArrayConverter(
                        fromLegacyInfoToDataType(typeInfo.getComponentInfo())
                                .bridgedTo(clazz.getComponentType()));
            }
        case MAP:
            if (clazz == MapData.class) {
                return MapDataConverter.INSTANCE;
            }
            KeyValueDataType keyValueDataType = (KeyValueDataType) dataType;
            return new MapConverter(
                    keyValueDataType.getKeyDataType(), keyValueDataType.getValueDataType());
        case MULTISET:
            if (clazz == MapData.class) {
                return MapDataConverter.INSTANCE;
            }
            CollectionDataType collectionDataType = (CollectionDataType) dataType;
            return new MapConverter(
                    collectionDataType.getElementDataType(),
                    DataTypes.INT().bridgedTo(Integer.class));
        case ROW:
        case STRUCTURED_TYPE:
            TypeInformation<?> asTypeInfo = fromDataTypeToTypeInfo(dataType);
            if (asTypeInfo instanceof InternalTypeInfo && clazz == RowData.class) {
                LogicalType realLogicalType =
                        ((InternalTypeInfo<?>) asTypeInfo).toLogicalType();
                return new RowDataConverter(getFieldCount(realLogicalType));
            }

            // legacy

            CompositeType compositeType = (CompositeType) asTypeInfo;
            DataType[] fieldTypes =
                    Stream.iterate(0, x -> x + 1)
                            .limit(compositeType.getArity())

                LogicalType realLogicalType =
                        ((InternalTypeInfo<?>) asTypeInfo).toLogicalType();
                return new RowDataConverter(getFieldCount(realLogicalType));
            }

            // legacy

            CompositeType compositeType = (CompositeType) asTypeInfo;
            DataType[] fieldTypes =
                    Stream.iterate(0, x -> x + 1)
                            .limit(compositeType.getArity())
                            .map((Function<Integer, TypeInformation>) compositeType::getTypeAt)
                            .map(TypeConversions::fromLegacyInfoToDataType)
                            .toArray(DataType[]::new);
            if (clazz == RowData.class) {
                return new RowDataConverter(compositeType.getArity());
            } else if (clazz == Row.class) {
                return new RowConverter(fieldTypes);
            } else if (Tuple.class.isAssignableFrom(clazz)) {
                return new TupleConverter((Class<Tuple>) clazz, fieldTypes);
            } else if (CaseClassConverter.PRODUCT_CLASS != null
                    && CaseClassConverter.PRODUCT_CLASS.isAssignableFrom(clazz)) {
                return new CaseClassConverter((TupleTypeInfoBase) compositeType, fieldTypes);
            } else if (compositeType instanceof PojoTypeInfo) {
                return new PojoConverter((PojoTypeInfo) compositeType, fieldTypes);
            } else {
                throw new IllegalStateException(
                        "Cannot find a converter for type "
                                + compositeType
                                + ". If the target should be a converter to scala.Product, then you might have a scala classpath issue.");
            }
        case RAW:
            if (logicalType instanceof RawType) {
                final RawType<?> rawType = (RawType<?>) logicalType;
                if (clazz == RawValueData.class) {
                    return RawValueDataConverter.INSTANCE;
                } else {
                    return new GenericConverter<>(rawType.getTypeSerializer());
                }
            }

            // legacy

            TypeInformation typeInfo =
                    logicalType instanceof LegacyTypeInformationType
                            ? ((LegacyTypeInformationType) logicalType).getTypeInformation()
                            : ((TypeInformationRawType) logicalType).getTypeInformation();

            // planner type info
            if (typeInfo instanceof StringDataTypeInfo) {
                return StringDataConverter.INSTANCE;
            } else if (typeInfo instanceof DecimalDataTypeInfo) {
                DecimalDataTypeInfo decimalType = (DecimalDataTypeInfo) typeInfo;
                return new DecimalDataConverter(decimalType.precision(), decimalType.scale());
            } else if (typeInfo instanceof BigDecimalTypeInfo) {
                BigDecimalTypeInfo decimalType = (BigDecimalTypeInfo) typeInfo;
                return new BigDecimalConverter(decimalType.precision(), decimalType.scale());
            } else if (typeInfo instanceof TimestampDataTypeInfo) {
                TimestampDataTypeInfo timestampDataTypeInfo = (TimestampDataTypeInfo) typeInfo;
                return new TimestampDataConverter(timestampDataTypeInfo.getPrecision());
            } else if (typeInfo instanceof LegacyLocalDateTimeTypeInfo) {
                LegacyLocalDateTimeTypeInfo dateTimeType =
                        (LegacyLocalDateTimeTypeInfo) typeInfo;
                return new LocalDateTimeConverter(dateTimeType.getPrecision());
            } else if (typeInfo instanceof LegacyTimestampTypeInfo) {
                LegacyTimestampTypeInfo timestampType = (LegacyTimestampTypeInfo) typeInfo;
                return new TimestampConverter(timestampType.getPrecision());
            } else if (typeInfo instanceof LegacyInstantTypeInfo) {
                LegacyInstantTypeInfo instantTypeInfo = (LegacyInstantTypeInfo) typeInfo;
                return new InstantConverter(instantTypeInfo.getPrecision());
            }

            if (clazz == RawValueData.class) {
                return RawValueDataConverter.INSTANCE;
            } else if (clazz == Variant.class) {
                return VariantConverter.INSTANCE;
            }

            return new GenericConverter(typeInfo.createSerializer(new SerializerConfigImpl()));
        default:
            throw new RuntimeException("Not support dataType: " + dataType);
    }
}

private static Tuple2<Integer, Integer> getPrecision(LogicalType logicalType) {
    Tuple2<Integer, Integer> ps = new Tuple2<>();
    if (logicalType instanceof DecimalType) {
        DecimalType decimalType = (DecimalType) logicalType;
        ps.f0 = decimalType.getPrecision();
        ps.f1 = decimalType.getScale();
    } else {
        TypeInformation typeInfo =
                ((LegacyTypeInformationType) logicalType).getTypeInformation();
        if (typeInfo instanceof BigDecimalTypeInfo) {
            BigDecimalTypeInfo decimalType = (BigDecimalTypeInfo) typeInfo;
            ps.f0 = decimalType.precision();
            ps.f1 = decimalType.scale();
        } else if (typeInfo instanceof DecimalDataTypeInfo) {
            DecimalDataTypeInfo decimalType = (DecimalDataTypeInfo) typeInfo;
            ps.f0 = decimalType.precision();
            ps.f1 = decimalType.scale();
        } else {
            ps.f0 = DecimalDataUtils.DECIMAL_SYSTEM_DEFAULT.getPrecision();
            ps.f1 = DecimalDataUtils.DECIMAL_SYSTEM_DEFAULT.getScale();
        }
    }
    return ps;
}

private static int getDateTimePrecision(LogicalType logicalType) {
    if (logicalType instanceof LocalZonedTimestampType) {
        return ((LocalZonedTimestampType) logicalType).getPrecision();
    } else if (logicalType instanceof TimestampType) {
        return ((TimestampType) logicalType).getPrecision();
    } else {
        TypeInformation typeInfo =
                ((LegacyTypeInformationType) logicalType).getTypeInformation();
        if (typeInfo instanceof LegacyInstantTypeInfo) {
            return ((LegacyInstantTypeInfo) typeInfo).getPrecision();
        } else if (typeInfo instanceof LegacyLocalDateTimeTypeInfo) {
            return ((LegacyLocalDateTimeTypeInfo) typeInfo).getPrecision();
        } else {
            // TimestampType.DEFAULT_PRECISION == LocalZonedTimestampType.DEFAULT_PRECISION == 6
            return TimestampType.DEFAULT_PRECISION;
        }
    }
}

/**
 * Converter between internal data format and java format.
 *
 * @param <Internal> Internal data format.
 * @param <External> External data format.
 */
public abstract static class DataFormatConverter<Internal, External> implements Serializable {

    public static BinaryStringData substringSQL(BinaryStringData str, int pos) {
        return substringSQL(str, pos, Integer.MAX_VALUE);
    }

    public static BinaryStringData substringSQL(BinaryStringData str, int pos, int length) {
        if (length < 0) {
            return null;
        }
        str.ensureMaterialized();
        if (str.equals(EMPTY_UTF8)) {
            return EMPTY_UTF8;
        }

        int start;
        int end;
        int numChars = str.numChars();

        if (pos > 0) {
            start = pos - 1;
            if (start >= numChars) {
                return EMPTY_UTF8;
            }
        } else if (pos < 0) {
            start = numChars + pos;
            if (start < 0) {
                return EMPTY_UTF8;
            }
        } else {
            start = 0;
        }

        if ((numChars - start) < length) {
            end = numChars;
        } else {
            end = start + length;
        }
        return str.substring(start, end);
    }

    /**
     * Concatenates input strings together into a single string. Returns NULL if any argument is
     * NULL.
     */
    public static BinaryStringData concat(BinaryStringData... inputs) {
        return concat(Arrays.asList(inputs));
    }

    public static BinaryStringData concat(Iterable<BinaryStringData> inputs) {
        // Compute the total length of the result.
        int totalLength = 0;
        for (BinaryStringData input : inputs) {
            if (input == null) {
                return null;
            }

            input.ensureMaterialized();
            totalLength += input.getSizeInBytes();
        }

        // Allocate a new byte array, and copy the inputs one by one into it.
        final byte[] result = new byte[totalLength];
        int offset = 0;
        for (BinaryStringData input : inputs) {
            if (input != null) {
                int len = input.getSizeInBytes();
                SegmentsUtil.copyToBytes(
                        input.getSegments(), input.getOffset(), result, offset, len);
                offset += len;
            }
        }
        return fromBytes(result);
    }

    /**
     * Concatenates input strings together into a single string using the separator. Returns NULL If
     * the separator is NULL.
     *
     * <p>Note: CONCAT_WS() does not skip any empty strings, however it does skip any NULL values
     * after the separator. For example, concat_ws(",", "a", null, "c") would yield "a,c".
     */
    public static BinaryStringData concatWs(
            BinaryStringData separator, BinaryStringData... inputs) {
        return concatWs(separator, Arrays.asList(inputs));
    }

    public static BinaryStringData concatWs(
            BinaryStringData separator, Iterable<BinaryStringData> inputs) {
        if (null == separator) {
            return null;
        }

        separator.ensureMaterialized();

        int numInputBytes = 0; // total number of bytes from the inputs
        int numInputs = 0; // number of non-null inputs
        for (BinaryStringData input : inputs) {
            if (input != null) {
                input.ensureMaterialized();
                numInputBytes += input.getSizeInBytes();
                numInputs++;
            }
        }

        if (numInputs == 0) {
            // Return an empty string if there is no input, or all the inputs are null.
            return EMPTY_UTF8;
        }

        // Allocate a new byte array, and copy the inputs one by one into it.
        // The size of the new array is the size of all inputs, plus the separators.
        final byte[] result =
                new byte[numInputBytes + (numInputs - 1) * separator.getSizeInBytes()];
        int offset = 0;

        int j = 0;
        for (BinaryStringData input : inputs) {
            if (input != null) {
                int len = input.getSizeInBytes();
                SegmentsUtil.copyToBytes(
                        input.getSegments(), input.getOffset(), result, offset, len);
                offset += len;

                j++;
                // Add separator if this is not the last input.
                if (j < numInputs) {
                    SegmentsUtil.copyToBytes(
                            separator.getSegments(),
                            separator.getOffset(),
                            result,
                            offset,
                            separator.getSizeInBytes());
                    offset += separator.getSizeInBytes();
                }
            }
        }
        return fromBytes(result);
    }

    /**
     * Reverse each character in current string.
     *
     * @return a new string which character order is reverse to current string.
     */
    public static BinaryStringData reverse(BinaryStringData str) {
        str.ensureMaterialized();
        if (str.inFirstSegment()) {
            byte[] result = new byte[str.getSizeInBytes()];
            // position in byte
            int byteIdx = 0;
            while (byteIdx < str.getSizeInBytes()) {
                int charBytes = numBytesForFirstByte(str.getByteOneSegment(byteIdx));
                str.getSegments()[0].get(
                        str.getOffset() + byteIdx,
                        result,
                        result.length - byteIdx - charBytes,
                        charBytes);
                byteIdx += charBytes;
            }
            return BinaryStringData.fromBytes(result);
        } else {
            return reverseMultiSegs(str);
        }
    }

    private static BinaryStringData reverseMultiSegs(BinaryStringData str) {
        byte[] result = new byte[str.getSizeInBytes()];
        // position in byte
        int byteIdx = 0;
        int segSize = str.getSegments()[0].size();
        BinaryStringData.SegmentAndOffset index = str.firstSegmentAndOffset(segSize);
        while (byteIdx < str.getSizeInBytes()) {
            int charBytes = numBytesForFirstByte(index.value());
            SegmentsUtil.copyMultiSegmentsToBytes(
                    str.getSegments(),
                    str.getOffset() + byteIdx,
                    result,
                    result.length - byteIdx - charBytes,
                    charBytes);
            byteIdx += charBytes;
            index.skipBytes(charBytes, segSize);
        }
        return BinaryStringData.fromBytes(result);
    }

    /**
     * Walk each character of current string from both ends, remove the character if it is in trim
     * string. Return the new substring which both ends trim characters have been removed.
     *
     * @param trimStr the trim string
     * @return A subString which both ends trim characters have been removed.
     */
    public static BinaryStringData trim(BinaryStringData str, BinaryStringData trimStr) {
        if (trimStr == null) {
            return null;
        }
        return trimRight(trimLeft(str, trimStr), trimStr);
    }

    public static BinaryStringData trimLeft(BinaryStringData str) {
        str.ensureMaterialized();
        if (str.inFirstSegment()) {
            int s = 0;
            // skip all of the space (0x20) in the left side
            while (s < str.getSizeInBytes() && str.getByteOneSegment(s) == 0x20) {
                s++;
            }
            if (s == str.getSizeInBytes()) {
                // empty string
                return EMPTY_UTF8;
            } else {
                return str.copyBinaryStringInOneSeg(s, str.getSizeInBytes() - s);
            }
        } else {
            return trimLeftSlow(str);
        }
    }

    private static BinaryStringData trimLeftSlow(BinaryStringData str) {
        int s = 0;
        int segSize = str.getSegments()[0].size();
        BinaryStringData.SegmentAndOffset front = str.firstSegmentAndOffset(segSize);
        // skip all of the space (0x20) in the left side
        while (s < str.getSizeInBytes() && front.value() == 0x20) {
            s++;
            front.nextByte(segSize);
        }
        if (s == str.getSizeInBytes()) {
            // empty string
            return EMPTY_UTF8;
        } else {
            return str.copyBinaryString(s, str.getSizeInBytes() - 1);
        }
    }

    public static boolean isEmpty(BinaryStringData str) {
        // check javaObject or binarySection directly rather than call
        // BinaryStringData#getSizeInBytes to avoid performance loss caused by materialization
        if (str.javaObject != null) {
            return str.javaObject.isEmpty();
        } else {
            return str.binarySection == null || str.binarySection.getSizeInBytes() == 0;
        }
    }

    public static boolean isSpaceString(BinaryStringData str) {
        if (str.javaObject != null) {
            return str.javaObject.equals(" ");
        } else {
            return str.byteAt(0) == ' ';
        }
    }

    /**
     * Walk each character of current string from left end, remove the character if it is in trim
     * string. Stops at the first character which is not in trim string. Return the new substring.
     *
     * @param trimStr the trim string
     * @return A subString which removes all of the character from the left side that is in trim
     *     string.
     */
    public static BinaryStringData trimLeft(BinaryStringData str, BinaryStringData trimStr) {
        str.ensureMaterialized();
        if (trimStr == null) {
            return null;
        }
        trimStr.ensureMaterialized();
        if (isSpaceString(trimStr)) {
            return trimLeft(str);
        }
        if (str.inFirstSegment()) {
            int searchIdx = 0;
            while (searchIdx < str.getSizeInBytes()) {
                int charBytes = numBytesForFirstByte(str.getByteOneSegment(searchIdx));
                BinaryStringData currentChar = str.copyBinaryStringInOneSeg(searchIdx, charBytes);
                // try to find the matching for the character in the trimString characters.
                if (trimStr.contains(currentChar)) {
                    searchIdx += charBytes;
                } else {
                    break;
                }
            }
            // empty string
            if (searchIdx >= str.getSizeInBytes()) {
                return EMPTY_UTF8;
            } else {
                return str.copyBinaryStringInOneSeg(searchIdx, str.getSizeInBytes() - searchIdx);
            }
        } else {
            return trimLeftSlow(str, trimStr);
        }
    }

    private static BinaryStringData trimLeftSlow(BinaryStringData str, BinaryStringData trimStr) {
        int searchIdx = 0;
        int segSize = str.getSegments()[0].size();
        BinaryStringData.SegmentAndOffset front = str.firstSegmentAndOffset(segSize);
        while (searchIdx < str.getSizeInBytes()) {
            int charBytes = numBytesForFirstByte(front.value());
            BinaryStringData currentChar =
                    str.copyBinaryString(searchIdx, searchIdx + charBytes - 1);
            if (trimStr.contains(currentChar)) {
                searchIdx += charBytes;
                front.skipBytes(charBytes, segSize);
            } else {
                break;
            }
        }
        if (searchIdx == str.getSizeInBytes()) {
            // empty string
            return EMPTY_UTF8;
        } else {
            return str.copyBinaryString(searchIdx, str.getSizeInBytes() - 1);
        }
    }

    public static BinaryStringData trimRight(BinaryStringData str) {
        str.ensureMaterialized();
        if (str.inFirstSegment()) {
            int e = str.getSizeInBytes() - 1;
            // skip all of the space (0x20) in the right side
            while (e >= 0 && str.getByteOneSegment(e) == 0x20) {
                e--;
            }

            if (e < 0) {
                // empty string
                return EMPTY_UTF8;
            } else {
                return str.copyBinaryStringInOneSeg(0, e + 1);
            }
        } else {
            return trimRightSlow(str);
        }
    }

    private static BinaryStringData trimRightSlow(BinaryStringData str) {
        int e = str.getSizeInBytes() - 1;
        int segSize = str.getSegments()[0].size();
        BinaryStringData.SegmentAndOffset behind = str.lastSegmentAndOffset(segSize);
        // skip all of the space (0x20) in the right side
        while (e >= 0 && behind.value() == 0x20) {
            e--;
            behind.previousByte(segSize);
        }

        if (e < 0) {
            // empty string
            return EMPTY_UTF8;
        } else {
            return str.copyBinaryString(0, e);
        }
    }

    /**
     * Walk each character of current string from right end, remove the character if it is in trim
     * string. Stops at the first character which is not in trim string. Return the new substring.
     *
     * @param trimStr the trim string
     * @return A subString which removes all of the character from the right side that is in trim
     *     string.
     */
    public static BinaryStringData trimRight(BinaryStringData str, BinaryStringData trimStr) {
        str.ensureMaterialized();
        if (trimStr == null) {
            return null;
        }
        trimStr.ensureMaterialized();
        if (isSpaceString(trimStr)) {
            return trimRight(str);
        }
        if (str.inFirstSegment()) {
            int charIdx = 0;
            int byteIdx = 0;
            // each element in charLens is length of character in the source string
            int[] charLens = new int[str.getSizeInBytes()];
            // each element in charStartPos is start position of first byte in the source string
            int[] charStartPos = new int[str.getSizeInBytes()];
            while (byteIdx < str.getSizeInBytes()) {
                charStartPos[charIdx] = byteIdx;
                charLens[charIdx] = numBytesForFirstByte(str.getByteOneSegment(byteIdx));
                byteIdx += charLens[charIdx];
                charIdx++;
            }
            // searchIdx points to the first character which is not in trim string from the right
            // end.
            int searchIdx = str.getSizeInBytes() - 1;
            charIdx -= 1;
            while (charIdx >= 0) {
                BinaryStringData currentChar =
                        str.copyBinaryStringInOneSeg(charStartPos[charIdx], charLens[charIdx]);
                if (trimStr.contains(currentChar)) {
                    searchIdx -= charLens[charIdx];
                } else {
                    break;
                }
                charIdx--;
            }
            if (searchIdx < 0) {
                // empty string
                return EMPTY_UTF8;
            } else {
                return str.copyBinaryStringInOneSeg(0, searchIdx + 1);
            }
        } else {
            return trimRightSlow(str, trimStr);
        }
    }

    private static BinaryStringData trimRightSlow(BinaryStringData str, BinaryStringData trimStr) {
        int charIdx = 0;
        int byteIdx = 0;
        int segSize = str.getSegments()[0].size();
        BinaryStringData.SegmentAndOffset index = str.firstSegmentAndOffset(segSize);
        // each element in charLens is length of character in the source string
        int[] charLens = new int[str.getSizeInBytes()];
        // each element in charStartPos is start position of first byte in the source string
        int[] charStartPos = new int[str.getSizeInBytes()];
        while (byteIdx < str.getSizeInBytes()) {
            charStartPos[charIdx] = byteIdx;
            int charBytes = numBytesForFirstByte(index.value());
            charLens[charIdx] = charBytes;
            byteIdx += charBytes;
            charIdx++;
            index.skipBytes(charBytes, segSize);
        }
        // searchIdx points to the first character which is not in trim string from the right
        // end.
        int searchIdx = str.getSizeInBytes() - 1;
        charIdx -= 1;
        while (charIdx >= 0) {
            BinaryStringData currentChar =
                    str.copyBinaryString(
                            charStartPos[charIdx], charStartPos[charIdx] + charLens[charIdx] - 1);
            if (trimStr.contains(currentChar)) {
                searchIdx -= charLens[charIdx];
            } else {
                break;
            }
            charIdx--;
        }
        if (searchIdx < 0) {
            // empty string
            return EMPTY_UTF8;
        } else {
            return str.copyBinaryString(0, searchIdx);
        }
    }

    public static BinaryStringData trim(
            BinaryStringData str, boolean leading, boolean trailing, BinaryStringData seek) {
        str.ensureMaterialized();
        if (seek == null) {
            return null;
        }
        if (leading && trailing) {
            return trim(str, seek);
        } else if (leading) {
            return trimLeft(str, seek);
        } else if (trailing) {
            return trimRight(str, seek);
        } else {
            return str;
        }
    }

    public static String safeToString(BinaryStringData str) {
        if (str == null) {
            return null;
        } else {
            return str.toString();
        }
    }
}

