    public PojoConverter(PojoTypeInfo<T> t, DataType[] fieldTypes) {
        super(fieldTypes);
        this.fields = new PojoField[t.getArity()];
        for (int i = 0; i < t.getArity(); i++) {
            fields[i] = t.getPojoFieldAt(i);
