                .isEqualTo("hello");
        assertThat(BinaryStringDataUtil.trim(bs("xxxx"), bs("x")).toString()).isEmpty();
        assertThat(BinaryStringDataUtil.trim(bs("  hello  "), null)).isNull();

        assertThat(BinaryStringDataUtil.trimLeft(bs("  hello  ")).toString())
                .isEqualTo("hello  ");
        assertThat(BinaryStringDataUtil.trimRight(bs("  hello  ")).toString())
                .isEqualTo("  hello");
        assertThat(BinaryStringDataUtil.trimLeft(bs("xxhelloxx"), bs("x")).toString())
                .isEqualTo("helloxx");
        assertThat(BinaryStringDataUtil.trimRight(bs("xxhelloxx"), bs("x")).toString())
                .isEqualTo("xxhello");
        assertThat(BinaryStringDataUtil.trimLeft(bs("  hello  "), null)).isNull();
        assertThat(BinaryStringDataUtil.trimRight(bs("  hello  "), null)).isNull();
    }

