/** Tests for {@link DataFormatConverters}. */
class DataFormatConvertersTest {

    @SuppressWarnings("unchecked")
    private static <I, E> DataFormatConverter<I, E> converter(DataType dataType) {
        return (DataFormatConverter<I, E>) DataFormatConverters.getConverterForDataType(dataType);
    }

    @Test
    void testResolverReturnsExpectedConvertersForSimpleTypes() {
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.BOOLEAN()))
                .isSameAs(BooleanConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.TINYINT()))
                .isSameAs(ByteConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.SMALLINT()))
                .isSameAs(ShortConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.INT()))
                .isSameAs(IntConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.BIGINT()))
                .isSameAs(LongConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.FLOAT()))
                .isSameAs(FloatConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.DOUBLE()))
                .isSameAs(DoubleConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.STRING()))
                .isSameAs(StringConverter.INSTANCE);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.STRING().bridgedTo(StringData.class)))
                .isSameAs(StringDataConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.BINARY(10)))
                .isSameAs(PrimitiveByteArrayConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.VARBINARY(10)))
                .isSameAs(PrimitiveByteArrayConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.DATE()))
                .isSameAs(LocalDateConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.TIME()))
                .isSameAs(LocalTimeConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.TIMESTAMP(3)))
                .isInstanceOf(LocalDateTimeConverter.class);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.TIMESTAMP_LTZ(3)))
                .isInstanceOf(InstantConverter.class);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.BITMAP()))
                .isSameAs(BitmapConverter.INSTANCE);
    }

    @Test
    void testResolverForLegacyJavaTypes() {
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.DATE().bridgedTo(java.sql.Date.class)))
                .isSameAs(DateConverter.INSTANCE);
        assertThat(DataFormatConverters.getConverterForDataType(DataTypes.DATE().bridgedTo(Integer.class)))
                .isSameAs(IntConverter.INSTANCE);
        assertThat(
                        DataFormatConverters.getConverterForDataType(
                                DataTypes.TIMESTAMP(3).bridgedTo(Timestamp.class)))
