    }

    @Test
    void testStringConversion() {
        DataFormatConverter<StringData, String> converter =
                converter(DataTypes.STRING());

        StringData internal = converter.toInternal("hello");
        assertThat(internal.toString()).isEqualTo("hello");
        assertThat(converter.toExternal(internal)).isEqualTo("hello");

        GenericRowData row = GenericRowData.of(internal);
        assertThat(converter.toExternal(row, 0)).isEqualTo("hello");

        assertThat(converter.toInternal(null)).isNull();
        assertThat(converter.toExternal((String) null)).isNull();
        assertThat(converter.toExternal(GenericRowData.of((Object) null), 0)).isNull();
    }

    @Test
    void testDecimalConversion() {
        DataFormatConverter<DecimalData, BigDecimal> converter =
                converter(DataTypes.DECIMAL(5, 2));

        BigDecimal value = new BigDecimal("1.23");
        DecimalData internal = converter.toInternal(value);
        assertThat(internal.toBigDecimal()).isEqualByComparingTo("1.23");
        assertThat(converter.toExternal(internal)).isEqualByComparingTo("1.23");

        GenericRowData row = GenericRowData.of(internal);
        assertThat(converter.toExternal(row, 0)).isEqualByComparingTo("1.23");
        assertThat(converter.toInternal(null)).isNull();
        assertThat(converter.toExternal((BigDecimal) null)).isNull();
    }

