boolean addMeasureExpr(SqlNode expr) {
    if (isMeasureExpr(expr)) {
        return false; // already present
    }
    measureExprs.add(expr);
    String name = nameMap.get(expr.toString());
    RexNode convExpr = bb.convertExpression(expr);
