import org.apache.calcite.sql.validate.SqlValidatorUtil;
import org.apache.calcite.sql2rel.SqlToRelConverter;
import org.apache.calcite.sql2rel.StandardConvertletTable;
import org.apache.calcite.tools.Frameworks;
import java.util.Collections;
import java.util.List;

public class Probe4 {
  static class T extends AbstractTable {
    private final String[] cols; private final SqlTypeName[] types;
    T(String[] cols, SqlTypeName[] types) { this.cols=cols; this.types=types; }
    @Override public RelDataType getRowType(RelDataTypeFactory tf) {
      RelDataTypeFactory.Builder b = tf.builder();
      for (int i=0;i<cols.length;i++) b.add(cols[i], types[i]);
      return b.build();
    }
  }
  static class H {
    RelDataTypeFactory tf;
    CalciteCatalogReader reader;
    SqlValidator validator;
    RelOptCluster cluster;
    SqlToRelConverter converter;
    H() {
      SchemaPlus root = Frameworks.createRootSchema(true);
      root.add("EMP", new T(new String[]{"EMPNO","ENAME","DEPTNO"}, new SqlTypeName[]{SqlTypeName.INTEGER, SqlTypeName.VARCHAR, SqlTypeName.INTEGER}));
      root.add("DEPT", new T(new String[]{"DEPTNO","DNAME"}, new SqlTypeName[]{SqlTypeName.INTEGER, SqlTypeName.VARCHAR}));
      tf = new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
      reader = new CalciteCatalogReader(CalciteSchema.from(root), Collections.emptyList(), tf, CalciteConnectionConfig.DEFAULT);
      validator = SqlValidatorUtil.newValidator(SqlStdOperatorTable.instance(), reader, tf);
      cluster = RelOptCluster.create(new VolcanoPlanner(), new RexBuilder(tf));
      RelOptTable.ViewExpander ve = new RelOptTable.ViewExpander() {
        public RelRoot expandView(RelDataType rowType, String queryString, List<String> schemaPath, List<String> viewPath) { return null; }
      };
      converter = new SqlToRelConverter(ve, validator, reader, cluster, StandardConvertletTable.INSTANCE, SqlToRelConverter.config());
    }
    SqlNode parse(String sql) { try { return SqlParser.create(sql).parseQuery(); } catch (Exception e) { throw new RuntimeException(e); } }
  }
  public static void main(String[] args) throws Exception {
    H h = new H();
    SqlNode n = h.parse("select EMPNO, ENAME from EMP where DEPTNO = ? order by EMPNO");
    SqlNode v = h.validator.validate(n);
    RelRoot root = h.converter.convertQuery(v, false, true);
    System.out.println(RelOptUtil.toString(root.rel));
    System.out.println("dyn="+h.converter.getDynamicParamCount()+" type="+h.converter.getDynamicParamType(0));
    System.out.println("FIELDS="+root.fields+" collation="+root.collation);
    SqlNode expr = h.parse("EMPNO + 1");
    RexNode rex = h.converter.convertExpression(expr);
    System.out.println("REX="+rex+" type="+rex.getType());
  }
}
