import org.apache.calcite.plan.RelOptUtil;
import org.apache.calcite.rel.RelNode;
import org.apache.calcite.rel.core.Correlate;
import org.apache.calcite.rel.core.JoinRelType;
import org.apache.calcite.rex.RexCorrelVariable;
import org.apache.calcite.rex.RexNode;
import org.apache.calcite.sql2rel.RelDecorrelator;
import org.apache.calcite.tools.RelBuilder;
import org.apache.calcite.util.Holder;
import java.util.ArrayList;
import java.util.List;

public class Probe5 extends Probe3 {
  public static void main(String[] args) throws Exception {
    // scalar aggregate correlated plan
    RelBuilder b = newBuilder();
    b.scan("EMP").as("e");
    Holder<RexCorrelVariable> h = Holder.of(null);
    b.variable(h::set);
    RexCorrelVariable cor = h.get();
    b.scan("DEPT").as("d")
      .filter(b.equals(b.field("DEPTNO"), b.getRexBuilder().makeFieldAccess(cor, 2)))
      .aggregate(b.groupKey(), b.count(false, "C"));
    System.out.println("right fields: "+b.peek().getRowType());
    b.correlate(JoinRelType.LEFT, cor.id, b.literal(true));
    System.out.println("after corr fields: "+b.peek().getRowType());
    b.project(b.field("e","ENAME"), b.field(2));
    RelNode rel = b.build();
    System.out.println("BEFORE:\n"+RelOptUtil.toString(rel));
    RelNode out = RelDecorrelator.decorrelateQuery(rel, newBuilder());
    System.out.println("AFTER:\n"+RelOptUtil.toString(out));
    System.out.println("hasCorrelate="+hasCorrelate(rel)+" after="+hasCorrelate(out));
    RelDecorrelator.CorelMap map = new RelDecorrelator.CorelMapBuilder().build(rel);
    System.out.println("map has="+map.hasCorrelation()+" size="+map.getMapCorToCorRel().size());
  }
  static boolean hasCorrelate(RelNode n) {
    if (n instanceof Correlate) return true;
    for (RelNode i : n.getInputs()) if (hasCorrelate(i)) return true;
    return false;
  }
}
