    final RelDataTypeFactory typeFactory;
    final CalciteCatalogReader catalogReader;
    final SqlValidator validator;
    final RelOptCluster cluster;
    final SqlToRelConverter converter;

    Sql2RelTestSupport() {
        this(SqlToRelConverter.config());
    }

    Sql2RelTestSupport(SqlToRelConverter.Config config) {
        this.rootSchema = createSchema();
        this.typeFactory = newTypeFactory();
        this.catalogReader = newCatalogReader(rootSchema, typeFactory);
        this.validator =
                SqlValidatorUtil.newValidator(
                        SqlStdOperatorTable.instance(), catalogReader, typeFactory);
        this.cluster = newCluster(typeFactory);
        final RelOptTable.ViewExpander viewExpander =
                (rowType, queryString, schemaPath, viewPath) -> null;
        this.converter =
                new SqlToRelConverter(
                        viewExpander,
                        validator,
                        catalogReader,
                        cluster,
                        StandardConvertletTable.INSTANCE,
                        config);
    }

    RelRoot convert(String sql) {
        return convert(validate(sql));
    }

    RelRoot convert(SqlNode validatedQuery) {
        return converter.convertQuery(validatedQuery, false, true);
    }

    SqlNode validate(String sql) {
        return validator.validate(parseQuery(sql));
    }

    static SqlNode parseQuery(String sql) {
        try {
            return SqlParser.create(sql).parseQuery();
        } catch (SqlParseException e) {
            throw new IllegalArgumentException("Could not parse query: " + sql, e);
        }
    }

    static SqlNode parseExpression(String expression) {
        try {
            return SqlParser.create(expression).parseExpression();
        } catch (SqlParseException e) {
            throw new IllegalArgumentException("Could not parse expression: " + expression, e);
        }
    }

    static RelBuilder newRelBuilder() {
        final SchemaPlus root = createSchema();
        final RelDataTypeFactory typeFactory = newTypeFactory();
        final CalciteCatalogReader catalogReader = newCatalogReader(root, typeFactory);
        return RelFactories.LOGICAL_BUILDER.create(newCluster(typeFactory), catalogReader);
    }

    static SchemaPlus createSchema() {
        final SchemaPlus root = Frameworks.createRootSchema(true);
        root.add(
                EMP,
                new TestTable(
                        Arrays.asList("EMPNO", "ENAME", "DEPTNO", "SAL"),
                        Arrays.asList(
                                SqlTypeName.INTEGER,
                                SqlTypeName.VARCHAR,
                                SqlTypeName.INTEGER,
                                SqlTypeName.INTEGER)));
        root.add(
                DEPT,
                new TestTable(
                        Arrays.asList("DEPTNO", "DNAME"),
                        Arrays.asList(SqlTypeName.INTEGER, SqlTypeName.VARCHAR)));
        return root;
    }

    static RelDataTypeFactory newTypeFactory() {
        return new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT);
    }

    static CalciteCatalogReader newCatalogReader(
            SchemaPlus rootSchema, RelDataTypeFactory typeFactory) {
        return new CalciteCatalogReader(
                CalciteSchema.from(rootSchema),
                Collections.emptyList(),
                typeFactory,
                CalciteConnectionConfig.DEFAULT);
    }

    static RelOptCluster newCluster(RelDataTypeFactory typeFactory) {
        return RelOptCluster.create(new VolcanoPlanner(), new RexBuilder(typeFactory));
    }

    static boolean containsCorrelate(RelNode node) {
        if (node instanceof Correlate) {
            return true;
        }
        for (RelNode input : node.getInputs()) {
            if (containsCorrelate(input)) {
                return true;
            }
        }
        return false;
    }

    static <T extends RelNode> T find(RelNode root, Class<T> type) {
        if (type.isInstance(root)) {
            return type.cast(root);
        }
        for (RelNode input : root.getInputs()) {
            final T result = find(input, type);
            if (result != null) {
                return result;
            }
        }
        return null;
    }

    private static final class TestTable extends AbstractTable {
        private final List<String> fieldNames;
        private final List<SqlTypeName> fieldTypes;

        TestTable(List<String> fieldNames, List<SqlTypeName> fieldTypes) {
            this.fieldNames = fieldNames;
            this.fieldTypes = fieldTypes;
        }

        @Override
        public RelDataType getRowType(RelDataTypeFactory typeFactory) {
            final RelDataTypeFactory.Builder builder = typeFactory.builder();
            for (int i = 0; i < fieldNames.size(); i++) {
                builder.add(fieldNames.get(i), fieldTypes.get(i));
            }
            return builder.build();
        }
    }
}
