import org.apache.calcite.sql.SqlFunction;
import org.apache.calcite.sql.fun.SqlStdOperatorTable;
import org.apache.calcite.sql.type.SqlTypeFactoryImpl;
import org.apache.calcite.sql.type.SqlTypeName;

import org.apache.flink.table.planner.functions.sql.FlinkSqlOperatorTable;
import org.junit.jupiter.api.Test;

import java.math.BigDecimal;

import static org.assertj.core.api.Assertions.assertThat;

/** Tests for {@link AuxiliaryConverter}. */
class AuxiliaryConverterTest {

    private final RexBuilder rexBuilder =
            new RexBuilder(new SqlTypeFactoryImpl(RelDataTypeSystem.DEFAULT));

    private RexNode timestampInput() {
        final RelDataType timestampType =
                rexBuilder.getTypeFactory().createSqlType(SqlTypeName.TIMESTAMP);
        return rexBuilder.makeInputRef(timestampType, 0);
    }

    @Test
    void implWrapsExpressionInConfiguredFunction() {
        final RexNode expression = timestampInput();
        final AuxiliaryConverter converter =
                new AuxiliaryConverter.Impl(SqlStdOperatorTable.TUMBLE_START);

        final RexNode result = converter.convert(rexBuilder, expression, expression);

        assertThat(result).isInstanceOf(RexCall.class);
        final RexCall call = (RexCall) result;
        assertThat(call.getOperator()).isSameAs(SqlStdOperatorTable.TUMBLE_START);
        assertThat(call.getKind()).isEqualTo(SqlStdOperatorTable.TUMBLE_START.getKind());
        assertThat(call.getOperands()).containsExactly(expression);
        assertThat(call.getType()).isEqualTo(expression.getType());
    }

    @Test
    void implUsesTheExpressionAndNotTheOriginalGroupCall() {
        final RexNode expression = timestampInput();
        final AuxiliaryConverter converter =
                new AuxiliaryConverter.Impl(SqlStdOperatorTable.TUMBLE_END);
        final RexNode unrelatedGroupCall = rexBuilder.makeExactLiteral(BigDecimal.ONE);

        final RexNode result = converter.convert(rexBuilder, unrelatedGroupCall, expression);

        final RexCall call = (RexCall) result;
        assertThat(call.getOperator()).isSameAs(SqlStdOperatorTable.TUMBLE_END);
        assertThat(call.getOperands()).containsExactly(expression);
    }

    @Test
    void implSupportsFlinkSpecificRowTimeAuxiliaryFunction() {
        final RexNode expression = timestampInput();
        final SqlFunction rowTimeFunction = FlinkSqlOperatorTable.TUMBLE_ROWTIME;
        final AuxiliaryConverter converter = new AuxiliaryConverter.Impl(rowTimeFunction);

        final RexNode result = converter.convert(rexBuilder, expression, expression);

        assertThat(result).isInstanceOf(RexCall.class);
        final RexCall call = (RexCall) result;
        assertThat(call.getOperator()).isSameAs(rowTimeFunction);
        assertThat(call.getOperator().getName()).isEqualTo("TUMBLE_ROWTIME");
        assertThat(call.getOperands()).containsExactly(expression);
    }
}
