    private final RexBuilder rexBuilder =
            new RexBuilder(Sql2RelTestSupport.newTypeFactory());

    private SqlToRelConverter.Blackboard newBlackboard() {
        final SqlToRelConverter.Blackboard blackboard =
                mock(SqlToRelConverter.Blackboard.class);
        blackboard.root = scan;
        when(blackboard.root()).thenReturn(scan);
        when(blackboard.getRexBuilder()).thenReturn(rexBuilder);
        return blackboard;
    }

    private RexNode inputRef(int index) {
        return rexBuilder.makeInputRef(
                scan.getRowType().getFieldList().get(index).getType(), index);
    }

    @Test
    void newlyCreatedConverterHasEmptyState() {
        final AggConverter converter = AggConverter.create(newBlackboard());

        assertThat(converter.groupExprs).isEmpty();
        assertThat(converter.aggCalls).isEmpty();
        assertThat(converter.convertedInputExprs).isEmpty();
        assertThat(converter.lookupMeasure(Sql2RelTestSupport.parseExpression("DEPTNO")))
                .isNull();
        assertThat(converter.lookupGroupExpr(Sql2RelTestSupport.parseExpression("DEPTNO")))
                .isEqualTo(-1);
    }

    @Test
    void addGroupExprDeduplicatesStructurallyEqualExpressions() {
        final SqlToRelConverter.Blackboard blackboard = newBlackboard();
        when(blackboard.convertExpression(any(SqlNode.class))).thenReturn(inputRef(0));
        final AggConverter converter = AggConverter.create(blackboard);

        final SqlNode groupExpr = Sql2RelTestSupport.parseExpression("DEPTNO");
        final SqlNode equivalentGroupExpr = Sql2RelTestSupport.parseExpression("DEPTNO");

        assertThat(converter.addGroupExpr(groupExpr)).isZero();
        assertThat(converter.addGroupExpr(equivalentGroupExpr)).isZero();

        assertThat(converter.groupExprs).hasSize(1);
        assertThat(converter.convertedInputExprs).hasSize(1);
        verify(blackboard, times(1)).convertExpression(any(SqlNode.class));
        assertThat(converter.lookupGroupExpr(groupExpr)).isZero();
        assertThat(converter.lookupGroupExpr(Sql2RelTestSupport.parseExpression("SAL")))
                .isEqualTo(-1);
    }

    @Test
    void addGroupExprAssignsSequentialIndexesAndDerivesInputNames() {
        final SqlToRelConverter.Blackboard blackboard = newBlackboard();
        when(blackboard.convertExpression(any(SqlNode.class)))
                .thenAnswer(
                        invocation -> {
                            final SqlNode node = invocation.getArgument(0);
                            return node.toString().equals("EMPNO")
                                    ? inputRef(1)
                                    : inputRef(0);
                        });
        final AggConverter converter = AggConverter.create(blackboard);

        assertThat(converter.addGroupExpr(Sql2RelTestSupport.parseExpression("DEPTNO")))
                .isZero();
        assertThat(converter.addGroupExpr(Sql2RelTestSupport.parseExpression("EMPNO")))
                .isEqualTo(1);

        assertThat(converter.groupExprs).hasSize(2);
        assertThat(converter.convertedInputExprs.leftList())
                .extracting(RexNode::toString)
                .containsExactly("$0", "$1");
        assertThat(converter.convertedInputExprs.rightList())
                .containsExactly("DEPTNO", "EMPNO");
    }

    @Test
    void lookupAggregatesUsesFirstRegisteredAuxiliaryConverter() {
        final SqlToRelConverter.Blackboard blackboard = newBlackboard();
        when(blackboard.convertExpression(any(SqlNode.class))).thenReturn(inputRef(0));
        final AggConverter converter = AggConverter.create(blackboard);
        converter.addGroupExpr(Sql2RelTestSupport.parseExpression("DEPTNO"));
        blackboard.agg = converter;

        final SqlNode auxiliaryCall = Sql2RelTestSupport.parseExpression("F(DEPTNO)");
        final AuxiliaryConverter first = mock(AuxiliaryConverter.class);
        final AuxiliaryConverter second = mock(AuxiliaryConverter.class);
        final RexNode expected = rexBuilder.makeExactLiteral(BigDecimal.ONE);
        when(first.convert(any(), any(), any())).thenReturn(expected);

        converter.addAuxiliaryGroupExpr(auxiliaryCall, 0, first);
        converter.addAuxiliaryGroupExpr(
                Sql2RelTestSupport.parseExpression("F(DEPTNO)"), 0, second);

        final RexNode result = converter.lookupAggregates((SqlCall) auxiliaryCall);

        assertThat(result).isSameAs(expected);
        verify(first, times(1))
                .convert(
                        eq(rexBuilder),
                        argThat(node -> node.equals(converter.convertedInputExprs.left(0))),
                        argThat(
                                node ->
                                        node instanceof RexInputRef
                                                && ((RexInputRef) node).getIndex() == 0));
        verify(second, never()).convert(any(), any(), any());
    }

    @Test
    void lookupAggregatesReturnsNullForUnknownCall() {
        final SqlToRelConverter.Blackboard blackboard = newBlackboard();
        when(blackboard.convertExpression(any(SqlNode.class))).thenReturn(inputRef(0));
        final AggConverter converter = AggConverter.create(blackboard);
        converter.addGroupExpr(Sql2RelTestSupport.parseExpression("DEPTNO"));
        blackboard.agg = converter;

        assertThat(
                        converter.lookupAggregates(
                                (SqlCall)
                                        Sql2RelTestSupport.parseExpression(
                                                "UNKNOWN(DEPTNO)")))
                .isNull();
    }

    @Test
    void pivotConverterDoesNotSupportResolvedMeasureScope() {
        final AggConverter converter = AggConverter.create(newBlackboard());
        final SqlNode expression = Sql2RelTestSupport.parseExpression("DEPTNO");

        assertThatThrownBy(converter::getResolved)
                .isInstanceOf(UnsupportedOperationException.class);
        assertThatThrownBy(() -> converter.addMeasureExpr(expression))
                .isInstanceOf(UnsupportedOperationException.class);
    }

    @Test
    void inferredInputTypeIsAvailableForConvertedGroupExpressions() {
        final SqlToRelConverter.Blackboard blackboard = newBlackboard();
        when(blackboard.convertExpression(any(SqlNode.class))).thenReturn(inputRef(0));
        final AggConverter converter = AggConverter.create(blackboard);

        converter.addGroupExpr(Sql2RelTestSupport.parseExpression("DEPTNO"));

        assertThat(converter.convertedInputExprs.left(0).getType().getSqlTypeName())
                .isEqualTo(SqlTypeName.INTEGER);
    }
}
