 * HADOOP_CLASSPATH} is not set.
 */
@Internal
public class FallbackYarnSessionCli extends AbstractYarnCli {

    public FallbackYarnSessionCli(Configuration configuration) {
        super(configuration, "y", "yarn");
    }

    @Override
