import org.apache.flink.yarn.executors.YarnSessionClusterExecutor;

import org.apache.commons.cli.CommandLine;
import org.apache.commons.cli.Options;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

/** Tests for the common YARN command line behavior. */
class AbstractYarnCliTest {

    private static final String APPLICATION_ID = "application_1234567890000_0001";

    @Test
    void testIdIsYarnCluster() {
        final TestYarnCli yarnCli = new TestYarnCli(new Configuration());

        assertThat(yarnCli.getId()).isEqualTo(AbstractYarnCli.ID).isEqualTo("yarn-cluster");
    }

    @Test
    void testGeneralOptionsContainYarnApplicationAndAddressOptions() {
        final Options options = new Options();
        final TestYarnCli yarnCli = new TestYarnCli(new Configuration());

        yarnCli.addGeneralOptions(options);

        assertThat(options.getOption("yid")).isNotNull();
        assertThat(options.getOption("yid").getLongOpt()).isEqualTo("yarnapplicationId");
        assertThat(options.getOption("m")).isNotNull();
        assertThat(options.getOption("m").getLongOpt()).isEqualTo("jobmanager");
        assertThat(options.getOption("z")).isNotNull();
    }

    @Test
    void testIsActiveWhenYarnClusterIsSelectedAsJobManager() throws CliArgsException {
        final TestYarnCli yarnCli = new TestYarnCli(new Configuration());

        assertThat(yarnCli.isActive(yarnCli.parseCommandLineOptions(
                        new String[] {"--jobmanager", AbstractYarnCli.ID}, true)))
                .isTrue();
    }

    @Test
    void testIsActiveWhenApplicationIdIsGivenOnCommandLine() throws CliArgsException {
        final TestYarnCli yarnCli = new TestYarnCli(new Configuration());

        assertThat(yarnCli.isActive(yarnCli.parseCommandLineOptions(
                        new String[] {"--yarnapplicationId", APPLICATION_ID}, true)))
                .isTrue();
    }

    @Test
    void testIsActiveWhenApplicationIdIsConfigured() throws CliArgsException {
        final Configuration configuration = new Configuration();
        configuration.set(YarnConfigOptions.APPLICATION_ID, APPLICATION_ID);
        final TestYarnCli yarnCli = new TestYarnCli(configuration);

        assertThat(yarnCli.isActive(yarnCli.parseCommandLineOptions(new String[0], true)))
                .isTrue();
    }

    @Test
    void testIsActiveWhenYarnSessionExecutorIsConfiguredCaseInsensitively()
            throws CliArgsException {
        final Configuration configuration = new Configuration();
        configuration.set(DeploymentOptions.TARGET, YarnSessionClusterExecutor.NAME.toUpperCase());
        final TestYarnCli yarnCli = new TestYarnCli(configuration);

        assertThat(yarnCli.isActive(yarnCli.parseCommandLineOptions(new String[0], true)))
                .isTrue();
    }

    @Test
    void testIsNotActiveWhenNoYarnInformationIsProvided() throws CliArgsException {
        final TestYarnCli yarnCli = new TestYarnCli(new Configuration());

        assertThat(yarnCli.isActive(yarnCli.parseCommandLineOptions(new String[0], true)))
                .isFalse();
    }

    @Test
    void testIsNotActiveForUnrelatedJobManagerAndDeploymentTarget() throws CliArgsException {
        final Configuration configuration = new Configuration();
        configuration.set(DeploymentOptions.TARGET, "yarn-application");
        final TestYarnCli yarnCli = new TestYarnCli(configuration);

        assertThat(yarnCli.isActive(yarnCli.parseCommandLineOptions(
                        new String[] {"--jobmanager", "localhost:6123"}, true)))
                .isFalse();
    }

    /** Minimal concrete subclass used to exercise the package-private base class. */
    private static final class TestYarnCli extends AbstractYarnCli {

        private TestYarnCli(Configuration configuration) {
            super(configuration, "y", "yarn");
        }
    }
}
