import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

/** Tests for {@link YarnApplicationStatusMonitor}. */
class YarnApplicationStatusMonitorTest {

    private static final ApplicationId APPLICATION_ID =
            ApplicationId.fromString("application_1234567890000_0003");

    private YarnClient yarnClient;
    private ScheduledExecutor scheduledExecutor;
    private ScheduledFuture<?> scheduledFuture;

    @BeforeEach
    void setUp() {
        yarnClient = mock(YarnClient.class);
        scheduledExecutor = mock(ScheduledExecutor.class);
        scheduledFuture = mock(ScheduledFuture.class);
        when(scheduledExecutor.scheduleWithFixedDelay(
                        any(Runnable.class), anyLong(), anyLong(), any(TimeUnit.class)))
                .thenReturn(scheduledFuture);
    }

    @Test
    void testInitialStatusIsUnknownAndPollingIsScheduled() {
        final YarnApplicationStatusMonitor monitor =
                new YarnApplicationStatusMonitor(yarnClient, APPLICATION_ID, scheduledExecutor);

        assertThat(monitor.getApplicationStatusNow()).isEqualTo(ApplicationStatus.UNKNOWN);
        verifyNoInteractions(scheduledFuture);

        final ArgumentCaptor<Runnable> updateTask = ArgumentCaptor.forClass(Runnable.class);
        verify(scheduledExecutor)
                .scheduleWithFixedDelay(
                        updateTask.capture(), eq(0L), eq(1000L), eq(TimeUnit.MILLISECONDS));
        assertThat(updateTask.getValue()).isNotNull();
    }

    @Test
    void testCloseCancelsPolling() {
        final YarnApplicationStatusMonitor monitor =
                new YarnApplicationStatusMonitor(yarnClient, APPLICATION_ID, scheduledExecutor);

        monitor.close();

        verify(scheduledFuture).cancel(false);
    }

    @ParameterizedTest
    @EnumSource(
            value = YarnApplicationState.class,
            names = {"FAILED", "KILLED"})
    void testFailedAndKilledApplicationStatesBecomeFailed(YarnApplicationState state)
            throws Exception {
        final ApplicationReport report = mock(ApplicationReport.class);
        when(report.getYarnApplicationState()).thenReturn(state);
        when(yarnClient.isInState(Service.STATE.STARTED)).thenReturn(true);
        when(yarnClient.getApplicationReport(APPLICATION_ID)).thenReturn(report);

        final YarnApplicationStatusMonitor monitor =
                new YarnApplicationStatusMonitor(yarnClient, APPLICATION_ID, scheduledExecutor);
        getPollingTask().run();

        assertThat(monitor.getApplicationStatusNow()).isEqualTo(ApplicationStatus.FAILED);
        verify(yarnClient).getApplicationReport(APPLICATION_ID);
    }

    @ParameterizedTest
    @EnumSource(
            value = YarnApplicationState.class,
            names = {"FAILED", "KILLED"},
            mode = EnumSource.Mode.EXCLUDE)
    void testAllOtherApplicationStatesBecomeSucceeded(YarnApplicationState state) throws Exception {
        final ApplicationReport report = mock(ApplicationReport.class);
        when(report.getYarnApplicationState()).thenReturn(state);
        when(yarnClient.isInState(Service.STATE.STARTED)).thenReturn(true);
        when(yarnClient.getApplicationReport(APPLICATION_ID)).thenReturn(report);

        final YarnApplicationStatusMonitor monitor =
                new YarnApplicationStatusMonitor(yarnClient, APPLICATION_ID, scheduledExecutor);
        getPollingTask().run();

        assertThat(monitor.getApplicationStatusNow()).isEqualTo(ApplicationStatus.SUCCEEDED);
    }

    @Test
    void testReportRetrievalFailureResetsStatusToUnknown() throws Exception {
        final ApplicationReport report = mock(ApplicationReport.class);
        when(report.getYarnApplicationState()).thenReturn(YarnApplicationState.RUNNING);
        when(yarnClient.isInState(Service.STATE.STARTED)).thenReturn(true);
        when(yarnClient.getApplicationReport(APPLICATION_ID))
                .thenReturn(report)
                .thenThrow(new YarnException("temporary failure"));

        final YarnApplicationStatusMonitor monitor =
                new YarnApplicationStatusMonitor(yarnClient, APPLICATION_ID, scheduledExecutor);
        final Runnable pollingTask = getPollingTask();

        pollingTask.run();
        assertThat(monitor.getApplicationStatusNow()).isEqualTo(ApplicationStatus.SUCCEEDED);

        pollingTask.run();
        assertThat(monitor.getApplicationStatusNow()).isEqualTo(ApplicationStatus.UNKNOWN);
    }

    @Test
    void testIoFailureDuringReportRetrievalResetsStatusToUnknown() throws Exception {
        when(yarnClient.isInState(Service.STATE.STARTED)).thenReturn(true);
        when(yarnClient.getApplicationReport(APPLICATION_ID))
                .thenThrow(new IOException("unavailable"));

        final YarnApplicationStatusMonitor monitor =
                new YarnApplicationStatusMonitor(yarnClient, APPLICATION_ID, scheduledExecutor);
        getPollingTask().run();

        assertThat(monitor.getApplicationStatusNow()).isEqualTo(ApplicationStatus.UNKNOWN);
    }

    @Test
    void testPollingIsCancelledWhenYarnClientStops() throws Exception {
        when(yarnClient.isInState(Service.STATE.STARTED)).thenReturn(false);

        final YarnApplicationStatusMonitor monitor =
                new YarnApplicationStatusMonitor(yarnClient, APPLICATION_ID, scheduledExecutor);
        getPollingTask().run();

        assertThat(monitor.getApplicationStatusNow()).isEqualTo(ApplicationStatus.UNKNOWN);
        verify(scheduledFuture).cancel(false);
        verifyNoInteractions(yarnClient);
    }

    @Test
    void testConstructorRejectsNullCollaborators() {
        assertThatNullPointerException()
                .isThrownBy(
                        () ->
                                new YarnApplicationStatusMonitor(
                                        null, APPLICATION_ID, scheduledExecutor));
        assertThatNullPointerException()
                .isThrownBy(
                        () ->
                                new YarnApplicationStatusMonitor(
                                        yarnClient, null, scheduledExecutor));
    }

    private Runnable getPollingTask() {
        final ArgumentCaptor<Runnable> updateTask = ArgumentCaptor.forClass(Runnable.class);
        verify(scheduledExecutor)
                .scheduleWithFixedDelay(
                        updateTask.capture(), eq(0L), eq(1000L), eq(TimeUnit.MILLISECONDS));
        return updateTask.getValue();
    }
}
