    @Test
    void testRunRollsBackDeploymentWhenConnectionInformationCannotBeWritten() throws Exception {
        final java.nio.file.Path missingPropertiesDirectory =
                temporaryDirectory.resolve("missing-directory");
        final Configuration configuration = newConfiguration(missingPropertiesDirectory);
        final ClusterClientServiceLoader serviceLoader = mock(ClusterClientServiceLoader.class);
        final ClusterClientFactory<ApplicationId> factory = mock(ClusterClientFactory.class);
        final YarnClusterDescriptor descriptor = mock(YarnClusterDescriptor.class);
        @SuppressWarnings("unchecked")
        final ClusterClientProvider<ApplicationId> provider = mock(ClusterClientProvider.class);
        @SuppressWarnings("unchecked")
        final ClusterClient<ApplicationId> clusterClient = mock(ClusterClient.class);
        final ClusterSpecification specification =
                new ClusterSpecification.ClusterSpecificationBuilder()
                        .setMasterMemoryMB(1024)
                        .setTaskManagerMemoryMB(2048)
                        .setSlotsPerTaskManager(2)
                        .createClusterSpecification();
        when(serviceLoader.getClusterClientFactory(any(Configuration.class))).thenReturn(factory);
        when(factory.createClusterDescriptor(any(Configuration.class))).thenReturn(descriptor);
        when(factory.getClusterSpecification(any(Configuration.class)))
                .thenReturn(specification);
