                .isInstanceOf(CliArgsException.class);
    }

    private FlinkYarnSessionCli createCli(Configuration configuration) throws FlinkException {
        return new FlinkYarnSessionCli(
                configuration, temporaryDirectory.toString(), "", "", false);
    }

    private FlinkYarnSessionCli createCli(
            Configuration configuration, ClusterClientServiceLoader serviceLoader)
            throws FlinkException {
        return new FlinkYarnSessionCli(
                configuration, serviceLoader, temporaryDirectory.toString(), "", "", false);
    }

    private Configuration newConfiguration(java.nio.file.Path propertiesDirectory) {
        final Configuration configuration = new Configuration();
        configuration.set(
                YarnConfigOptions.PROPERTIES_FILE_LOCATION, propertiesDirectory.toString());
        return configuration;
    }

    private static void writeYarnPropertiesFile(
            java.nio.file.Path propertiesDirectory, String... lines) throws Exception {
        final File propertiesFile =
                FlinkYarnSessionCli.getYarnPropertiesLocation(propertiesDirectory.toString());
        Files.write(propertiesFile.toPath(), Arrays.asList(lines), StandardCharsets.UTF_8);
    }

    private static Properties loadYarnProperties(java.nio.file.Path propertiesDirectory)
            throws Exception {
        final Properties properties = new Properties();
        try (InputStream input =
                new FileInputStream(
                        FlinkYarnSessionCli.getYarnPropertiesLocation(
                                propertiesDirectory.toString()))) {
            properties.load(input);
        }
        return properties;
    }
}
