import java.util.Collections;
import java.util.Deque;
import java.util.concurrent.Callable;
import java.util.concurrent.Delayed;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatNullPointerException;

/** Tests for {@link YarnApplicationStatusMonitor}. */
class YarnApplicationStatusMonitorTest {

    private static final ApplicationId APPLICATION_ID =
            ApplicationId.fromString("application_1234567890000_0003");

    private TestingYarnClient yarnClient;
    private RecordingScheduledExecutor scheduledExecutor;

    @BeforeEach
    void setUp() {
        yarnClient = new TestingYarnClient();
        scheduledExecutor = new RecordingScheduledExecutor();
    }

    @Test
    void testInitialStatusIsUnknownAndPollingIsScheduled() {
        final YarnApplicationStatusMonitor monitor =
                new YarnApplicationStatusMonitor(yarnClient, APPLICATION_ID, scheduledExecutor);

        assertThat(monitor.getApplicationStatusNow()).isEqualTo(ApplicationStatus.UNKNOWN);
        assertThat(scheduledExecutor.command).isNotNull();
        assertThat(scheduledExecutor.initialDelay).isZero();
        assertThat(scheduledExecutor.delay).isEqualTo(1000L);
        assertThat(scheduledExecutor.unit).isEqualTo(TimeUnit.MILLISECONDS);
        assertThat(scheduledExecutor.future.cancelled).isFalse();
    }

    @Test
    void testCloseCancelsPolling() {
        final YarnApplicationStatusMonitor monitor =
                new YarnApplicationStatusMonitor(yarnClient, APPLICATION_ID, scheduledExecutor);

        monitor.close();

        assertThat(scheduledExecutor.future.cancelled).isTrue();
    }

    @ParameterizedTest
    @EnumSource(
            value = YarnApplicationState.class,
            names = {"FAILED", "KILLED"})
    void testFailedAndKilledApplicationStatesBecomeFailed(YarnApplicationState state) {
        yarnClient.start();
        yarnClient.addReport(reportWithState(state));

        final YarnApplicationStatusMonitor monitor =
                new YarnApplicationStatusMonitor(yarnClient, APPLICATION_ID, scheduledExecutor);
        scheduledExecutor.runScheduledTask();

        assertThat(monitor.getApplicationStatusNow()).isEqualTo(ApplicationStatus.FAILED);
        assertThat(yarnClient.reportCalls).isEqualTo(1);
    }

    @ParameterizedTest
    @EnumSource(
            value = YarnApplicationState.class,
            names = {"FAILED", "KILLED"},
            mode = EnumSource.Mode.EXCLUDE)
    void testAllOtherApplicationStatesBecomeSucceeded(YarnApplicationState state) {
        yarnClient.start();
        yarnClient.addReport(reportWithState(state));

        final YarnApplicationStatusMonitor monitor =
                new YarnApplicationStatusMonitor(yarnClient, APPLICATION_ID, scheduledExecutor);
        scheduledExecutor.runScheduledTask();

        assertThat(monitor.getApplicationStatusNow()).isEqualTo(ApplicationStatus.SUCCEEDED);
    }

    @Test
    void testReportRetrievalFailureResetsStatusToUnknown() {
        yarnClient.start();
        yarnClient.addReport(reportWithState(YarnApplicationState.RUNNING));
        yarnClient.addFailure(new YarnException("temporary failure"));

        final YarnApplicationStatusMonitor monitor =
                new YarnApplicationStatusMonitor(yarnClient, APPLICATION_ID, scheduledExecutor);

        scheduledExecutor.runScheduledTask();
        assertThat(monitor.getApplicationStatusNow()).isEqualTo(ApplicationStatus.SUCCEEDED);

        scheduledExecutor.runScheduledTask();
        assertThat(monitor.getApplicationStatusNow()).isEqualTo(ApplicationStatus.UNKNOWN);
    }

    @Test
    void testIoFailureDuringReportRetrievalResetsStatusToUnknown() {
        yarnClient.start();
        yarnClient.addFailure(new IOException("unavailable"));

        final YarnApplicationStatusMonitor monitor =
                new YarnApplicationStatusMonitor(yarnClient, APPLICATION_ID, scheduledExecutor);
        scheduledExecutor.runScheduledTask();

        assertThat(monitor.getApplicationStatusNow()).isEqualTo(ApplicationStatus.UNKNOWN);
    }

    @Test
    void testPollingIsCancelledWhenYarnClientStops() {
        final YarnApplicationStatusMonitor monitor =
                new YarnApplicationStatusMonitor(yarnClient, APPLICATION_ID, scheduledExecutor);
        scheduledExecutor.runScheduledTask();

        assertThat(monitor.getApplicationStatusNow()).isEqualTo(ApplicationStatus.UNKNOWN);
        assertThat(scheduledExecutor.future.cancelled).isTrue();
        assertThat(yarnClient.reportCalls).isZero();
    }

    @Test
    void testConstructorRejectsNullCollaborators() {
        assertThatNullPointerException()
                .isThrownBy(
                        () ->
                                new YarnApplicationStatusMonitor(
                                        null, APPLICATION_ID, scheduledExecutor));
        assertThatNullPointerException()
                .isThrownBy(
                        () ->
                                new YarnApplicationStatusMonitor(
                                        yarnClient, null, scheduledExecutor));
    }

    private static ApplicationReport reportWithState(YarnApplicationState state) {
        return ApplicationReport.newInstance(
                APPLICATION_ID,
                null,
                "user",
                "default",
                "application",
                "localhost",
                0,
                null,
                state,
                "",
                "",
                0L,
                0L,
                FinalApplicationStatus.UNDEFINED,
                null,
                "test",
                0.0f,
                Collections.emptySet(),
                null,
                false,
                null,
                null,
                null);
    }

    /** Test YARN client which only implements report retrieval and has no network dependency. */
    private static final class TestingYarnClient extends YarnClientImpl {

        private final Deque<Object> reportResults = new ArrayDeque<>();
        private int reportCalls;

        private TestingYarnClient() {
            super("testing-yarn-client");
        }

        @Override
        protected void serviceInit(org.apache.hadoop.conf.Configuration conf) {}

        @Override
        protected void serviceStart() {}

        private void addReport(ApplicationReport report) {
            reportResults.addLast(report);
        }

        private void addFailure(Exception failure) {
            reportResults.addLast(failure);
        }

        @Override
        public ApplicationReport getApplicationReport(ApplicationId applicationId)
                throws YarnException, IOException {
            reportCalls++;
            final Object result = reportResults.removeFirst();
            if (result instanceof ApplicationReport) {
                return (ApplicationReport) result;
            } else if (result instanceof YarnException) {
                throw (YarnException) result;
            } else if (result instanceof IOException) {
                throw (IOException) result;
            }
            throw new AssertionError("Unexpected report result: " + result);
        }
    }

    /** Minimal scheduled executor which records and exposes the submitted polling task. */
    private static final class RecordingScheduledExecutor implements ScheduledExecutor {

        private final RecordingScheduledFuture future = new RecordingScheduledFuture();
        private Runnable command;
        private long initialDelay;
        private long delay;
        private TimeUnit unit;

        private void runScheduledTask() {
            command.run();
        }

        @Override
        public void execute(Runnable command) {
            command.run();
        }

        @Override
        public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit) {
            throw new UnsupportedOperationException();
        }

        @Override
        public <V> ScheduledFuture<V> schedule(
                Callable<V> callable, long delay, TimeUnit unit) {
            throw new UnsupportedOperationException();
        }

        @Override
        public ScheduledFuture<?> scheduleAtFixedRate(
                Runnable command, long initialDelay, long period, TimeUnit unit) {
            throw new UnsupportedOperationException();
        }

        @Override
        public ScheduledFuture<?> scheduleWithFixedDelay(
                Runnable command, long initialDelay, long delay, TimeUnit unit) {
            this.command = command;
            this.initialDelay = initialDelay;
            this.delay = delay;
            this.unit = unit;
            return future;
        }
    }

    /** Simple future whose cancellation state can be asserted by the tests. */
    private static final class RecordingScheduledFuture implements ScheduledFuture<Object> {

        private boolean cancelled;

        @Override
        public long getDelay(TimeUnit unit) {
            return 0L;
        }

        @Override
        public int compareTo(Delayed other) {
            return 0;
        }

        @Override
        public boolean cancel(boolean mayInterruptIfRunning) {
            cancelled = true;
            return true;
        }

        @Override
        public boolean isCancelled() {
            return cancelled;
        }

        @Override
        public boolean isDone() {
            return cancelled;
        }

        @Override
        public Object get() {
            throw new UnsupportedOperationException();
        }

        @Override
        public Object get(long timeout, TimeUnit unit) {
            throw new UnsupportedOperationException();
        }
    }
}
