    verifyNoInteractions(serviceLoader);
}

@Test
void testRunWithQueryPrintsDescriptionAndClosesDescriptor() throws Exception {
    final ClusterClientServiceLoader serviceLoader = mock(ClusterClientServiceLoader.class);
    final ClusterClientFactory<ApplicationId> factory = mock(ClusterClientFactory.class);
    final YarnClusterDescriptor descriptor = mock(YarnClusterDescriptor.class);
    when(serviceLoader.<ApplicationId>getClusterClientFactory(any(Configuration.class)))
            .thenReturn(factory);
    when(factory.createClusterDescriptor(any(Configuration.class))).thenReturn(descriptor);
    when(descriptor.getClusterDescription()).thenReturn("available YARN resources");

    final FlinkYarnSessionCli cli =
            createCli(newConfiguration(temporaryDirectory), serviceLoader);

    assertThat(cli.run(new String[] {"--query"})).isZero();
    verify(descriptor).getClusterDescription();
    verify(descriptor).close();
    verify(descriptor, never()).deploySessionCluster(any());
}

@Test
void testRunWithApplicationIdRetrievesExistingClusterInDetachedMode() throws Exception {
    final ClusterClientServiceLoader serviceLoader = mock(ClusterClientServiceLoader.class);
    final ClusterClientFactory<ApplicationId> factory = mock(ClusterClientFactory.class);
    final YarnClusterDescriptor descriptor = mock(YarnClusterDescriptor.class);
    @SuppressWarnings("unchecked")
    final ClusterClientProvider<ApplicationId> provider = mock(ClusterClientProvider.class);
    when(serviceLoader.<ApplicationId>getClusterClientFactory(any(Configuration.class)))
            .thenReturn(factory);
    when(factory.createClusterDescriptor(any(Configuration.class))).thenReturn(descriptor);
