    assertThat(returnCode).isZero();
    verify(descriptor).retrieve(APPLICATION_ID);
    verify(descriptor, never()).deploySessionCluster(any());
    verify(descriptor).close();
}

@Test
void testRunDeploysSessionAndWritesConnectionInformation() throws Exception {
    final ClusterClientServiceLoader serviceLoader = mock(ClusterClientServiceLoader.class);
    final ClusterClientFactory<ApplicationId> factory = mock(ClusterClientFactory.class);
    final YarnClusterDescriptor descriptor = mock(YarnClusterDescriptor.class);
    @SuppressWarnings("unchecked")
    final ClusterClientProvider<ApplicationId> provider = mock(ClusterClientProvider.class);
    @SuppressWarnings("unchecked")
    final ClusterClient<ApplicationId> clusterClient = mock(ClusterClient.class);
    final ClusterSpecification specification =
            new ClusterSpecification.ClusterSpecificationBuilder()
                    .setMasterMemoryMB(1024)
                    .setTaskManagerMemoryMB(2048)
                    .setSlotsPerTaskManager(2)
                    .createClusterSpecification();
    when(serviceLoader.<ApplicationId>getClusterClientFactory(any(Configuration.class)))
            .thenReturn(factory);
    when(factory.createClusterDescriptor(any(Configuration.class))).thenReturn(descriptor);
    when(factory.getClusterSpecification(any(Configuration.class))).thenReturn(specification);
    when(descriptor.deploySessionCluster(specification)).thenReturn(provider);
    when(provider.getClusterClient()).thenReturn(clusterClient);
    when(clusterClient.getClusterId()).thenReturn(APPLICATION_ID);
    when(clusterClient.getWebInterfaceURL()).thenReturn("http://jobmanager:8081");

    final FlinkYarnSessionCli cli =
            createCli(newConfiguration(temporaryDirectory), serviceLoader);

    final int returnCode = cli.run(new String[] {"--detached", "-Dcustom.option=value"});

    assertThat(returnCode).isZero();
    verify(descriptor).deploySessionCluster(specification);
    verify(descriptor).close();

    final Properties properties = loadYarnProperties(temporaryDirectory);
    assertThat(properties.getProperty("applicationID")).isEqualTo(APPLICATION_ID_STRING);
    assertThat(properties.getProperty("dynamicPropertiesString"))
            .isEqualTo("custom.option=value");
}

@Test
void testRunRollsBackDeploymentWhenConnectionInformationCannotBeWritten() throws Exception {
    final java.nio.file.Path missingPropertiesDirectory =
            temporaryDirectory.resolve("missing-directory");
    final Configuration configuration = newConfiguration(missingPropertiesDirectory);
    final ClusterClientServiceLoader serviceLoader = mock(ClusterClientServiceLoader.class);
    final ClusterClientFactory<ApplicationId> factory = mock(ClusterClientFactory.class);
    final YarnClusterDescriptor descriptor = mock(YarnClusterDescriptor.class);
    @SuppressWarnings("unchecked")
    final ClusterClientProvider<ApplicationId> provider = mock(ClusterClientProvider.class);
    @SuppressWarnings("unchecked")
    final ClusterClient<ApplicationId> clusterClient = mock(ClusterClient.class);
    final ClusterSpecification specification =
            new ClusterSpecification.ClusterSpecificationBuilder()
                    .setMasterMemoryMB(1024)
                    .setTaskManagerMemoryMB(2048)
                    .setSlotsPerTaskManager(2)
                    .createClusterSpecification();
    when(serviceLoader.<ApplicationId>getClusterClientFactory(any(Configuration.class)))
            .thenReturn(factory);
    when(factory.createClusterDescriptor(any(Configuration.class))).thenReturn(descriptor);
    when(factory.getClusterSpecification(any(Configuration.class))).thenReturn(specification);
    when(descriptor.deploySessionCluster(specification)).thenReturn(provider);
    when(provider.getClusterClient()).thenReturn(clusterClient);
    when(clusterClient.getClusterId()).thenReturn(APPLICATION_ID);

    final FlinkYarnSessionCli cli = createCli(configuration, serviceLoader);

    assertThatThrownBy(() -> cli.run(new String[] {"--detached"}))
            .isInstanceOf(FlinkException.class)
            .hasMessageContaining("Could not write the Yarn connection information");

    verify(clusterClient).close();
    verify(descriptor).killCluster(APPLICATION_ID);
    verify(descriptor).close();
}

